insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (1, 'DAM', 'DESPACHO ALCALDE MUNICIPAL', 'DIRECTIVO', 'DAM', 'SIN EJE', 'Formular políticas y estrategias orientadas a asegurar una gestión municipal eficiente y transparente, promoviendo el desarrollo del municipio, a través de la ejecución de planes, programas y proyectos concordantes con el Plan Territorial de Desarrollo Integral para Vivir Bien del municipio de La Paz, el Plan Estratégico Institucional y el Plan Operativo Anual, elevando los niveles de bienestar social de los ciudadanos, mediante la ejecución de obras y servicios de interés común, así como preservar, fomentar y difundir los valores culturales y las tradiciones cívicas.', 'Es la máxima autoridad ejecutiva del municipio: dirige y representa al Gobierno Autónomo Municipal de La Paz. || Firma y promulga Leyes Municipales, Decretos Municipales, Decretos Ediles y Resoluciones Ejecutivas, u observa las leyes cuando corresponde. || Presenta proyectos de ley al Concejo Municipal y define las políticas públicas del municipio. || Designa a secretarios municipales, subalcaldes, directores y máximas autoridades de empresas y entidades descentralizadas. || Aprueba mediante Decreto la estructura organizativa del Órgano Ejecutivo. || Conduce la gestión pública municipal y toma las decisiones de más alto nivel.', 'máxima autoridad ejecutiva, decreto municipal, decreto edil, resolución ejecutiva, promulgación de leyes, designación de autoridades, nombramiento de secretarios, nombramiento de subalcaldes, firma del alcalde, audiencia con el alcalde, estructura organizativa, veto, proyecto de ley municipal, dirección de la gestión municipal');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (2, 'US', 'UNIDAD SUMARIANTE', 'APOYO ESPECIALIZADO Y ASESORAMIENTO', 'DAM', 'SIN EJE', 'Garantizar la correcta sustanciación de los procesos sumarios administrativos disciplinarios, en estricto cumplimiento de la normativa vigente.', 'Instruye y lleva adelante procesos sumarios administrativos disciplinarios contra servidores públicos municipales. || Reúne y valora pruebas para determinar si existe responsabilidad administrativa, civil o penal según la Ley 1178. || Emite resoluciones fundamentadas que aplican sanciones (multa, suspensión, destitución) o disponen el archivo del caso. || Garantiza el debido proceso, el derecho a la defensa y la presunción de inocencia del funcionario investigado. || Coordina con otras unidades e instancias externas para investigar y resolver los casos.', 'proceso sumario, sumario administrativo, responsabilidad administrativa, responsabilidad civil, responsabilidad penal, sanción disciplinaria, destitución, suspensión de funciones, ley 1178, debido proceso, derecho a la defensa, servidor público, falta disciplinaria, auto inicial, resolución sumarial, descargos, prueba, archivo de obrados, sumariante, indicios de responsabilidad');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (3, 'UAI', 'UNIDAD DE AUDITORÍA INTERNA', 'APOYO ESPECIALIZADO Y ASESORAMIENTO', 'UAI', 'EJE-01', 'Ejercer el control gubernamental interno posterior en el Gobierno Autónomo Municipal de La Paz, en el marco de lo establecido por el artículo 15 de la Ley Nº 1178 de Administración y Control Gubernamentales y sus decretos reglamentarios.', 'Realiza auditorías internas (financieras, operativas, de sistemas, ambientales y de proyectos de inversión) a las dependencias del municipio. || Revisa el manejo de recursos públicos y verifica que se cumplan las leyes, contratos y normas administrativas. || Emite informes con hallazgos y recomendaciones para mejorar los controles internos, y los envía al Ejecutivo Municipal y a la Contraloría. || Da seguimiento a que las recomendaciones de auditoría se implementen realmente. || Detecta indicios de responsabilidad por la función pública cuando encuentra irregularidades. || Comprueba la confiabilidad de los registros y estados financieros del GAMLP y sus entes controlados.', 'auditoría interna, control gubernamental, contraloría, hallazgos, responsabilidad por la función pública, estados financieros, control interno, ley 1178, auditoría de sistemas, auditoría ambiental, auditoría de proyectos, seguimiento de recomendaciones, irregularidades, indicios de responsabilidad, fiscalización de recursos, informe de auditoría, relevamiento de información, confiabilidad de registros, eficacia eficiencia economía');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (4, 'UTLCC', 'UNIDAD DE TRANSPARENCIA Y LUCHA CONTRA LA CORRUPCIÓN', 'APOYO ESPECIALIZADO Y ASESORAMIENTO', 'UTLCC', 'EJE-01', 'Promover la transparencia municipal, la integridad, la ética institucional, la lucha contra la corrupción y su prevención, el acceso a la información y la cultura del buen trato en la gestión pública municipal, a través de la formulación e implementación de políticas, planes, programas, proyectos, estrategias, lineamientos y mecanismos de prevención, control, fortalecimiento institucional y desburocratización, en procura del cumplimiento eficaz de los objetivos de gestión, de la normativa municipal y nacional vigente, para la satisfacción de las necesidades de la ciudadanía y protección de sus derechos.', 'Recibe y da trámite a denuncias ciudadanas y de funcionarios por corrupción, faltas a la ética y mal uso de recursos municipales. || Investiga posibles irregularidades y remite los antecedentes con indicios de responsabilidad administrativa, civil o penal a las instancias competentes. || Redacta y propone normas municipales sobre transparencia, ética pública, acceso a la información y buen trato al ciudadano. || Organiza y coordina las audiencias públicas de rendición de cuentas del municipio con participación y control social. || Promueve el acceso transparente a la información municipal y campañas de integridad y cultura anticorrupción.', 'denuncia de corrupción, corrupción, transparencia, ética institucional, código de ética, acceso a la información, rendición de cuentas, control social, soborno, conflicto de intereses, buen trato, responsabilidad funcionaria, irregularidades, canal de denuncias, integridad pública, prevención de corrupción, malversación, queja contra funcionario, audiencia pública');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (5, 'DGEG', 'DIRECCIÓN DE GESTIÓN ESTRATÉGICA Y GABINETE', 'EJECUTIVO', 'DAM', 'SIN EJE', 'Gestionar de manera integral la agenda de actividades del Alcalde Municipal, supervisar y procesar el flujo documental de trámites y correspondencia a conocimiento y consideración del Alcalde Municipal, así como la documentación despachada por éste, a las instancias organizacionales del Ejecutivo Municipal, autoridades del Concejo Municipal, autoridades de los Órganos del Estado y ciudadanía en general; así también, administrar de manera integral los recursos de funcionamiento asignados al Despacho del Alcalde de acuerdo a las necesidades y requerimientos del mismo; además de planificar, organizar, conducir y supervisar todas las ceremonias protocolares del Gobierno Autónomo Municipal de La Paz.', 'Administra la agenda del Alcalde: programa reuniones, audiencias y actividades del Despacho. || Recibe, deriva y da seguimiento a la correspondencia y trámites que llegan al Alcalde y a los que él despacha. || Maneja el presupuesto y los gastos de funcionamiento del Despacho del Alcalde. || Organiza y conduce las ceremonias protocolares y actos oficiales del municipio. || Coordina y supervisa actividades administrativas, técnicas y financieras del Ejecutivo por instrucción del Alcalde. || Actúa como autoridad responsable de las contrataciones del Despacho del Alcalde.', 'agenda del alcalde, audiencias, reuniones del alcalde, correspondencia, trámites del despacho, protocolo, ceremonias oficiales, actos protocolares, presupuesto del despacho, gastos de funcionamiento, invitaciones oficiales, actividades del alcalde, máxima autoridad ejecutiva, correspondencia oficial, eventos oficiales, coordinación del ejecutivo');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (6, 'UGAP', 'UNIDAD DE GABINETE Y PROTOCOLO', 'OPERATIVO', 'DAM', 'SIN EJE', 'Coordinar y ejecutar acciones operativas de gabinete y protocolo.', 'Redacta y despacha oficios, órdenes de servicio, instrucciones ejecutivas y circulares que firma el Alcalde. || Recibe, registra, deriva y hace seguimiento a la correspondencia dirigida al Alcalde y al Concejo Municipal, con archivo y custodia. || Organiza la logística y el ceremonial de eventos, actos protocolares y efemérides del municipio (acto del 16 de julio, aniversarios, inauguraciones). || Coordina la agenda protocolar del Alcalde: ceremonias, entrega de obras, firma de convenios, condecoraciones y distinciones. || Atiende y recibe delegaciones y personalidades internacionales según normas de protocolo. || Articula el ceremonial con la Presidencia, la Asamblea Legislativa y el Ceremonial del Estado.', 'protocolo, ceremonial, acto protocolar, efeméride 16 de julio, aniversario de la paz, invitaciones oficiales, agenda del alcalde, oficios, circulares, instrucciones ejecutivas, correspondencia del alcalde, delegaciones internacionales, distinciones y condecoraciones, inauguración de obras, firma de convenios, izamiento de bandera, maestro de ceremonias, presentes de honor, recepción de autoridades');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (7, 'UAEMC', 'UNIDAD DE ASUNTOS ESTRATÉGICOS Y MEJORA CONTINUA', 'OPERATIVO', 'DAM', 'SIN EJE', 'Realizar el seguimiento estratégico a la gestión municipal, y gestionar acciones de mejora continua orientadas al cumplimiento efectivo de resultados.', 'Da seguimiento a los temas estratégicos y prioritarios de la gestión municipal en todas las áreas. || Detecta cuellos de botella y propone acciones concretas de mejora continua de procesos. || Articula con las distintas unidades para que las decisiones estratégicas se cumplan y muestren resultados. || Elabora reportes de avance e indicadores para la autoridad sobre el cumplimiento de metas.', 'seguimiento estratégico, mejora continua, optimización de procesos, indicadores de gestión, cumplimiento de metas, resultados institucionales, monitoreo de avance, eficiencia municipal, planificación estratégica, reportes de desempeño, reingeniería de procesos, tablero de control, cuellos de botella, análisis de gestión');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (8, 'DC', 'DIRECCIÓN DE COMUNICACIÓN', 'EJECUTIVO', 'DAM', 'SIN EJE', 'Socializar, a través de medios masivos y herramientas tecnológicas y en coordinación con las áreas y unidades organizacionales, las políticas, programas, proyectos y acciones que realiza el Gobierno Autónomo Municipal de La Paz para acercar la gestión a la gente y fomentar la participación ciudadana, garantizando el derecho al acceso a la información pública y consolidando la imagen institucional eficiente, transparente y de servicio a la comunidad.', 'Diseña y ejecuta la estrategia de comunicación del municipio: campañas, mensajes y difusión de obras, programas y actividades. || Produce y aprueba piezas comunicacionales (spots, videos, afiches, gigantografías, boletines, contenido web y redes) cuidando la imagen institucional. || Administra las redes sociales oficiales y responde/interactúa con la ciudadanía para acercar la gestión a la gente. || Define y controla el uso correcto del logotipo, colores y marca del GAMLP en todas las unidades y empresas municipales. || Da apoyo técnico de prensa, protocolo comunicacional y vocería a las demás áreas del municipio. || Informa a autoridades y funcionarios sobre políticas, hechos públicos y decisiones institucionales.', 'comunicacion, prensa, spot publicitario, campaña comunicacional, redes sociales, facebook, afiche, gigantografia, diseño grafico, logotipo, imagen institucional, marca gamlp, difusion, boletin de prensa, conferencia de prensa, video institucional, vocería, manual de marca, banner, contenido digital');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (9, 'UPVCE', 'UNIDAD DE PRENSA, VOCERÍA Y CONTENIDOS ESTRATÉGICOS', 'OPERATIVO', 'DAM', 'SIN EJE', 'Informar a la población de manera plural sobre las actividades del Gobierno Autónomo Municipal de La Paz a través de medios de comunicación, propios y externos, para transparentar y promocionar la gestión municipal promoviendo un relacionamiento respetuoso y fluido entre autoridades y medios de comunicación.', 'Redacta y difunde notas de prensa, reportajes y contenidos sobre las actividades del municipio en medios propios y externos. || Organiza conferencias de prensa, gestiona entrevistas a autoridades y coordina la cobertura de actos ediles. || Publica noticias diarias en la Agencia Municipal de Noticias (amun.bo) y produce periódico, microprogramas de radio y TV. || Supervisa la redacción y el diseño de materiales impresos y digitales institucionales. || Monitorea la presencia del municipio en radio, TV, prensa y redes sociales, y genera reportes para la toma de decisiones. || Coordina la relación entre las autoridades municipales y los medios de comunicación.', 'prensa, comunicación, nota de prensa, boletín informativo, conferencia de prensa, entrevista, vocería, cobertura de eventos, agencia municipal de noticias, amun.bo, redes sociales, monitoreo de medios, periódico municipal, microprograma, acreditación de periodistas, fotografía y video institucional, difusión, comunicado oficial, contenidos digitales, clipping');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (10, 'UGD', 'UNIDAD DE GESTIÓN DIGITAL', 'OPERATIVO', 'DAM', 'SIN EJE', 'Socializar las actividades del Gobierno Autónomo Municipal de La Paz a través de las redes sociales para transparentar y promocionar la gestión municipal aperturando nuevos canales de participación democrática y atención e interacción ciudadana.', 'Administra las cuentas oficiales del municipio en redes sociales (Facebook, X, Instagram, YouTube, TikTok y otras). || Publica y actualiza contenido para difundir servicios, obras y actividades del GAMLP. || Produce piezas gráficas, textos y material audiovisual para las redes institucionales. || Responde e interactúa con la ciudadanía en línea y canaliza sus consultas y quejas a las áreas responsables. || Mide el alcance e impacto de las publicaciones y evalúa la interacción ciudadana. || Define protocolos y da apoyo técnico a otras unidades para el uso responsable de sus redes.', 'redes sociales, facebook, instagram, twitter, tiktok, youtube, community manager, publicación, post, contenido digital, piezas gráficas, audiovisual, difusión digital, interacción ciudadana, cuentas oficiales, campaña en redes, seguidores, alcance, reels, historias, moderación de comentarios, hashtag, comunicación digital');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (11, 'UCIE', 'UNIDAD DE COMUNICACIÓN INTERNA Y EXTERNA', 'OPERATIVO', 'DAM', 'SIN EJE', 'Socializar políticas, proyectos y acciones del Gobierno Autónomo Municipal de La Paz a favor de la ciudadanía con productos y mecanismos de comunicación que permitan la interacción entre la institución y los públicos internos y externos para transparentar la gestión y fortalecer la imagen institucional.', 'Produce spots de TV, cuñas de radio, videos, documentales y transmisiones en vivo sobre obras, programas y servicios del municipio. || Difunde el material en medios masivos, pantallas de plataformas de atención, transporte municipal y subalcaldías. || Monitorea diariamente las noticias sobre el GAMLP y alerta a las unidades cuando corresponde responder. || Coordina los contenidos de los medios online junto con la Unidad de Gestión Digital. || Revisa la calidad de los materiales de comunicación que elaboran otras áreas del municipio. || Establece canales de interacción y retroalimentación entre la Alcaldía y la ciudadanía.', 'comunicación, prensa, spot, cuña radial, video institucional, transmisión en vivo, streaming, redes sociales, monitoreo de noticias, boletín de prensa, difusión, imagen institucional, medios masivos, pantallas, campaña comunicacional, cobertura, documental, vocería, contenido audiovisual, minimedios');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (12, 'DGT', 'DIRECCIÓN DE GOBERNANZA DEL TERRITORIO', 'EJECUTIVO', 'DAM', 'SIN EJE', 'Brindar asesoramiento al Alcalde Municipal en la construcción de consensos con actores públicos, privados y sociales; promover la participación ciudadana; coordinar acciones territoriales con las Subalcaldías; con el propósito de garantizar la efectividad de las políticas públicas que fortalezcan la gobernabilidad democrática en el municipio.', 'Asesora al Alcalde en el diálogo y construcción de acuerdos con organizaciones sociales, juntas vecinales y actores políticos. || Organiza las Asambleas de la Paceñidad, consultas ciudadanas y referendos municipales. || Coordina la relación con el Control Social y registra y da seguimiento a los acuerdos alcanzados con las organizaciones. || Detecta a tiempo conflictos sociales y ayuda a resolverlos junto con otras áreas del municipio. || Atiende visitas de delegaciones de otros gobiernos municipales y representa al Alcalde en actos delegados. || Supervisa la ejecución del POA y del Fondo de Atención Ciudadana de las Subalcaldías.', 'gobernabilidad, participación ciudadana, control social, organizaciones sociales, juntas vecinales, asamblea de la paceñidad, consulta ciudadana, referendo municipal, conflicto social, diálogo, acuerdos vecinales, subalcaldías, fondo de atención ciudadana, poa subalcaldías, delegaciones, mediación de conflictos, relaciones intergubernamentales, actores sociales');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (13, 'UPCSO', 'UNIDAD DE PARTICIPACIÓN Y CONTROL SOCIAL ORGANIZADO', 'OPERATIVO', 'DAM', 'SIN EJE', 'Diseñar, implementar y coordinar políticas, estrategias e instrumentos que coadyuven en la prevención, monitoreo y resolución de conflictos, así como en la promoción de la participación de la sociedad civil organizada en la gestión municipal, con el objetivo de fortalecer tanto el proceso de gobernabilidad democrática como el ejercicio de la ciudadanía plena en el municipio de La Paz.', 'Previene, monitorea y media conflictos sociales que afectan al municipio. || Registra la conflictividad en un sistema informático y reporta al Alcalde periódicamente. || Da seguimiento a los compromisos que el municipio asume para resolver conflictos. || Promueve la participación de juntas vecinales y organizaciones sociales en la gestión municipal. || Organiza espacios de participación ciudadana, consultas y referendos municipales. || Capacita a organizaciones vecinales y mantiene el mapa de actores sociales del municipio.', 'conflictos sociales, control social, participación ciudadana, juntas vecinales, organizaciones sociales, mediación, resolución de conflictos, diálogo, bloqueos, marchas, protestas, consulta ciudadana, referendo municipal, mapa de actores, compromisos sociales, gobernabilidad, sociedad civil, dirigentes vecinales, conflictividad municipal, acuerdos sociales');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (14, 'UCT', 'UNIDAD DE COORDINACIÓN TERRITORIAL', 'OPERATIVO', 'DAM', 'SIN EJE', 'Coordinar acciones con y entre las Subalcaldías urbanas y rurales del municipio, facilitando la articulación de procesos y procedimientos con otras áreas y unidades organizacionales del Gobierno Autónomo Municipal de La Paz, para optimizar la ejecución de planes, proyectos y servicios municipales.', 'Articula el trabajo entre las Subalcaldías urbanas y rurales y las Secretarías Municipales. || Hace seguimiento y evalúa la ejecución del POA de cada Subalcaldía y reporta al Alcalde. || Mantiene el contacto directo entre el Alcalde y los Subalcaldes para destrabar proyectos macrodistritales, distritales y barriales. || Controla la asignación y ejecución de los recursos del Fondo de Atención Ciudadana en cada macrodistrito. || Lleva un registro georreferenciado de organizaciones vecinales y sociales. || Evalúa el desempeño de las Subalcaldías y presenta informes de resultados.', 'subalcaldías, macrodistritos, coordinación territorial, fondo de atención ciudadana, poa subalcaldías, proyectos barriales, proyectos distritales, seguimiento a subalcaldías, juntas vecinales, organizaciones sociales, recursos concertados, desempeño subalcaldías, articulación con secretarías, obras macrodistritales, registro georreferenciado, subalcalde, demandas vecinales, distritos municipales, reportes al alcalde');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (15, 'UGM', 'UNIDAD GUARDIA MUNICIPAL', 'OPERATIVO', 'DAM', 'SIN EJE', 'Desarrollar tareas de prevención y protección social, comunitaria y situacional, de atención de emergencias y apoyo operativo a otras unidades organizacionales del Gobierno Autónomo Municipal de La Paz, en forma articulada y coordinada con la Policía Boliviana, contribuyendo a la seguridad ciudadana de manera proactiva, dando cumplimiento a disposiciones y normativa vigente; así como constituir la instancia operativa de la Autoridad Municipal de Transporte y Tránsito para el control del sistema de movilidad en el municipio de La Paz.', 'Ejecuta el Plan Municipal de Seguridad Ciudadana con patrullaje y prevención de la violencia y el delito. || Atiende emergencias que afectan a los vecinos y apoya operativamente a otras unidades del municipio. || Controla el comercio en aceras y calzadas, realizando decomisos ante infracciones flagrantes y depositándolos en almacén. || Ejecuta operativos de control de expendio y consumo de bebidas alcohólicas en locales, discotecas y whiskerías. || Custodia el ornato público y los bienes municipales, coordinando con la Policía Boliviana. || Actúa como brazo operativo del control de tránsito y movilidad en la ciudad, con personal uniformado capacitado.', 'guardia municipal, seguridad ciudadana, patrullaje, decomiso, comercio en vía pública, ambulantes, control de alcohol, operativos nocturnos, discotecas, whiskerías, orden público, emergencias vecinales, apoyo operativo, control de tránsito, personal uniformado, prevención del delito, aceras y calzadas, bienes municipales, avasallamiento de espacios, resguardo de eventos');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (16, 'DEESPM', 'DIRECCIÓN DE EMPRESAS, ENTIDADES Y SERVICIOS PÚBLICOS MUNICIPALES', 'EJECUTIVO', 'DAM', 'SIN EJE', 'Coordinar la planificación, ejecución y logro de efectos, resultados y actividades de las Empresas y Entidades Descentralizadas Municipales con el propósito de que logren un desempeño adecuado; así como administrar, supervisar y efectuar el seguimiento a los servicios públicos municipales, y regular los servicios públicos de administración privada, aplicando planes, políticas y estrategias que garanticen la eficiente prestación de los mismos.', 'Coordina y hace seguimiento al desempeño de las empresas y entidades descentralizadas municipales. || Preside directorios de empresas municipales por delegación del Alcalde y articula su relación con el Despacho. || Supervisa y administra los servicios públicos municipales y regula los de administración privada. || Recauda ingresos por baños públicos (servicios higiénicos municipales) y parqueos, con control diario de la recaudación. || Controla y fiscaliza los baños públicos privados y verifica el cumplimiento normativo. || Propone y da seguimiento a proyectos de mejora y mantenimiento de la infraestructura de servicios públicos. || Emite informes semanales, mensuales y anuales de ingresos y ejecución presupuestaria.', 'empresas municipales, entidades descentralizadas, servicios publicos municipales, baños publicos, servicios higienicos, parqueos, parquimetro, recaudacion, directorio, fiscalizacion de servicios, concesion de servicios, sanitarios publicos, playa de estacionamiento, ingresos municipales, infraestructura de servicios, empresa descentralizada, regulacion de servicios, seguimiento empresarial');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (17, 'DAJ', 'DIRECCIÓN DE ASUNTOS JURÍDICOS', 'EJECUTIVO', 'DAM', 'SIN EJE', 'Gestionar la defensa jurídica integral y el asesoramiento legal del Gobierno Autónomo Municipal de La Paz, a través de la producción normativa, el patrocinio institucional y el análisis técnico-legal, a través de las áreas y unidades organizacionales especializadas bajo su dependencia.', 'Brinda asesoramiento legal a las áreas del municipio que no cuentan con abogado propio. || Revisa y valida proyectos de leyes, decretos, convenios y contratos antes de su firma o remisión al Concejo. || Atiende y resuelve los recursos administrativos planteados ante el Alcalde. || Patrocina y da seguimiento a procesos civiles, penales, laborales, contenciosos y coactivos fiscales donde el municipio es parte. || Supervisa procesos de expropiación por necesidad o utilidad pública. || Gestiona enajenaciones, transferencias de terrenos, levantamientos de gravámenes y la protocolización de minutas ante la Notaría de Gobierno. || Responde peticiones de informe y solicitudes de fiscalización del Concejo Municipal y la Asamblea Legislativa.', 'asesoría legal, defensa jurídica, recurso administrativo, convenio, contrato, expropiación, proceso judicial, proceso penal, proceso civil, coactivo fiscal, minuta, protocolización, notaría de gobierno, transferencia de terreno, enajenación, levantamiento de gravamen, dictamen legal, proyecto normativo, petición de informe, propiedad municipal, patrocinio legal');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (18, 'UALN', 'UNIDAD DE ANÁLISIS LEGAL Y NORMATIVO', 'OPERATIVO', 'DAM', 'SIN EJE', 'Proyectar, analizar, revisar y gestionar proyectos normativos inherentes al ámbito municipal hasta su aprobación, para el ejercicio pleno de las competencias del Gobierno Autónomo Municipal de La Paz, revisando normas de carácter nacional y departamental, vinculadas a las atribuciones y competencias municipales.', 'Elabora y revisa proyectos de leyes municipales, decretos, ordenanzas y resoluciones para el Alcalde y el Concejo Municipal. || Revisa convenios y acuerdos con instituciones públicas, privadas, nacionales e internacionales antes de su firma. || Analiza normativa nacional y departamental para verificar su relación con las competencias municipales. || Sistematiza y mantiene actualizada la base de normativa municipal para consulta confiable. || Brinda asesoramiento legal a unidades que no tienen asesor propio y atiende recursos administrativos ante el Alcalde. || Gestiona expropiaciones, enajenaciones, transferencias de predios y levantamiento de gravámenes ante la Notaría de Gobierno. || Atiende peticiones de informe y solicitudes de fiscalización del Concejo Municipal y la Asamblea Legislativa.', 'proyecto de ley municipal, decreto municipal, ordenanza, resolución municipal, convenio, asesoramiento legal, recurso administrativo, recurso jerárquico, expropiación, enajenación, transferencia de predios, levantamiento de gravamen, minuta, notaría de gobierno, petición de informe, fiscalización, análisis normativo, compilación legal, concejo municipal, instrumento de relacionamiento, utilidad pública');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (19, 'UPJ', 'UNIDAD DE PROCESOS JURISDICCIONALES', 'OPERATIVO', 'DAM', 'SIN EJE', 'Patrocinar y hacer seguimiento eficiente a procesos judiciales y constitucionales, procesos civiles, penales y coactivos fiscales, procesos contenciosos y contenciosos administrativos; así como atender recursos y acciones constitucionales en las que el Órgano Ejecutivo del Gobierno Autónomo Municipal de La Paz participe como parte interesada, o en cualquier otra condición. Asimismo, patrocinar a las servidoras y los servidores públicos municipales electos, no electos, de carrera administrativa municipal y eventuales que se encuentren en funciones en el Órgano Ejecutivo del Gobierno Autónomo Municipal de La Paz, en los procesos judiciales penales que se instauren por delitos cometidos y actos producidos en el ejercicio de sus funciones y que no cuenten con patrocinio particular, previo análisis del caso.', 'Defiende al Ejecutivo Municipal en procesos judiciales: civiles, penales, contenciosos, contencioso-administrativos y coactivos fiscales. || Patrocina recursos y acciones constitucionales (amparos y similares) en los que participa el municipio. || Defiende legalmente a servidores públicos municipales por actos cometidos en el ejercicio de sus funciones cuando no cuentan con abogado particular. || Elabora informes sobre el estado de los procesos judiciales a su cargo. || Atiende solicitudes de fiscalización y pedidos de informe del Concejo Municipal y la Asamblea Legislativa sobre las causas que patrocina. || Remite reportes de los procesos jurisdiccionales a la Contraloría General del Estado.', 'proceso judicial, juicio, demanda, abogado, patrocinio legal, acción constitucional, amparo constitucional, proceso penal, proceso civil, coactivo fiscal, contencioso administrativo, defensa legal, querella, audiencia, propiedad municipal en litigio, servidor público procesado, derechos reales judicial, recurso constitucional, tribunal');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (20, 'UAJI', 'UNIDAD DE ASESORÍA JURÍDICA INSTITUCIONAL', 'OPERATIVO', 'DAM', 'SIN EJE', 'Brindar asesoramiento jurídico institucional especializado en materia laboral al Órgano Ejecutivo Municipal, así como gestionar, atender, sustanciar, hacer seguimiento y coadyuvar en la defensa de procesos laborales, administrativos laborales, constitucionales de naturaleza laboral y coactivos sociales en los que sea parte el Gobierno Autónomo Municipal de La Paz, conforme a la normativa vigente y en resguardo de los intereses institucionales.', 'Defiende al municipio en demandas y procesos laborales ante juzgados, el Ministerio de Trabajo y la vía constitucional. || Tramita y da seguimiento a procesos coactivos sociales por aportes, seguridad social y obligaciones laborales. || Asesora en materia laboral a las áreas que no tienen abogado propio sobre estabilidad, reincorporaciones y beneficios sociales. || Atiende conminatorias de reincorporación, reclamos de beneficios sociales y salarios devengados del personal municipal. || Controla los plazos procesales de todos los casos laborales asignados a la unidad.', 'proceso laboral, demanda laboral, ministerio de trabajo, reincorporación, beneficios sociales, salarios devengados, coactivo social, estabilidad laboral, conminatoria, derechos laborales, asesoría jurídica laboral, despido, seguridad social, aportes, defensa institucional, amparo constitucional laboral, régimen funcionarial, abogado laboral');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (21, 'DRICA', 'DIRECCIÓN DE RELACIONES INTERNACIONALES, COOPERACIÓN Y ALIANZAS', 'EJECUTIVO', 'DAM', 'SIN EJE', 'Proyectar y posicionar al Gobierno Autónomo Municipal de La Paz a nivel nacional e internacional como referente de innovación humana y valor público, mediante la gestión de la diplomacia urbana, la captación de recursos de cooperación técnica y financiera, la estructuración de alianzas público-privadas y la transferencia de conocimiento, transformando oportunidades externas en recursos concretos, inversión y bienestar para la ciudadanía paceña.', 'Posiciona a La Paz a nivel nacional e internacional mediante diplomacia urbana. || Gestiona relaciones con embajadas, redes de ciudades, gobiernos extranjeros y organismos de cooperación. || Administra la membresía del municipio en redes internacionales y prevé el pago de cuotas. || Busca financiamiento no reembolsable, donaciones en especie y cooperación técnica. || Coordina con la Cancillería y misiones diplomáticas. || Estructura alianzas público-privadas y transferencia de conocimiento con socios externos.', 'relaciones internacionales, cooperación internacional, diplomacia urbana, hermanamiento de ciudades, redes de ciudades, embajadas, cancillería, financiamiento no reembolsable, donaciones en especie, cooperación técnica, organismos internacionales, convenios internacionales, membresías, cuotas internacionales, alianzas, delegaciones extranjeras, misiones diplomáticas, fondos externos, ciudades hermanas, metropolitano, área metropolitana, región metropolitana, encuentro de alcaldes, mancomunidad, municipios vecinos, El Alto, Viacha, Palca, Mecapaca, Achocalla, coordinación metropolitana, agenda metropolitana');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (22, 'UCAE', 'UNIDAD DE COOPERACIÓN Y ALIANZAS ESTRATÉGICAS', 'OPERATIVO', 'DAM', 'SIN EJE', 'Gestionar la recepción y oferta de cooperación técnica y financiera, estructurando alianzas público-privadas y movilizando esquemas de financiamiento innovadores, articulando fuentes externas con la cartera de proyectos prioritarios del Gobierno Autónomo Municipal de La Paz y generando impacto medible en la calidad de vida de la ciudadanía paceña.', 'Gestiona y capta cooperación internacional no reembolsable, asistencia técnica y donaciones en especie para proyectos municipales. || Arma y mantiene la cartera de proyectos que buscan financiamiento externo. || Mapea y perfila cooperantes, socios estratégicos y aliados internacionales. || Estructura alianzas público-privadas (APP) con empresas para movilizar inversión. || Ayuda a las unidades a adecuar sus proyectos a los formatos técnicos, legales y financieros que pide cada cooperante. || Gestiona la firma de convenios de cooperación con embajadas, organismos y agencias.', 'cooperación internacional, donaciones, asistencia técnica, financiamiento no reembolsable, alianzas público-privadas, app, convenios de cooperación, embajadas, organismos internacionales, cartera de proyectos, cooperantes, aliados estratégicos, fondos externos, donación en especie, sector privado, financiamiento de proyectos, agencias de cooperación, inversión privada, captación de recursos');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (23, 'URI', 'UNIDAD DE RELACIONES INTERNACIONALES', 'OPERATIVO', 'DAM', 'SIN EJE', 'Coadyuvar al establecimiento y fortalecimiento de las relaciones internacionales del Gobierno Autónomo Municipal de La Paz con embajadas, delegaciones diplomáticas, redes internacionales, organismos de cooperación y gobiernos locales del exterior, posicionando estratégicamente a La Paz en el contexto global y profundizando vínculos de amistad, hermanamiento y cooperación.', 'Gestiona vínculos con embajadas, cuerpo diplomático, agencias de cooperación y redes de ciudades del exterior. || Promueve hermanamientos con gobiernos locales extranjeros y da seguimiento a los acuerdos suscritos. || Coordina agendas bilaterales y la participación de La Paz en foros y redes internacionales. || Prevé y paga cuotas de membresía en redes internacionales, y revisa proyectos ante organismos de cooperación. || Organiza y coordina los viajes al exterior del Alcalde y servidores públicos municipales. || Apoya la logística de eventos internacionales y la recepción de delegaciones extranjeras.', 'relaciones internacionales, cooperación internacional, hermanamiento de ciudades, embajadas, cuerpo diplomático, diplomacia urbana, redes de ciudades, foros internacionales, convenios internacionales, membresías internacionales, cuotas de red, viajes al exterior, delegaciones extranjeras, agendas bilaterales, protocolo internacional, proyectos de cooperación, financiamiento internacional, posicionamiento global');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (24, 'SEMGE', 'SECRETARÍA EJECUTIVA MUNICIPAL DE GESTIÓN EFICIENTE', 'EJECUTIVO', 'SEMGE', 'EJE-01', 'Implementar y promover políticas y estrategias que aseguren una gestión municipal eficiente y efectiva, mediante el seguimiento, coordinación y monitoreo de las áreas y unidades organizacionales, para garantizar la ejecución exitosa de planes, programas y proyectos; implementar a través de las Direcciones bajo su dependencia los sistemas de administración gubernamental, y efectuar los procesos de supervisión y fiscalización.', 'Coordina las reuniones de Gabinete del Alcalde y da seguimiento a las decisiones tomadas. || Articula a todas las áreas del Ejecutivo Municipal para que se cumplan los planes, programas y proyectos de la gestión. || Monitorea el avance y cumplimiento de metas de las unidades organizacionales. || Convoca reuniones ejecutivas para tratar temas técnicos, financieros, operativos y administrativos. || Emite Órdenes de Servicio de cumplimiento obligatorio para lograr los objetivos institucionales. || Implementa los sistemas de administración gubernamental a través de sus direcciones.', 'gestion eficiente, reunion ejecutiva, orden de servicio, seguimiento de gestion, monitoreo, cumplimiento de metas, coordinacion ejecutiva, planes programas proyectos, sistemas de administracion, supervision institucional, fiscalizacion, secretaria ejecutiva, maxima autoridad ejecutiva, poa, directrices ejecutivas');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (25, 'DPRIGR', 'DIRECCIÓN DE PLANIFICACIÓN, REFORMA INSTITUCIONAL Y GESTIÓN POR RESULTADOS', 'EJECUTIVO', 'SEMGE', 'EJE-01', 'Implementar el Sistema de Planificación Integral del Estado a través de la formulación, implementación, seguimiento y evaluación del Plan Territorial de Desarrollo Integral (PTDI) para Vivir Bien del municipio de La Paz y del Plan Estratégico Institucional (PEI); implantar el Sistema de Programación de Operaciones (SPO) y el Sistema de Organización Administrativa (SOA) en el Órgano Ejecutivo Municipal de La Paz; así como efectuar la sistematización y producción de información estadística, geográfica y cartográfica oficial del municipio, sobre cuya base serán desarrollados indicadores e investigaciones municipales para la toma de decisiones de políticas públicas.', 'Formula, implementa y da seguimiento al Plan Territorial de Desarrollo Integral (PTDI) y al Plan Estratégico Institucional (PEI). || Coordina la planificación municipal con las distintas áreas y con actores territoriales, nacionales y departamentales. || Implanta el Sistema de Programación de Operaciones (SPO) y el Sistema de Organización Administrativa (SOA) en el municipio. || Produce y sistematiza información estadística, geográfica y cartográfica oficial del municipio. || Genera indicadores e investigaciones que sustentan la toma de decisiones de políticas públicas.', 'planificación, ptdi, pei, poa, plan operativo anual, programación de operaciones, organización administrativa, reforma institucional, gestión por resultados, indicadores, estadísticas municipales, información geográfica, cartografía, manual de organización y funciones, reglamento específico, seguimiento y evaluación, plan estratégico, estructura organizacional, diagnóstico municipal');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (26, 'UPIOA', 'UNIDAD DE PLANIFICACIÓN INTEGRAL Y ORGANIZACIÓN ADMINISTRATIVA', 'OPERATIVO', 'SEMGE', 'EJE-01', 'Coordinar la formulación, implementación, seguimiento, evaluación y ajuste del Plan Territorial de Desarrollo Integral (PTDI) para Vivir Bien del municipio de La Paz con un enfoque integrado, armónico y articulado a la planificación nacional, departamental y sectorial y coordinar la formulación, implementación, seguimiento, evaluación y ajuste del Plan Estratégico Institucional (PEI) del Gobierno Autónomo Municipal de La Paz en el marco del Sistema de Planificación Integral del Estado; así también implantar el Sistema de Organización Administrativa (SOA) en función de las características y necesidades de la institución, promoviendo el desempeño eficiente de la gestión municipal, en el marco del desarrollo organizacional; y coordinar la compatibilización de los Reglamentos Específicos de los Sistemas de la Ley Nº 1178 de Administración y Control Gubernamentales.', 'Coordina la formulación, seguimiento y ajuste del Plan Territorial de Desarrollo Integral (PTDI) del municipio. || Formula y da seguimiento al Plan Estratégico Institucional (PEI) del GAMLP. || Diseña y rediseña la estructura organizacional del municipio en el marco del Sistema de Organización Administrativa (SOA). || Elabora y actualiza el Manual de Organización y Funciones (MOF) del Órgano Ejecutivo Municipal. || Socializa, capacita y difunde los planes de desarrollo con áreas internas y entidades externas. || Compatibiliza los reglamentos específicos de los sistemas de la Ley 1178.', 'ptdi, plan territorial de desarrollo integral, pei, plan estratégico institucional, planificación integral, sistema de organización administrativa, soa, re-soa, manual de organización y funciones, mof, estructura organizacional, organigrama, rediseño organizacional, reglamento específico, ley 1178, vivir bien, desarrollo organizacional, planificación municipal, seguimiento de planes, cargos y funciones');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (27, 'UPOAIP', 'UNIDAD DE PLANIFICACIÓN OPERATIVA ANUAL E INVERSIÓN PÚBLICA', 'OPERATIVO', 'SEMGE', 'EJE-01', 'Coordinar el proceso de formulación del Plan Operativo Anual (POA) para brindar soporte a la gestión integral de políticas públicas municipales a través del seguimiento periódico a las acciones de corto plazo; y brindar lineamientos para la ejecución de los proyectos de inversión pública en lo referente al SISIN Web, y realizar el seguimiento a la ejecución financiera de la inversión pública municipal, a través de herramientas de gestión para el soporte a la toma de decisiones de las autoridades.', 'Coordina la formulación del Plan Operativo Anual (POA) con todas las áreas y unidades ejecutoras del municipio. || Gestiona las modificaciones y reformulaciones al POA durante la gestión. || Da soporte técnico a las unidades en el uso del Sistema de Inversión Municipal (SIM) y el SISIN Web. || Hace seguimiento a los avances administrativo, físico y financiero de la inversión pública. || Elabora la Caja de Herramientas como instrumento de planificación del POA. || Brinda lineamientos para la ejecución de proyectos de inversión pública.', 'poa, plan operativo anual, inversión pública, sisin, sisin web, sistema de inversión municipal, formulación del poa, modificación del poa, reformulado, ejecución presupuestaria, avance físico financiero, preinversión, proyectos de inversión, caja de herramientas, planificación operativa, seguimiento poa, programación anual, asistencia técnica poa');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (28, 'UIIEM', 'UNIDAD DE INVESTIGACIÓN, INFORMACIÓN Y ESTADÍSTICA MUNICIPAL', 'OPERATIVO', 'SEMGE', 'EJE-01', 'Recopilar, procesar y analizar los datos primarios generados a través de registros administrativos, censos y encuestas municipales para la producción de instrumentos estadísticos y geográficos que permitan la construcción y estimación de indicadores e índices municipales.', 'Recopila, procesa y analiza datos de censos, encuestas y registros administrativos del municipio. || Produce las estadísticas, indicadores e índices oficiales del municipio de La Paz. || Diseña y aplica encuestas y levantamientos de información primaria en coordinación con las áreas municipales. || Elabora mapas temáticos y cartografía con enfoque estadístico y geoespacial. || Administra los metadatos y la red de estadísticas municipales, articulando datos entre todas las unidades. || Publica documentos de análisis estadístico e insumos para la formulación del POA.', 'estadística municipal, indicadores, índices, censo, encuesta, datos, cartografía temática, geoespacial, geomática, mapas temáticos, metadatos, análisis estadístico, registros administrativos, información municipal, base de datos, levantamiento de información, indicadores de desempeño, datos primarios, estadísticas sectoriales');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (29, 'DF', 'DIRECCIÓN DE FINANZAS', 'EJECUTIVO', 'SEMGE', 'EJE-01', 'Gestionar los Sistemas Financieros de Presupuesto y Contabilidad Integrada, Tesorería del Estado y Crédito Público, a través de la emisión de normativa específica para la generación de la información financiera que muestre los resultados de la gestión presupuestaria, económica y situación patrimonial del Gobierno Autónomo Municipal de La Paz.', 'Gestiona los sistemas financieros del municipio: presupuesto, contabilidad, tesorería y crédito público. || Elabora y valida reglamentos, normas y procedimientos financieros internos. || Dirige la formulación del presupuesto institucional y sus modificaciones. || Vela por el cumplimiento tributario ante el Servicio de Impuestos Nacionales. || Brinda asistencia técnica financiera a direcciones y unidades ejecutoras.', 'finanzas, presupuesto, contabilidad integrada, tesorería, crédito público, modificaciones presupuestarias, estados financieros, impuestos nacionales, obligaciones tributarias, ejecución presupuestaria, formulación presupuestaria, reglamentos financieros, patrimonio municipal, pagos, deuda pública, normativa financiera, asistencia financiera, unidades ejecutoras');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (30, 'UP', 'UNIDAD DE PRESUPUESTO', 'OPERATIVO', 'SEMGE', 'EJE-01', 'Administrar la gestión presupuestaria de las áreas y unidades organizacionales del Gobierno Autónomo Municipal de La Paz, a través de la formulación y las modificaciones presupuestarias, además de realizar la evaluación y seguimiento de la ejecución presupuestaria, dando cumplimiento al Reglamento Específico de Presupuesto y normativa vigente.', 'Formula el presupuesto institucional anual del municipio y prepara su estructura programática. || Tramita y emite informes para las modificaciones presupuestarias solicitadas por las unidades. || Hace seguimiento a la ejecución presupuestaria de cada Dirección y Unidad Ejecutora. || Elabora informes cuatrimestrales de ejecución y los estados de recursos y gastos para los estados financieros. || Brinda asesoría y apoyo técnico en el Sistema de Presupuesto a autoridades y técnicos. || Elabora y actualiza el Reglamento Específico del Sistema de Presupuesto.', 'presupuesto, presupuesto institucional, modificaciones presupuestarias, ejecución presupuestaria, estructura programática, poa y presupuesto, reformulado, partidas presupuestarias, traspaso de partidas, certificación presupuestaria, unidad ejecutora, reglamento de presupuesto, estados financieros, recursos y gastos, formulación presupuestaria, techo presupuestario, informe cuatrimestral, disponibilidad presupuestaria, sigep, reprogramación');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (31, 'UCON', 'UNIDAD DE CONTABILIDAD', 'OPERATIVO', 'SEMGE', 'EJE-01', 'Administrar el Sistema de Contabilidad Integrada emitiendo los Estados Financieros Básicos Comparativos, Estados de Cuentas y otra información complementaria del Gobierno Autónomo Municipal de La Paz; así como Estados Financieros Consolidados con sus Entes Controlados para obtener y procesar la información que permita conocer la situación financiera del Gobierno Autónomo Municipal y ser presentada ante los Entes Fiscalizadores y las Máximas Autoridades del Ejecutivo Municipal de manera oportuna, dirigida a la toma de decisiones y al cierre de cada Ejercicio Fiscal.', 'Administra el Sistema de Contabilidad Integrada y elabora los Estados Financieros del municipio. || Emite estados financieros mensuales, cuatrimestrales y de cierre de gestión para fiscalizadores y autoridades. || Consolida los estados financieros del municipio con sus entes controlados. || Registra transacciones y comprobantes C-21 en el SIGEP por recaudaciones, alquileres y transferencias. || Concilia saldos de cuentas contables patrimoniales y controla depósitos a la Cuenta Única Municipal. || Actualiza el Reglamento Específico del Sistema de Contabilidad Integrada.', 'contabilidad, estados financieros, sistema de contabilidad integrada, sigep, comprobante c-21, cierre de gestión, registros contables, cuentas patrimoniales, conciliación contable, cuenta única municipal, balance general, estados consolidados, entes controlados, recaudaciones, rendición de cuentas, información financiera, ejecución de recursos, reglamento contable');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (32, 'UT', 'UNIDAD DE TESORERÍA', 'OPERATIVO', 'SEMGE', 'EJE-01', 'Gestionar el seguimiento y la programación de los ingresos, gastos y financiamiento de la Tesorería Municipal a fin de prever la disponibilidad de recursos para la toma oportuna de decisiones, diseñando e implementando políticas orientadas a la eficiencia de la gestión financiera del Gobierno Autónomo Municipal de La Paz, administrar los recursos financieros mediante el principio de unicidad de caja, programar la ejecución presupuestaria mediante la asignación de cuotas de caja e implantar políticas de pago en el marco de la disponibilidad financiera, para honrar las obligaciones generadas en el Gobierno Autónomo Municipal de La Paz; así como, controlar y conciliar las cuentas corrientes fiscales recaudadoras y pagadora de la Cuenta Única Municipal.', 'Programa los ingresos, gastos y financiamiento del Tesoro Municipal (anual, mensual y diario). || Administra los recursos financieros bajo el principio de caja única y la Cuenta Única Municipal. || Consolida y proyecta el flujo de caja y los saldos de banco para prever la disponibilidad de fondos. || Asigna cuotas de caja y ejecuta los pagos según la disponibilidad financiera para honrar obligaciones. || Asigna y controla los montos de fondos rotativos y cajas chicas de las direcciones administrativas. || Controla y concilia las cuentas corrientes fiscales recaudadoras y pagadoras. || Da apoyo técnico en materia de tesorería a las demás unidades.', 'tesoreria, flujo de caja, pagos, cuota de caja, fondo rotativo, caja chica, cuenta unica municipal, conciliacion bancaria, cuentas corrientes fiscales, recaudacion, disponibilidad financiera, saldos bancarios, programacion financiera, tesoro municipal, desembolsos, unicidad de caja, obligaciones de pago, cheques');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (33, 'UCPFF', 'UNIDAD DE CRÉDITO PÚBLICO Y FONDOS FIDUCIARIOS', 'OPERATIVO', 'SEMGE', 'EJE-01', 'Administrar el Sistema de Crédito Público e información financiera, en el marco de la normativa vigente, mediante el seguimiento, control, registro y gestión de la Deuda Pública municipal contratada y vigente, relacionada a los recursos de financiamiento obtenidos por el municipio, así como realizar las gestiones para la contratación de endeudamiento externo e interno en el marco de las necesidades de financiamiento del Gobierno Autónomo Municipal de La Paz.', 'Administra la deuda pública municipal: registra, controla y da seguimiento a los créditos vigentes. || Prepara la información financiera para contratar endeudamiento interno y externo. || Verifica liquidaciones y ejecuta los pagos del servicio de la deuda. || Da seguimiento a las solicitudes de desembolso de las unidades ejecutoras y verifica su registro contable. || Elabora la formulación y modificación presupuestaria del servicio de la deuda y controla su ejecución. || Genera boletines y reportes de deuda para el Ministerio de Economía, el Banco Central, calificadoras de riesgo y otros financiadores. || Administra los sistemas informáticos y la base de datos de la deuda pública.', 'crédito público, deuda pública, fondos fiduciarios, endeudamiento, financiamiento externo, financiamiento interno, desembolso, servicio de la deuda, calificadora de riesgo, banco central, ministerio de economía, amortización, intereses, fideicomiso, liquidación de deuda, boletín de deuda, presupuesto de deuda, financiadores, donaciones, registro contable');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (34, 'DT', 'DIRECCIÓN DE TECNOLOGÍAS', 'EJECUTIVO', 'SEMGE', 'EJE-01', 'Gestionar la administración y mantenimiento evolutivo de los sistemas informáticos, así como la administración de la infraestructura tecnológica del Gobierno Autónomo Municipal de La Paz.', 'Administra y mantiene los sistemas informáticos y la infraestructura tecnológica del municipio. || Gestiona servidores, redes, telecomunicaciones, bases de datos y el centro de datos institucional. || Realiza mantenimiento preventivo, correctivo y evolutivo de plataformas, sistemas y software. || Define y controla políticas de seguridad de la información y de respaldo y recuperación de datos. || Administra la telefonía IP y garantiza la continuidad y disponibilidad de los servicios tecnológicos. || Brinda soporte técnico especializado a todas las áreas del Órgano Ejecutivo Municipal.', 'sistemas informáticos, infraestructura tecnológica, servidores, redes, telecomunicaciones, base de datos, centro de datos, data center, seguridad de la información, ciberseguridad, respaldo de datos, backup, telefonía ip, soporte técnico, software institucional, desarrollo de sistemas, mantenimiento de sistemas, tic, hardware, conectividad, hosting, mesa de ayuda');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (35, 'UADI', 'UNIDAD DE ANALÍTICA, DESARROLLO E INNOVACIÓN', 'OPERATIVO', 'SEMGE', 'EJE-01', 'Analizar, diseñar, desarrollar, implementar, validar, aprobar, administrar, actualizar y mantener de manera evolutiva soluciones tecnológicas de los sistemas informáticos del Gobierno Autónomo Municipal de La Paz.', 'Analiza, diseña, desarrolla e implementa los sistemas informáticos del municipio (a medida o adquiridos). || Crea servicios web para integrar los distintos sistemas y aplicaciones institucionales. || Realiza pruebas y aseguramiento de la calidad del software antes de ponerlo en producción. || Da mantenimiento evolutivo a los sistemas en producción y administra sus códigos fuente, accesos y respaldos. || Desarrolla y actualiza el Portal Web del GAMLP y herramientas de datos abiertos y gobierno abierto. || Apoya a las áreas con términos de referencia para desarrollar o contratar soluciones informáticas.', 'desarrollo de software, sistemas informáticos, programación, aplicaciones, portal web, página web, servicios web, api, integración de sistemas, base de datos, código fuente, datos abiertos, gobierno abierto, mantenimiento de sistemas, términos de referencia software, aseguramiento de calidad, innovación tecnológica, analítica de datos, arquitectura de software, sistema municipal');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (36, 'UIT', 'UNIDAD DE INFRAESTRUCTURA TECNOLÓGICA', 'OPERATIVO', 'SEMGE', 'EJE-01', 'Administrar la infraestructura de tecnologías de información y comunicación, implementando y administrando las redes institucionales de datos; asesorando y validando la adquisición de equipamiento informático, brindando soporte y asistencia técnica a los usuarios a fin de contribuir con la implementación del Gobierno Electrónico/Digital y Abierto, y la mejora de los servicios apoyados en la tecnología.', 'Administra la infraestructura tecnológica del municipio: servidores, redes de datos, comunicaciones y centro de datos. || Garantiza la disponibilidad, seguridad y respaldo (backups) de los sistemas y bases de datos institucionales. || Gestiona usuarios, accesos y seguridad de la información de los sistemas en producción. || Da soporte técnico y mantenimiento preventivo y correctivo al parque informático y a la red de datos. || Tramita bajas, reposiciones y garantías técnicas de equipos obsoletos, dañados o extraviados. || Aplica normas de seguridad de la información y controla la seguridad física del centro de datos.', 'infraestructura tecnológica, servidores, redes de datos, centro de datos, data center, backups, respaldos, seguridad de la información, soporte técnico, mantenimiento de equipos, parque informático, computadoras, impresoras, cableado de red, internet institucional, base de datos, usuarios y accesos, hardware, conectividad, garantía de equipos');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (37, 'DGRH', 'DIRECCIÓN DE GESTIÓN DE RECURSOS HUMANOS', 'EJECUTIVO', 'SEMGE', 'EJE-01', 'Lograr una gestión de recursos humanos eficiente y eficaz, mediante la implementación y ejecución de procesos de Bienestar Social y del Sistema de Administración de Personal, garantizando una adecuada dotación, registro, movilidad, capacitación y evaluación del desempeño del personal, promoviendo buenas prácticas de talento humano dentro el Gobierno Autónomo Municipal de La Paz.', 'Administra el personal del municipio: contrataciones de planta y eventual, registro y movilidad. || Ejecuta procesos de dotación, evaluación del desempeño y capacitación de servidores públicos. || Gestiona el bienestar social del personal municipal. || Elabora normativa e instrumentos de gestión de recursos humanos. || Sustancia procesos administrativos ante el Ministerio de Trabajo y bajo la Ley 2027.', 'recursos humanos, personal municipal, contratación de personal, personal eventual, planilla, evaluación del desempeño, capacitación, bienestar social, servidores públicos, dotación de personal, movilidad de personal, escalafón, ministerio de trabajo, ley 2027, talento humano, vacaciones, memorándums, procesos administrativos internos, registro de personal');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (38, 'UDEP', 'UNIDAD DE DESARROLLO DE PERSONAL', 'OPERATIVO', 'SEMGE', 'EJE-01', 'Ejecutar procesos de capacitación productiva, evaluación del desempeño, reclutamiento y selección de personal, Programación Operativa Anual Individual, inducción o integración y evaluación de confirmación, promoviendo el fortalecimiento del capital humano del Gobierno Autónomo Municipal de La Paz, para el logro de los objetivos institucionales.', 'Ejecuta el reclutamiento y selección de personal para la administración centralizada. || Realiza la inducción e integración de nuevos servidores públicos a su puesto. || Programa y ejecuta la evaluación del desempeño del personal de planta. || Diseña y ejecuta el Plan Anual de Capacitación y las Buenas Prácticas Municipales. || Coordina y valida el Manual de Puestos del Órgano Ejecutivo. || Gestiona convenios para prácticas pre-profesionales y pasantías con universidades e institutos.', 'capacitación, reclutamiento, selección de personal, evaluación de desempeño, plan de capacitación, inducción, manual de puestos, prácticas preprofesionales, pasantías, convocatoria de personal, plan de personal, servidores públicos, desarrollo de personal, cursos y talleres, poai, formación de funcionarios, recursos humanos, buenas prácticas municipales, confirmación de personal');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (39, 'UAP', 'UNIDAD DE ADMINISTRACIÓN DE PERSONAL', 'OPERATIVO', 'SEMGE', 'EJE-01', 'Administrar y ejecutar dentro del Subsistema de Dotación de Personal, los procesos de clasificación, valoración y remuneración de puestos y todos aquellos procesos referidos al Subsistema de Registro, garantizando una operativa eficiente y la aplicación de controles efectivos, en el marco de la correcta aplicación de la normativa en materia de recursos humanos.', 'Elabora las planillas de sueldos, bonos, aguinaldos, retroactivos, horas extras y adicionales del personal. || Clasifica, valora y remunera puestos, y gestiona ajustes de la escala salarial. || Procesa beneficios sociales, liquidación de vacaciones y pagos de finiquito del personal centralizado. || Administra las obligaciones impositivas (RC-IVA) y los aportes a la Gestora Pública de Seguridad Social. || Controla asistencia, movimientos de personal y programa las vacaciones anuales del personal de planta. || Coordina el Plan de Personal y controla frecuencias de personal eventual según techos presupuestarios.', 'administración de personal, planillas de sueldos, haberes, bonos, aguinaldo, horas extras, beneficios sociales, finiquito, liquidación de vacaciones, escala salarial, rc-iva, aportes gestora, seguridad social, personal eventual, control de asistencia, recursos humanos, planilla de pago, retroactivo, frecuencias de personal, movimientos de personal');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (40, 'UBSSO', 'UNIDAD DE BIENESTAR SOCIAL Y SEGURIDAD OCUPACIONAL', 'OPERATIVO', 'SEMGE', 'EJE-01', 'Fortalecer la política social en el Gobierno Autónomo Municipal de La Paz, estableciendo condiciones favorables para la protección, promoción y desarrollo social y laboral de los recursos humanos de la institución, proponiendo estrategias para prevenir, proteger la vida, integridad física y mental del personal del Gobierno Autónomo Municipal de La Paz, en el marco de la normativa vigente.', 'Gestiona la afiliación, reafiliación y desafiliación de los funcionarios ante las cajas de salud (entes gestores). || Tramita bajas médicas, incapacidad temporal, maternidad y accidentes de trabajo, y recupera lo económico ante la caja. || Gestiona y canaliza asignaciones familiares: prenatal, natalidad, lactancia y sepelio. || Organiza los exámenes ocupacionales pre, post y anuales del personal municipal. || Administra la inamovilidad laboral (embarazo, discapacidad, tutores de hijos con discapacidad, enfermedades inmunodepresoras). || Desarrolla acciones de bienestar social y seguridad ocupacional para el personal. || Procesa avisos de baja definitiva y finalización de contratos ante las instancias competentes.', 'bienestar social, seguridad ocupacional, caja de salud, afiliacion, baja medica, incapacidad temporal, asignaciones familiares, prenatal, lactancia, subsidio de natalidad, sepelio, examenes ocupacionales, inamovilidad laboral, accidente de trabajo, maternidad, salud ocupacional, ente gestor, funcionario municipal, riesgos laborales, reafiliacion');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (41, 'DAG', 'DIRECCIÓN DE ADMINISTRACIÓN GENERAL', 'EJECUTIVO', 'SEMGE', 'EJE-01', 'Garantizar la implantación del Sistema de Administración de Bienes y Servicios y su Reglamento Específico en el Gobierno Autónomo Municipal de La Paz en los Subsistemas de Manejo y Disposición de Bienes; para el adecuado manejo, disposición y baja de los bienes de propiedad municipal, además de gestionar el gasto institucional, los servicios de atención ciudadana y el Archivo General. es-MX', 'Administra y controla los bienes muebles e inmuebles de propiedad municipal, velando por su uso adecuado, mantenimiento y baja. || Define políticas de salvaguarda y contrata seguros para los activos fijos municipales. || Establece directrices para el mantenimiento preventivo y correctivo de bienes registrados en los estados financieros. || Controla los almacenes de bienes de consumo y remite resultados a las áreas. || Asigna y ordena los espacios físicos en los edificios administrativos del municipio. || Gestiona el gasto institucional, los servicios de atención ciudadana y el Archivo General.', 'administración de bienes, activos fijos, bienes muebles, bienes inmuebles, inventario, almacenes, seguros de bienes, mantenimiento de edificios, baja de bienes, archivo general, atención ciudadana, gasto institucional, custodia de bienes, espacios físicos, activos municipales, mobiliario, salvaguarda de bienes, disposición de bienes, estados financieros');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (42, 'USAC', 'UNIDAD DE SERVICIOS Y ATENCIÓN CIUDADANA', 'OPERATIVO', 'SEMGE', 'EJE-01', 'Establecer políticas de atención ciudadana en los canales presenciales y no presenciales para mejorar la calidad y calidez de la atención y la prestación de servicios, caracterizados por ser ágiles, oportunos y cercanos a la ciudadanía y a los usuarios internos del Gobierno Autónomo Municipal de La Paz, en el marco del Modelo Integral de Atención Ciudadana.', 'Administra las plataformas de atención ciudadana presenciales y virtuales del municipio. || Recibe, registra, clasifica y distribuye trámites y correspondencia que ingresan al Órgano Ejecutivo. || Emite documentos físicos o digitales que forman parte de los servicios municipales. || Diseña canales y metodologías para una atención ágil, con buen trato y uso de nuevas tecnologías. || Administra los sistemas de flujo documental y genera reportes estadísticos de trámites. || Identifica necesidades ciudadanas y mejora los servicios de atención en los distintos canales.', 'atención ciudadana, plataforma de atención, ventanilla, trámites, mesa de partes, correspondencia, hoja de ruta, flujo documental, recepción de documentos, atención al público, atención virtual, canales de atención, reporte estadístico, servicios municipales, cite, registro de trámites, call center, punto de atención, buen trato, usuario, certificados');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (43, 'UAFGA', 'UNIDAD DE ACTIVOS FIJOS Y GESTIÓN DE ALMACENES', 'OPERATIVO', 'SEMGE', 'EJE-01', 'Administrar los subsistemas de manejo, disposición y baja de bienes de consumo, activos fijos muebles e inmuebles de propiedad del Gobierno Autónomo Municipal de La Paz y los que estén a su cargo o custodia, optimizando su disponibilidad, uso y control.', 'Registra, codifica, asigna e inventaría los activos fijos muebles del municipio y los de escuelas, salud, deportes y seguridad ciudadana. || Administra los almacenes y el manejo, disposición y baja de bienes de consumo y activos fijos. || Participa en la recepción de los activos fijos que adquiere el GAMLP. || Verifica la contratación de seguros y medidas de salvaguarda para bienes muebles e inmuebles. || Remite a Finanzas el detalle de activos muebles e inmuebles para los Estados Financieros. || Controla que las secciones administrativas de cada área cumplan con el control de sus activos.', 'activos fijos, inventario, almacenes, bienes muebles, codificación de activos, baja de bienes, disposición de bienes, toma de inventario, asignación de bienes, seguros de bienes, custodia de bienes, recepción de activos, mobiliario, equipos, material de escritorio, bienes de consumo, salvaguarda, revalúo, control patrimonial, inmuebles municipales');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (44, 'UASG', 'UNIDAD DE ARCHIVOS Y SERVICIOS GENERALES', 'OPERATIVO', 'SEMGE', 'EJE-01', 'Brindar servicios generales de mantenimiento de la infraestructura administrativa institucional del Gobierno Autónomo Municipal de La Paz y efectuar el control y la conciliación de cuentas por concepto de servicios básicos, relacionados con el gasto institucional; además de la administración del Archivo General del Gobierno Autónomo Municipal de La Paz.', 'Realiza el mantenimiento de los edificios municipales: plomería, carpintería, pintura, albañilería y electricidad. || Controla la facturación y autoriza el pago de agua, luz y telefonía de las oficinas municipales. || Gestiona las instalaciones de servicios básicos y las líneas telefónicas fijas y móviles institucionales. || Administra el combustible del parque automotor según presupuesto asignado. || Administra los parqueos institucionales (Parqueo Central, Edificio 10 y otros). || Gestiona el alquiler de ambientes para oficinas y administra el Archivo General del municipio.', 'servicios generales, mantenimiento de edificios, plomería, carpintería, pintura, albañilería, electricidad, servicios básicos, agua potable, energía eléctrica, factura de luz, telefonía, combustible, parqueo, alquiler de ambientes, archivo general, archivo documental, líneas telefónicas, instalación de servicios, gasolina diesel');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (45, 'DLC', 'DIRECCIÓN DE LICITACIONES Y CONTRATACIONES', 'EJECUTIVO', 'SEMGE', 'EJE-01', 'Diseñar las herramientas técnicas e instrumentos normativos que permitan operativizar la implantación del Subsistema de Contratación de Bienes y Servicios en el marco de las Normas Básicas del Sistema de Administración de Bienes y Servicios (NB-SABS), para su aplicación por todos los participantes en los procesos de contratación al interior del Gobierno Autónomo Municipal de La Paz.', 'Diseña normas, protocolos e instrumentos para las contrataciones de bienes y servicios del municipio. || Supervisa la aplicación de las Normas Básicas del SABS en los procesos de contratación. || Consolida y publica el Programa Anual de Contrataciones (PAC) en el SICOES. || Da seguimiento al cumplimiento de la programación de contrataciones. || Remite documentación de contrataciones a la Contraloría y al Concejo Municipal.', 'licitaciones, contrataciones, bienes y servicios, sicoes, programa anual de contrataciones, pac, nb-sabs, procesos de contratación, convocatorias, adjudicaciones, pliegos de condiciones, proveedores, compras estatales, contraloría, normativa de contrataciones, modalidades de contratación, términos de referencia, licitación pública');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (46, 'UPC', 'UNIDAD DE PROCESOS DE CONTRATACIÓN', 'OPERATIVO', 'SEMGE', 'EJE-01', 'Ejecutar los procesos de contratación en el marco de las Normas Básicas del Sistema de Administración de Bienes y Servicios a solicitud de las áreas y unidades organizacionales del Gobierno Autónomo Municipal de La Paz de acuerdo a la normativa vigente, así como proponer herramientas técnicas e instrumentos normativos que permitan implantar el Subsistema de Contratación de Bienes y Servicios en el Gobierno Autónomo Municipal de La Paz.', 'Lleva adelante los procesos de contratación de bienes, obras y servicios solicitados por las unidades. || Publica las convocatorias en el SICOES y medios oficiales según normativa. || Brinda asistencia técnica, administrativa y legal a las áreas durante la contratación. || Define los formatos y documentos de cada modalidad de contratación (DBC, pliegos). || Capacita a las unidades en materia de contrataciones estatales. || Gestiona la automatización de los procesos en el sistema de contrataciones del municipio.', 'contrataciones, procesos de contratación, licitación, sicoes, dbc, pliego de condiciones, anpe, licitación pública, convocatoria, adjudicación, nb-sabs, contratación de bienes, contratación de servicios, contratación de obras, modalidades de contratación, concesiones, términos de referencia, especificaciones técnicas, proveedores, compras estatales, contratación directa');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (47, 'UGDS', 'UNIDAD DE GESTIÓN DOCUMENTAL Y SEGUIMIENTO', 'OPERATIVO', 'SEMGE', 'EJE-01', 'Resguardar físicamente los documentos inherentes a los procesos de contratación remitidos para su custodia, de acuerdo a la normativa vigente, remitir información proporcionada por los actores del proceso de contratación a las instancias de fiscalización internas y externas a la entidad, administrar las garantías y efectuar el seguimiento a la protocolización de contratos ante la Notaría de Gobierno.', 'Custodia físicamente los documentos originales de los procesos de contratación y sus modificaciones. || Administra y resguarda las garantías presentadas por proveedores, contratistas y consultores. || Atiende solicitudes de fotocopias simples y legalizaciones de documentos bajo su custodia. || Remite documentación de contratos a la Contraloría General del Estado según reglamento vigente. || Da seguimiento a la protocolización de contratos ante la Notaría de Gobierno. || Envía listados de procesos de contratación al Concejo Municipal a través de la instancia correspondiente.', 'gestión documental, archivo de contratos, custodia de documentos, boletas de garantía, garantías de contrato, protocolización, notaría de gobierno, legalización de documentos, fotocopias legalizadas, contraloría, registro de contratos, procesos de contratación, modificaciones de contrato, resguardo físico, verificación de contratos, documentación de proveedores');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (48, 'DSO', 'DIRECCIÓN DE SUPERVISIÓN DE OBRAS', 'EJECUTIVO', 'SEMGE', 'EJE-01', 'Planificar, ejecutar y supervisar proyectos para infraestructuras estratégicas de acuerdo a normativa vigente, asegurando la calidad de las obras civiles; a través de un manejo administrativo técnico y eficiente.', 'Supervisa la ejecución de obras civiles estratégicas contratadas por el municipio, controlando calidad y avance. || Designa supervisores de obra y realiza supervisiones especializadas cuando la envergadura lo requiere. || Elabora lineamientos técnicos y normaliza el trabajo de supervisión de obras. || Gestiona formación continua y capacitación para los supervisores de obra. || Administra la plataforma informática de seguimiento de supervisión y fiscalización de obras. || Establece indicadores de desempeño y recomienda acciones a través del Fiscal de Obras. || Monitorea paralizaciones o suspensiones de obra según la normativa vigente.', 'supervision de obras, obras civiles, infraestructura estrategica, supervisor de obra, fiscal de obra, control de calidad de obra, avance de obra, planillas de avance, paralizacion de obra, construccion, obra publica, seguimiento de obra, indicadores de obra, administracion delegada, certificacion de obra, libro de ordenes, obra estrategica');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (49, 'DFOS', 'DIRECCIÓN DE FISCALIZACIÓN DE OBRAS Y SERVICIOS', 'EJECUTIVO', 'SEMGE', 'EJE-01', 'Establecer e implementar políticas orientadas a la adecuada gestión de la fiscalización de obras por administración delegada y directa según corresponda en el Gobierno Autónomo Municipal de La Paz, verificando los procesos en la ejecución de las obras.', 'Fiscaliza la ejecución de obras civiles municipales por administración directa y delegada, incluidos proyectos estratégicos y con financiamiento externo. || Controla que las obras cumplan el contrato, las especificaciones técnicas y la normativa vigente. || Realiza inspecciones técnicas periódicas a las obras y verifica seguridad industrial, seguros y garantías. || Evalúa, aprueba o rechaza modificaciones de contrato, certificados de pago y planillas de avance. || Participa en las comisiones de recepción provisional y definitiva de obras. || Fiscaliza el trabajo de la supervisión externa y emite resoluciones administrativas sobre documentos de seguimiento de obra.', 'fiscalización de obras, supervisión de obra, obra civil, certificado de pago, planilla de avance, recepción de obra, modificación de contrato, orden de cambio, inspección técnica, seguridad industrial en obra, garantía de obra, contrato de obra, administración delegada, administración directa, proyecto estructurante, avance físico, especificaciones técnicas, resolución administrativa, financiamiento externo, empresa constructora');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (50, 'SMCVI', 'SECRETARÍA MUNICIPAL DE CIUDAD VITAL', 'EJECUTIVO', 'SMCVI', 'EJE-02', 'Formular, dirigir, coordinar e implementar políticas, planes, programas y proyectos municipales orientados a consolidar una Ciudad Vital, saludable, activa, preventiva e inclusiva, mediante el fortalecimiento de la red municipal de salud, la promoción de servicios de salud integral e inteligente, el impulso del deporte para la vida, la actividad física, el alto rendimiento, la administración eficiente de campos deportivos y la articulación territorial de acciones que mejoren la calidad de vida de la población del municipio de La Paz.', 'Dirige las políticas y proyectos municipales de salud y deportes para una Ciudad Vital, saludable y activa. || Fortalece la red municipal de salud y gestiona el Plan Municipal de Salud. || Impulsa el deporte para la vida, la actividad física y el alto rendimiento. || Administra los campos deportivos y la infraestructura deportiva municipal. || Representa al GAMLP ante instancias públicas y privadas en materia de salud y deportes. || Conforma la Instancia Máxima de Gestión Local en Salud y articula acciones con las unidades dependientes.', 'salud municipal, red de salud, centro de salud, hospital municipal, plan municipal de salud, deportes, actividad física, alto rendimiento, campos deportivos, canchas, coliseo, polideportivo, escuelas deportivas, promoción de la salud, prevención, vida saludable, atletas, infraestructura deportiva, gestión local en salud, ciudad vital');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (51, 'DS', 'DIRECCIÓN DE SALUD', 'EJECUTIVO', 'SMCVI', 'EJE-02', 'Dirigir la gestión municipal de salud mediante la formulación, implementación, seguimiento y evaluación de políticas, programas, proyectos y servicios orientados a la prevención, atención primaria, salud integral, salud inteligente, administración de la red municipal de salud, mejora de infraestructura y equipamiento, y fortalecimiento de la calidad de atención a la población del municipio de La Paz.', 'Dirige la gestión municipal de salud: formula, implementa y evalúa políticas, programas y proyectos del sector. || Administra la Red Municipal de Salud y mejora su infraestructura y equipamiento. || Impulsa la prevención, atención primaria y salud integral bajo el modelo SAFCI. || Coordina la vigilancia epidemiológica y la gestión de riesgos y daños a la salud pública. || Fortalece la calidad de atención a la población en los establecimientos de salud del municipio.', 'salud, red municipal de salud, centro de salud, hospital municipal, atención primaria, safci, epidemiología, vigilancia epidemiológica, prevención, vacunación, equipamiento médico, infraestructura de salud, políticas de salud, salud pública, brote, campaña de salud, seguro de salud, insumos médicos, personal de salud');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (52, 'USII', 'UNIDAD DE SALUD INTEGRAL E INTELIGENTE', 'OPERATIVO', 'SMCVI', 'EJE-02', 'Gestionar servicios y programas de mayor alcance geográfico que permitan el acceso a los servicios de salud de primer nivel, mediante Equipos Móviles de Salud y Servicio Municipal de Ambulancias, con acciones de promoción, prevención y atención integral y pre hospitalaria, además de servicios de laboratorio de alimentos, bebidas u otros susceptibles de estudio, promover la investigación en salud, la gestión de calidad y la dotación de información de los servicios brindados del primer y segundo nivel en las redes de salud del municipio de La Paz.', 'Opera el Servicio Municipal de Ambulancias AUXILIO LA PAZ para atención pre hospitalaria y primeros auxilios. || Lleva atención de salud de primer nivel a los barrios mediante Equipos Móviles de Salud. || Realiza vigilancia epidemiológica para detectar y controlar brotes, epidemias y pandemias. || Implementa telemedicina y salud digital para ampliar la cobertura en la Red Municipal de Salud. || Ofrece servicios de laboratorio de alimentos y bebidas y análisis susceptibles de estudio. || Ejecuta campañas de promoción, prevención y detección precoz de enfermedades.', 'ambulancia, auxilio la paz, primeros auxilios, atención pre hospitalaria, equipos móviles de salud, salud primer nivel, vigilancia epidemiológica, brotes, epidemia, telemedicina, salud digital, laboratorio de alimentos, promoción de la salud, prevención, emergencia médica, red municipal de salud, detección precoz, campaña de salud, traslado de pacientes');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (53, 'UARMS', 'UNIDAD DE ADMINISTRACIÓN DE LA RED MUNICIPAL DE SALUD', 'OPERATIVO', 'SMCVI', 'EJE-02', 'Coordinar y gestionar los requerimientos de dotación de servicios básicos, equipos, mobiliario, medicamentos, insumos, suministros y la adecuada infraestructura de los establecimientos de salud de primer nivel, para su funcionamiento adecuado con calidad y eficiencia.', 'Gestiona el abastecimiento de medicamentos, insumos, equipos y mobiliario para los centros de salud de primer nivel. || Administra la infraestructura y servicios básicos de los establecimientos de salud municipales. || Brinda asistencia administrativa y financiera a los centros de salud de primer nivel. || Supervisa la ejecución presupuestaria y coordina contrataciones para el funcionamiento de la red de salud. || Gestiona desembolsos de Recursos de Generación Local (RGL) y la aprobación de aranceles y cartera de servicios.', 'red de salud, centros de salud, primer nivel, medicamentos, insumos médicos, equipamiento médico, postas de salud, mobiliario de salud, aranceles de salud, recursos de generación local, rgl, cartera de servicios, establecimientos de salud, suministros hospitalarios, infraestructura de salud, contrataciones de salud, personal de salud eventual, servicios básicos de salud');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (54, 'DD', 'DIRECCIÓN DE DEPORTES', 'EJECUTIVO', 'SMCVI', 'EJE-02', 'Dirigir la política municipal de deporte, actividad física, recreación, deporte comunitario, deporte inclusivo y alto rendimiento, promoviendo hábitos saludables, formación deportiva, uso ordenado de campos deportivos, competencias municipales y participación ciudadana, para consolidar una ciudad activa, saludable y vital.', 'Dirige la política municipal de deporte, actividad física, recreación y alto rendimiento. || Organiza y promueve competencias, juegos y actividades deportivas en todas las disciplinas. || Coordina con clubes, federaciones y entidades deportivas del municipio. || Impulsa el deporte comunitario, inclusivo y los hábitos saludables en los barrios. || Gestiona el uso ordenado de campos deportivos y escenarios municipales. || Genera canales de participación de vecinos en actividades deportivas y recreativas.', 'deporte, actividad física, recreación, campos deportivos, canchas, competencias deportivas, juegos deportivos, escuelas deportivas, alto rendimiento, deporte inclusivo, deporte comunitario, disciplinas deportivas, torneos, maratón, carrera pedestre, polideportivo, coliseo, graderías, clubes deportivos, federaciones, vida activa, hábitos saludables');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (55, 'UDVAR', 'UNIDAD DE DEPORTE PARA LA VIDA Y DE ALTO RENDIMIENTO', 'OPERATIVO', 'SMCVI', 'EJE-02', 'Ejecutar programas y proyectos de fomento a la práctica deportiva y actividad física saludable en el municipio de La Paz, en sus niveles formativo, recreativo y competitivo.', 'Organiza y ejecuta competencias, torneos y actividades deportivas y recreativas masivas en el municipio. || Promueve la actividad física saludable y programas de deporte barrial junto a las Subalcaldías. || Crea y mejora escuelas deportivas formativas y desarrolla a deportistas de alto rendimiento. || Capacita a profesores, entrenadores, dirigentes, atletas y padres de familia. || Dota de material deportivo a las asociaciones y clubes deportivos municipales. || Registra, empadrona y posesiona asociaciones deportivas y emite certificados para su personalidad jurídica.', 'deporte, actividad física, competencias deportivas, torneos, escuelas deportivas, alto rendimiento, deporte barrial, material deportivo, asociaciones deportivas, clubes deportivos, entrenadores, deportistas, personalidad jurídica deportiva, juegos deportivos, recreación, canchas, olimpiadas municipales, empadronamiento de deportistas, medallas y trofeos, eventos deportivos');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (56, 'UACCD', 'UNIDAD DE ADMINISTRACIÓN Y CONTROL DE CAMPOS DEPORTIVOS', 'OPERATIVO', 'SMCVI', 'EJE-02', 'Administrar los campos deportivos para su funcionamiento óptimo, en coordinación con las Subalcaldías, asociaciones deportivas y otras unidades organizacionales.', 'Administra y supervisa los campos deportivos municipales categoría A y B (canchas, coliseos, complejos). || Asegura el uso adecuado de los campos deportivos y aplica medidas de bioseguridad. || Recauda y deposita los ingresos por uso de los campos deportivos y elabora reportes mensuales. || Gestiona construcción, refacción, mejora, mantenimiento y equipamiento de la infraestructura deportiva. || Recopila y sistematiza la información técnica y legal del derecho propietario de los campos deportivos del municipio. || Coordina con Subalcaldías y asociaciones deportivas el funcionamiento de los escenarios deportivos.', 'campos deportivos, cancha, coliseo, complejo deportivo, escenario deportivo, alquiler de cancha, cesped sintetico, graderias, mantenimiento deportivo, equipamiento deportivo, recaudacion deportiva, asociaciones deportivas, polideportivo, iluminacion de cancha, reserva de cancha, derecho propietario deportivo, infraestructura deportiva, bioseguridad deportiva');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (57, 'SMCI', 'SECRETARÍA MUNICIPAL DE CIUDAD INTELIGENTE', 'EJECUTIVO', 'SMCI', 'EJE-03', 'Formular, dirigir, coordinar e implementar políticas, planes, programas y proyectos orientados a consolidar una Ciudad Inteligente, innovadora, educativa, inclusiva y basada en conocimiento, mediante la aplicación de tecnología y la creación de laboratorios de innovación social.', 'Formula y dirige las políticas de ciudad inteligente, innovación tecnológica y educación para el desarrollo. || Gestiona la infraestructura y el equipamiento de las unidades educativas del municipio. || Impulsa laboratorios urbanos de innovación social para resolver problemas de movilidad, seguridad, salud, ambiente y servicios. || Promueve el uso de datos, evidencia e investigación aplicada y la participación ciudadana en el diseño de soluciones urbanas. || Conduce la planificación de los sectores de Educación y Telecomunicaciones/TIC. || Supervisa el cumplimiento de normas y controles internos en las áreas bajo su dependencia.', 'ciudad inteligente, innovación, tecnología, tic, telecomunicaciones, educación, unidad educativa, colegio, infraestructura educativa, laboratorio de innovación, gobierno digital, datos abiertos, smart city, conectividad, internet, equipamiento escolar, transformación digital, participación ciudadana, software municipal, innovación social');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (58, 'DICI', 'DIRECCIÓN DE INNOVACIÓN Y CIUDAD INTELIGENTE', 'EJECUTIVO', 'SMCI', 'EJE-03', 'Dirigir la formulación, implementación y evaluación de proyectos de innovación tecnológica aplicada, laboratorios urbanos, soluciones inteligentes y modelos de innovación social orientados a resolver problemas públicos.', 'Formula e implementa la estrategia municipal de innovación tecnológica y laboratorios urbanos. || Impulsa proyectos de ciudad inteligente y soluciones tecnológicas para problemas públicos. || Promueve el Gobierno Electrónico, Digital y Abierto en la gestión municipal. || Gestiona y controla proyectos vinculados al uso y aprovechamiento de las TIC. || Diseña modelos de innovación social y políticas públicas para la toma de decisiones abierta.', 'innovación, ciudad inteligente, smart city, gobierno electrónico, gobierno digital, gobierno abierto, laboratorio urbano, innovación social, transformación digital, tecnología aplicada, datos abiertos, open data, solución tecnológica, modernización, proyecto tecnológico, sensores urbanos, plataforma digital, tic, iniciativa innovadora, prototipo');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (59, 'UCILU', 'UNIDAD DE CIUDAD INTELIGENTE Y LABORATORIOS URBANOS', 'OPERATIVO', 'SMCI', 'EJE-03', 'Implementar laboratorios urbanos de innovación social como espacios de investigación aplicada, participación ciudadana, co-creación, experimentación, prototipado y evaluación de soluciones para desafíos urbanos, articulando los diferentes actores de la sociedad civil.', 'Diseña e implementa laboratorios urbanos de innovación social junto a universidades, comunidad, empresas e instituciones. || Identifica problemas del territorio que pueden resolverse con metodologías de innovación. || Organiza talleres participativos, mesas de innovación y sesiones de co-creación con la ciudadanía. || Desarrolla prototipos y pilotos para mejorar espacios públicos, movilidad, seguridad, convivencia y ambiente. || Convoca retos y concursos ciudadanos de soluciones y experimentación pública.', 'ciudad inteligente, laboratorio urbano, innovación social, co-creación, prototipo, piloto, hackathon, reto de innovación, taller participativo, mesa de innovación, experimentación urbana, smart city, diseño colaborativo, solución urbana, participación ciudadana, concurso de soluciones, tecnología urbana, laboratorio ciudadano');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (60, 'UITA', 'UNIDAD DE INNOVACIÓN Y TECNOLOGÍA APLICADA', 'OPERATIVO', 'SMCI', 'EJE-03', 'Desarrollar, implementar, validar y aprobar soluciones innovadoras que contribuyan a la implementación del Gobierno Electrónico/Digital, Abierto e Innovador en el Gobierno Autónomo Municipal de La Paz, con transparencia, participación y colaboración.', 'Desarrolla e implementa soluciones tecnológicas innovadoras para el Gobierno Electrónico, Digital y Abierto. || Diseña y ejecuta proyectos de ciudad inteligente e inclusión digital. || Ejecuta las políticas y estrategias del modelo de gobierno digital municipal. || Propone y atiende iniciativas de innovación tecnológica junto con las demás áreas del municipio. || Implementa soluciones que mejoran la calidad de vida y los servicios al ciudadano mediante tecnología.', 'innovación, gobierno electrónico, gobierno digital, gobierno abierto, ciudad inteligente, smart city, inclusión digital, transformación digital, soluciones tecnológicas, trámites en línea, aplicación móvil, plataforma digital, datos abiertos, innovación tecnológica, servicios digitales, modernización, tecnología aplicada, proyectos digitales');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (61, 'DEDH', 'DIRECCIÓN DE EDUCACIÓN Y DESARROLLO HUMANO', 'EJECUTIVO', 'SMCI', 'EJE-03', 'Contribuir a la mejora de la calidad educativa, a través de la implementación de planes, programas y proyectos en infraestructura, equipamiento, nutrición y servicios pedagógicos de los subsistemas de educación regular, alternativa y especial en unidades educativas del municipio de La Paz.', 'Mejora la infraestructura, equipamiento y mobiliario de las unidades educativas del municipio. || Entrega mobiliario, material educativo, equipos e insumos a colegios fiscales, de convenio, alternativos y especiales. || Implementa programas de nutrición y servicios pedagógicos. || Establece alianzas para construir y mejorar infraestructura educativa. || Coadyuva en políticas educativas dentro de las competencias municipales.', 'educación, unidades educativas, colegios, infraestructura educativa, mobiliario escolar, material educativo, pupitres, desayuno escolar, nutrición escolar, equipamiento escolar, educación especial, educación alternativa, escuelas fiscales, escuelas de convenio, construcción de colegios, insumos educativos, servicios pedagógicos, desarrollo humano');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (62, 'UIEE', 'UNIDAD DE INFRAESTRUCTURA Y EQUIPAMIENTO EDUCATIVO', 'OPERATIVO', 'SMCI', 'EJE-03', 'Identificar, proponer, diseñar y ejecutar proyectos de construcción y mejora de las infraestructuras educativas de propiedad del Gobierno Autónomo Municipal de La Paz, para mejorar la calidad educativa del municipio de La Paz, así como fortalecer la calidad educativa a través de la dotación de insumos, material educativo y equipamiento a las Unidades Educativas Fiscales, Convenio y Centros de Educación Alternativa y Especial del municipio de La Paz.', 'Identifica necesidades y diseña proyectos de construcción, ampliación y renovación de unidades educativas municipales. || Supervisa las obras de construcción y mejoramiento de infraestructura educativa. || Coordina con las Subalcaldías el mantenimiento preventivo y correctivo de las escuelas. || Dota de mobiliario, equipamiento, insumos y material educativo a las unidades educativas fiscales, de convenio y centros de educación alternativa. || Hace seguimiento al estado, cuidado y conservación de la infraestructura educativa del municipio.', 'infraestructura educativa, construcción de escuelas, unidades educativas, mantenimiento de colegios, mobiliario escolar, equipamiento educativo, pupitres, material educativo, refacción de escuelas, ampliación de aulas, escuelas fiscales, centros de educación alternativa, supervisión de obras, insumos educativos, aulas, baterías de baño escolar, techado de escuelas, laboratorios, colegios de convenio');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (63, 'USED', 'UNIDAD DE SERVICIOS DE EDUCACIÓN PARA EL DESARROLLO', 'OPERATIVO', 'SMCI', 'EJE-03', 'Diseñar e implementar servicios, programas y proyectos educativos complementarios orientados al desarrollo humano, habilidades para la vida, educación digital, innovación, ciudadanía, sostenibilidad, emprendimiento, cultura urbana y formación integral, fortaleciendo las capacidades de niñas, niños, adolescentes, jóvenes, familias y comunidades educativas del municipio de La Paz, así como la alimentación complementaria escolar, en base a políticas de seguridad y soberanía alimentaria que contribuyan al desarrollo físico e intelectual de la población estudiantil del sistema fiscal, de convenio y Centros de Educación Especial en la jurisdicción del municipio de La Paz.', 'Diseña e implementa programas educativos complementarios en habilidades para la vida y ciudadanía. || Promueve la educación digital, alfabetización tecnológica, ciencia e innovación en la comunidad educativa. || Define el contenido nutricional y la cantidad de beneficiarios del desayuno escolar (Alimentación Complementaria Escolar). || Actúa como unidad solicitante en la contratación de proveedores de raciones del desayuno escolar. || Controla y coordina la distribución de raciones en unidades educativas fiscales, de convenio y de educación especial. || Articula con proveedores, colegios y el sistema de supervisión municipal la provisión del alimento escolar.', 'educación para el desarrollo, desayuno escolar, alimentación complementaria escolar, raciones escolares, unidades educativas, educación digital, habilidades para la vida, formación ciudadana, alimentación estudiantil, proveedores de raciones, colegios fiscales, educación especial, innovación educativa, nutrición escolar, programas educativos, alfabetización tecnológica, distribución de alimentos, seguridad alimentaria escolar');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (64, 'SMCP', 'SECRETARÍA MUNICIPAL DE CIUDAD PRODUCTIVA', 'EJECUTIVO', 'SMCP', 'EJE-04', 'Impulsar el desarrollo económico local, productivo, competitivo e innovador, centrado en el desarrollo de las capacidades humanas, articulando políticas de fomento a la inversión, emprendimiento y sectores estratégicos con alianzas público-privadas que consoliden una Ciudad Productiva, competitiva, ordenada, inclusiva y generadora de oportunidades.', 'Impulsa el desarrollo económico local: apoyo a emprendedores, artesanos y a la micro, pequeña, mediana y gran empresa. || Promueve inversiones, concesiones y Alianzas Público-Privadas (APP), y genera alianzas con el sector privado y académico. || Formula políticas para el control, regulación y administración de mercados municipales y el ordenamiento del comercio en vía pública. || Fomenta el acceso a mercados, a capital y la competitividad del sector productivo e industrial. || Regula la publicidad y las actividades económicas en cuanto a condiciones técnicas, seguridad y defensa del consumidor. || Coordina con Subalcaldías la territorialización de programas productivos y atención a comerciantes. || Articula el ecosistema emprendedor con el sector público, privado y académico.', 'desarrollo economico, emprendimiento, emprendedores, mercados municipales, comercio en via publica, comerciantes, gremiales, mipyme, artesanos, inversiones, alianzas publico privadas, app, competitividad, publicidad, defensa del consumidor, ciudad productiva, ferias productivas, actividad economica, industria, acceso a capital, ordenamiento del comercio, responsabilidad social empresarial');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (65, 'DAAE', 'DIRECCIÓN DE ADMINISTRACIÓN DE ACTIVIDADES ECONÓMICAS', 'EJECUTIVO', 'SMCP', 'EJE-04', 'Promover el desarrollo económico y promover, regular, controlar y fiscalizar las actividades económicas, elementos publicitarios; así como formular y ejecutar políticas, planes, programas y proyectos orientados al control, fiscalización, regulación y administración de mercados municipales, y el ordenamiento del comercio en vía pública. ===== PÁGINA 160 ===== 160', 'Regula, controla y fiscaliza las actividades económicas del municipio y emite lineamientos para licencias de funcionamiento. || Administra y ordena los mercados municipales de abasto y el comercio en vía pública en todos los macrodistritos. || Regula la publicidad y los elementos publicitarios, controlando emplazamientos, retiros y contaminación visual. || Aplica sanciones por infracciones mediante resolución administrativa y aprueba la reversión de puestos. || Atiende denuncias, reclamos y conflictos de comerciantes minoristas y vendedoras de mercados. || Coordina operativos de control, decomiso y desalojo de comerciantes asentados ilegalmente en espacios públicos. || Sensibiliza sobre la venta y consumo de bebidas alcohólicas y productos nocivos en mercados y ferias.', 'actividades económicas, licencia de funcionamiento, mercados municipales, comercio en vía pública, comerciantes, publicidad, vallas publicitarias, letreros, contaminación visual, puesto de mercado, reversión de puesto, ferias, vendedores ambulantes, decomiso, operativo de control, patente, gremiales, abasto, sanción administrativa, bebidas alcohólicas, avisos publicitarios, asentamiento ilegal');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (66, 'UIM', 'UNIDAD INTENDENCIA MUNICIPAL', 'OPERATIVO', 'SMCP', 'EJE-04', 'Precautelar la legalidad de las actividades económicas y la salud pública del Municipio, promoviendo la defensa del consumidor mediante el control y verificación de actividades económicas de todo tipo; así también, capacitando y concientizando a la población en general respecto a la inocuidad alimentaria, consumo y venta responsable de bebidas alcohólicas, en cumplimiento a normativa municipal y disposiciones relacionadas.', 'Controla y verifica las actividades económicas del municipio para precautelar la legalidad y la salud pública. || Ejecuta operativos de control del expendio de bebidas alcohólicas junto a Seguridad Ciudadana. || Atiende denuncias de Defensa al Consumidor e inspecciona los establecimientos denunciados. || Verifica condiciones de infraestructura, higiene y seguridad de locales comerciales. || Realiza controles en horarios extraordinarios a locales de expendio y consumo de alimentos y bebidas. || Capacita a la población sobre inocuidad alimentaria y consumo responsable de alcohol.', 'intendencia, control de actividades económicas, defensa al consumidor, inspección, operativo, bebidas alcohólicas, expendio de alcohol, control de alcohol, inocuidad alimentaria, salud pública, clausura, decomiso, licencia de funcionamiento, locales comerciales, mercados, puestos de venta, higiene, horarios extraordinarios, denuncia, verificación técnica, comercio, precios');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (67, 'UMCD', 'UNIDAD DE MERCADOS Y COMERCIO DIGNO', 'OPERATIVO', 'SMCP', 'EJE-04', 'Ejecutar políticas, planes, proyectos y normas para la administración y funcionamiento de mercados y centros de acopio, así como para el reordenamiento y control del sector gremial asentado en vía pública orientadas a promover la reconversión productiva y la dinamización, dignificación, fortalecimiento y modernización de mercados municipales y del comercio en vía pública.', 'Administra los mercados municipales, mercados tambo, mercados calle y centros de acopio. || Registra y autoriza los puestos de venta en mercados y en vía pública, y revierte puestos abandonados o subalquilados. || Planifica y ejecuta obras de construcción, mantenimiento y mejora de la infraestructura de mercados. || Coordina el control de higiene, el lavado y fumigado de mercados y la manipulación de alimentos. || Atiende denuncias, reclamos y conflictos de comerciantes junto con Intendencia y Guardia Municipal. || Reordena y controla al sector gremial asentado en la vía pública.', 'mercados, comercio, gremiales, vendedores, puestos de venta, vía pública, comerciantes, mercado tambo, mercado calle, centro de acopio, reordenamiento, reversión de puesto, manipulación de alimentos, fumigación de mercados, higiene, infraestructura de mercados, asentamiento, avance de venta, reconversión productiva, comercio digno');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (68, 'UAEP', 'UNIDAD DE ACTIVIDADES ECONÓMICAS Y PUBLICIDAD', 'OPERATIVO', 'SMCP', 'EJE-04', 'Generar y ejecutar políticas, planes, programas, proyectos, instrumentos y lineamientos técnicos para regular actividades económicas y publicidad en el municipio, incluyendo la emisión y control de licencias de funcionamiento y de publicidad, así como los procesos sancionatorios, garantizando el cumplimiento de la normativa vigente.', 'Emite, renueva, modifica y revoca las licencias de funcionamiento de las actividades económicas. || Regula y controla la publicidad urbana para reducir la contaminación visual. || Tramita la regularización de actividades económicas y emite resoluciones administrativas y sanciones. || Brinda legalizaciones, certificaciones y fotocopias de licencias de funcionamiento. || Elabora y actualiza la normativa y lineamientos técnicos para negocios y publicidad. || Coordina la mejora de las herramientas informáticas para la emisión de licencias.', 'licencia de funcionamiento, actividad económica, publicidad, letreros, vallas publicitarias, contaminación visual, negocios, comercio, resolución administrativa, sanción, clausura, regularización, certificación de licencia, renovación de licencia, revocatoria, emplazamiento de publicidad, letrero comercial, apertura de negocio, legalización');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (69, 'DDECI', 'DIRECCIÓN DE DESARROLLO ECONÓMICO, COMPETITIVIDAD E INVERSIONES', 'EJECUTIVO', 'SMCP', 'EJE-04', 'Impulsar el desarrollo económico del municipio, articulando la economía solidaria, popular y el desarrollo rural con el fomento al emprendimiento y la promoción de competitividad e inversiones, que contribuyan a la generación de empleo, incremento de ingresos y oportunidades económicas para la población del municipio de La Paz.', 'Impulsa el desarrollo económico, el emprendimiento y la generación de empleo en el municipio. || Promueve la inversión, las concesiones y las Alianzas Público-Privadas (APP). || Fortalece a micro, pequeñas, medianas y grandes empresas para mejorar productividad y competitividad. || Fomenta la innovación tecnológica, la digitalización y el acceso a capital para emprendedores. || Apoya el desarrollo productivo rural articulado con el área metropolitana. || Administra Centros de Innovación Tecnológica y Escuelas Técnicas Municipales.', 'desarrollo económico, emprendimiento, competitividad, inversiones, alianzas público-privadas, app, concesiones, empleo, mipymes, microempresa, economía popular, innovación tecnológica, escuelas técnicas, centros de innovación, productividad, acceso a capital, desarrollo rural, ferias productivas, capacitación empresarial, inserción laboral');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (70, 'UESPDR', 'UNIDAD DE ECONOMÍA SOLIDARIA, POPULAR Y DESARROLLO RURAL', 'OPERATIVO', 'SMCP', 'EJE-04', 'Promover la economía solidaria, popular y el desarrollo productivo del municipio de La Paz mediante programas de fortalecimiento productivo, asociatividad, asistencia técnica, acceso a mercados, cadenas de valor, producción sostenible, contribuyendo a mejorar ingresos y oportunidades de productores, comunidades y unidades económicas populares.', 'Diseña y ejecuta programas de economía solidaria, popular, comunitaria y desarrollo rural. || Fortalece capacidades productivas, comerciales y administrativas de productores, asociaciones y unidades económicas populares. || Organiza ferias, mercados móviles e itinerantes para conectar la producción rural con el mercado metropolitano. || Ejecuta estrategias de producción agropecuaria tecnificada en los distritos rurales. || Impulsa la asociatividad, redes productivas, circuitos cortos y compras locales. || Vincula a pequeños productores con la academia y el sector privado para transferencia de tecnología.', 'economía solidaria, economía popular, desarrollo rural, productores, ferias productivas, mercados móviles, ferias itinerantes, asociatividad, asistencia técnica productiva, cadenas de valor, circuitos cortos, compras locales, producción agropecuaria, distritos rurales, unidades económicas populares, emprendimientos, acceso a mercados, comercialización directa, cooperativas, microempresas, productos rurales');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (71, 'UFE', 'UNIDAD DE FOMENTO AL EMPRENDEDURISMO', 'OPERATIVO', 'SMCP', 'EJE-04', 'Impulsar acciones que fortalezcan el ecosistema emprendedor del municipio, mediante el fortalecimiento integral de capacidades empresariales, técnicas y tecnológicas y la articulación de alianzas estratégicas entre sectores, promoviendo la innovación, la productividad y la sostenibilidad, con el fin de fomentar el desarrollo económico, la inserción laboral y el crecimiento del municipio de La Paz.', 'Capacita y brinda asistencia técnica a emprendedores en gestión empresarial, marketing digital, producción y costos. || Apoya la innovación y el uso de herramientas digitales y tecnológicas en negocios locales. || Administra los Centros de Innovación Tecnológica Sectoriales, su infraestructura, equipos y maquinaria. || Articula redes de emprendedores y alianzas con actores privados y académicos. || Organiza concursos, ferias y eventos que reconocen e impulsan a los emprendedores. || Coadyuva en el desarrollo de prototipos de productos con apoyo académico y privado.', 'emprendimiento, emprendedores, asistencia técnica, capacitación empresarial, marketing digital, innovación tecnológica, centros de innovación, prototipos, redes de emprendedores, alianzas estratégicas, concursos de emprendimiento, ecosistema emprendedor, negocios en marcha, ideas de negocio, incubación, productividad, ferias empresariales, desarrollo económico, maquinaria y equipos, gestión empresarial');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (72, 'UCI', 'UNIDAD DE COMPETITIVIDAD E INVERSIONES', 'OPERATIVO', 'SMCP', 'EJE-04', 'Gestionar inversiones municipales de manera transparente y equitativa, realizando análisis de evaluación económica para optimizar los servicios públicos municipales, obras públicas y bienes municipales, contribuyendo así al desarrollo sostenible y la mejora de la calidad de vida en la comunidad.', 'Evalúa económicamente proyectos de inversión municipal para optimizar servicios, obras y bienes del municipio. || Gestiona instrumentos de disposición temporal de bienes de dominio municipal según normativa. || Coordina con actores privados proyectos de interés municipal bajo responsabilidad social empresarial e inversión social. || Implementa acciones que faciliten la inversión, concesiones, APP y otras figuras legales en el municipio.', 'competitividad, inversiones, evaluacion economica, proyectos de inversion, concesiones, alianzas publico privadas, app, bienes de dominio municipal, disposicion de bienes, responsabilidad social empresarial, inversion social, analisis costo beneficio, actores privados, figuras legales de inversion, desarrollo sostenible, rentabilidad de proyectos');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (73, 'SMCCD', 'SECRETARÍA MUNICIPAL DE CIUDAD DE CUIDADOS Y DERECHOS', 'EJECUTIVO', 'SMCCD', 'EJE-05', 'Formular e implementar políticas, planes, programas y proyectos municipales integrales para el bienestar y desarrollo poblacional, así como la prevención social, comunitaria y situacional, la promoción de la seguridad ciudadana con corresponsabilidad social y la construcción de redes territoriales de cuidado, inclusión, dignidad y convivencia pacífica orientadas a consolidar una Ciudad de Cuidados y Derechos.', 'Formula políticas y programas de protección y restitución de derechos de niñez, adolescencia, juventud, mujeres, adultos mayores, personas con discapacidad y poblaciones vulnerables. || Impulsa el sistema de atención a la violencia en el marco de la Ley 348 y el Código Niña, Niño y Adolescente. || Gestiona asistencia humanitaria, cobijo temporal y albergues para personas en situación de violencia, riesgo o emergencia. || Conduce la política municipal de seguridad ciudadana y da seguimiento al Plan Municipal de prevención de la violencia y el delito. || Promueve la protección de animales de compañía y en situación de abandono, y el bienestar animal. || Supervisa los servicios legales integrales, defensorías y redes de cuidado en el territorio.', 'derechos, cuidados, violencia, ley 348, slim, defensoría de la niñez, niñez y adolescencia, adulto mayor, personas con discapacidad, mujeres, juventud, diversidad sexual, seguridad ciudadana, prevención del delito, asistencia humanitaria, albergue, cobijo temporal, bienestar animal, protección animal, grupos vulnerables, inclusión social, servicios legales integrales');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (74, 'DASI', 'DIRECCIÓN DE ATENCIÓN SOCIAL INTEGRAL', 'EJECUTIVO', 'SMCCD', 'EJE-05', 'Diseñar e implementar políticas públicas, planes, programas y proyectos destinados a promover el ejercicio pleno de los derechos humanos de la infancia, niñez, adolescencia, jóvenes, mujeres, hombres, personas con discapacidad, personas con diversa orientación sexual e identidad de género, víctimas de violencia, personas en riesgo social y personas adultas mayores, fomentando su autonomía, empoderamiento, desarrollo personal, prevención de violencias y participación ciudadana, en el marco de los principios de igualdad, equidad y transversalización del enfoque de género y generacional; así como promover la protección a los animales de compañía y fomentar la salud pública y el bienestar animal en el municipio de La Paz.', 'Diseña e implementa políticas y programas para los derechos de niñez, adolescencia, jóvenes, mujeres, adultos mayores, personas con discapacidad y diversidad sexual. || Presta servicios gratuitos de defensa psico-socio-jurídica a víctimas de violencia mediante la DNA, el SLIM y el Centro Terapéutico Municipal. || Atiende y previene la violencia contra niños, adolescentes, mujeres y hombres a través de defensores municipales. || Ofrece apoyo pedagógico a la infancia y adolescencia mediante Centros de Apoyo Pedagógico. || Promueve los Consejos y Comités Ciudadanos y la participación de poblaciones vulnerables. || Fomenta la protección de animales de compañía y el bienestar animal en el municipio.', 'defensoría de la niñez, dna, slim, servicio legal integral municipal, violencia, violencia de género, víctimas de violencia, niñez y adolescencia, adulto mayor, personas con discapacidad, diversidad sexual, lgbti, mujeres, juventud, centro terapéutico, apoyo pedagógico, derechos humanos, grupos vulnerables, ley 348, ley 548, bienestar animal, animales de compañía, atención social');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (75, 'UCLARCI', 'UNIDAD DE CIUDAD LONGEVA, ACTIVA Y REDES DE CUIDADO INTERGENERACIONAL', 'OPERATIVO', 'SMCCD', 'EJE-05', 'Desarrollar e implementar normativa, políticas públicas a través de planes, programas y proyectos de promoción, fortalecimiento y difusión del ejercicio de los derechos de las personas adultas mayores del municipio de La Paz, promoviendo la igualdad, inclusión e integración social.', 'Implementa programas y proyectos para promover y proteger los derechos de las personas adultas mayores. || Crea redes de cuidado intergeneracional con actividades comunitarias y de acompañamiento social. || Previene el abandono de las personas adultas mayores y articula servicios municipales para su atención. || Promueve el envejecimiento activo, digno, saludable y participativo. || Realiza capacitación, sensibilización y difusión de derechos de la población adulta mayor.', 'adulto mayor, personas adultas mayores, tercera edad, envejecimiento activo, cuidado intergeneracional, redes de cuidado, abandono del adulto mayor, vejez digna, acompañamiento social, derechos del adulto mayor, centro del adulto mayor, ciudad longeva, abuelos, inclusión social, protección del adulto mayor, actividades para mayores, gerontología, envejecimiento');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (76, 'UCIN', 'UNIDAD DE CIUDAD INCLUSIVA', 'OPERATIVO', 'SMCCD', 'EJE-05', 'Implementar servicios de atención y protección a personas con discapacidad, con enfoque de derechos humanos y promover acciones de protección en el municipio de La Paz, además de implementar políticas públicas, planes, proyectos y acciones estratégicas en favor del ejercicio pleno de los derechos de personas con discapacidad, en el marco de los principios de igualdad y equidad.', 'Brinda atención y protección a personas con discapacidad con enfoque de derechos humanos. || Implementa políticas, planes y proyectos a favor de los derechos de las personas con discapacidad. || Ejecuta campañas de sensibilización y difusión sobre los derechos de personas con discapacidad. || Promueve la capacitación y la equiparación de oportunidades para una convivencia inclusiva.', 'discapacidad, personas con discapacidad, inclusión, ciudad inclusiva, derechos humanos, accesibilidad, equiparación de oportunidades, sensibilización, carnet de discapacidad, atención a discapacidad, protección, convivencia inclusiva, igualdad, capacitación, apoyo a discapacidad');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (77, 'UDM', 'UNIDAD DE DEFENSORÍA MUNICIPAL', 'OPERATIVO', 'SMCCD', 'EJE-05', 'Gestionar servicios municipales de defensoría, atención y restitución psico-socio-legal de infantes, niñas, niños, adolescentes, familias, personas en situación de riesgo social y toda persona en situación de violencia; así como implementar planes, programas y proyectos de protección para la población vulnerable, de riesgo social y en situación de calle, promoviendo la corresponsabilidad y resiliencia social en coordinación con la sociedad civil y mecanismos comunitarios.', 'Atiende y protege a niñas, niños, adolescentes, familias y personas en situación de violencia. || Brinda defensa psicológica, social y jurídica a través de equipos multidisciplinarios. || Restituye derechos de personas en situación de riesgo social o de calle. || Emite lineamientos de atención integral ante casos de violencia y vulneración de derechos. || Implementa programas de protección para población vulnerable en coordinación con la sociedad civil.', 'defensoría de la niñez, violencia, niñez y adolescencia, protección de derechos, maltrato infantil, violencia intrafamiliar, personas en situación de calle, atención psicológica, atención legal, trabajo social, riesgo social, restitución de derechos, vulneración de derechos, diversidad sexual, población vulnerable, defensoría municipal, denuncias de violencia, equipo multidisciplinario');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (78, 'UJDP', 'UNIDAD DE JUVENTUDES Y DIVERSIDADES PROACTIVAS', 'OPERATIVO', 'SMCCD', 'EJE-05', 'Desarrollar políticas públicas orientadas a la promoción y atención de las juventudes y diversidad sexuales y de género, a través de la ejecución de planes, programas y proyectos que garanticen el ejercicio pleno de sus derechos y fomenten su corresponsabilidad en el municipio de La Paz.', 'Propone y ejecuta políticas públicas para las juventudes y las diversidades sexuales y de género. || Implementa centros de información, formación y coworks para jóvenes (refuerzo académico, arte, deporte, habilidades para la vida). || Organiza asambleas y encuentros juveniles para recoger propuestas y demandas. || Promueve el desarrollo integral de la juventud en lo social, laboral, educativo y tecnológico. || Acompaña el voluntariado juvenil en el municipio. || Garantiza el ejercicio pleno de derechos de jóvenes y poblaciones LGBTI.', 'juventudes, jóvenes, diversidades sexuales, lgbti, diversidad de género, centros juveniles, cowork, voluntariado juvenil, encuentros juveniles, habilidades para la vida, derechos de los jóvenes, formación artística, refuerzo académico, asambleas juveniles, políticas de juventud, desarrollo humano productivo, agrupaciones juveniles, casa de la juventud, orientación juvenil');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (79, 'UCIM', 'UNIDAD CIUDAD DE LA MUJER', 'OPERATIVO', 'SMCCD', 'EJE-05', 'Desarrollar e implementar políticas públicas que promuevan el ejercicio pleno de los derechos, la autonomía y el empoderamiento de las mujeres de todas las edades, centrado en el desarrollo de capacidades humanas.', 'Diseña e implementa políticas, programas y servicios municipales para las mujeres de todas las edades. || Impulsa la autonomía económica y emocional de las mujeres mediante alianzas estratégicas. || Ejecuta proyectos de prevención de la violencia y promoción de derechos de las mujeres y sus familias. || Promueve derechos sexuales y reproductivos con enfoque de género y derechos humanos. || Propone normativa de igualdad y equidad de género y generacional. || Impulsa el reconocimiento del trabajo no remunerado y la corresponsabilidad del cuidado.', 'ciudad de la mujer, derechos de las mujeres, equidad de género, prevención de violencia, violencia de género, empoderamiento femenino, autonomía económica, derechos sexuales y reproductivos, igualdad de género, trabajo de cuidado, liderazgo de la mujer, corresponsabilidad, políticas de género, protección a la mujer, bienestar de las mujeres, servicios para mujeres, enfoque de género');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (80, 'UCPA', 'UNIDAD CIUDAD PROTECTORA DE ANIMALES', 'OPERATIVO', 'SMCCD', 'EJE-05', 'Promover la atención, protección, control de animales y zoonosis para la preservación de la salud pública, en coordinación con las áreas y unidades organizacionales del Gobierno Autónomo Municipal de La Paz, enmarcados en la normativa nacional, departamental y municipal vigente y promocionar la tenencia responsable de animales de compañía.', 'Ejecuta campañas de esterilización para controlar la sobrepoblación de perros y gatos. || Realiza vacunación antirrábica y vigilancia epidemiológica de enfermedades zoonóticas (rabia y otras). || Implementa el censo, registro y carnetización de animales de compañía y promueve la tenencia responsable. || Atiende denuncias de maltrato animal y coordina decomisos de venta ilegal de animales en ferias y vía pública. || Controla vectores mediante desratización, desinsectación y desinfección en mercados, áreas verdes y espacios públicos. || Inspecciona veterinarias, peluquerías caninas, pet shops y albergues para el otorgamiento de licencias de funcionamiento. || Recoge animales sospechosos de rabia y coordina con fundaciones, veterinarios y voluntariado el rescate y sensibilización.', 'proteccion animal, zoonosis, esterilizacion, castracion, vacuna antirrabica, rabia, perros, gatos, mascotas, tenencia responsable, maltrato animal, denuncia animal, canil, albergue, desratizacion, fumigacion, control de vectores, veterinaria, pet shop, carnetizacion de mascotas, bienestar animal, rescate animal, vacunacion');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (81, 'DSCC', 'DIRECCIÓN DE SEGURIDAD CIUDADANA CON COMUNIDAD', 'EJECUTIVO', 'SMCCD', 'EJE-05', 'Desarrollar planes, programas y proyectos de prevención primaria, secundaria y terciaria, social, comunitaria, situacional y de protección, identificando e interviniendo en las causas de la violencia y el delito; en el marco de las competencias establecidas en la ley y normativa vigente; para consolidar la construcción de la cultura de paz a través del empoderamiento de los habitantes del municipio de La Paz y su resiliencia, con base en el desarrollo humano integral y el ejercicio pleno de sus derechos y obligaciones.', 'Diseña planes y proyectos de prevención de la violencia y el delito (primaria, secundaria y terciaria) con enfoque comunitario. || Elabora directrices y estándares de prevención situacional del delito interviniendo en factores del entorno. || Realiza intervenciones en espacios públicos y semipúblicos para reducir oportunidades de comisión de delitos. || Ejecuta evaluaciones de sitios y auditorías de seguridad en lugares con factores de riesgo. || Coordina con otras áreas municipales para consolidar la cultura de paz y la resiliencia comunitaria.', 'seguridad ciudadana, prevención del delito, prevención de la violencia, cultura de paz, prevención situacional, auditoría de seguridad, espacios públicos seguros, iluminación, puntos de riesgo, convivencia pacífica, resiliencia comunitaria, intervención comunitaria, cámaras de seguridad, factores de riesgo, vecindario seguro, delincuencia, diagnóstico de seguridad, entorno urbano');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (82, 'UPSC', 'UNIDAD DE PREVENCIÓN SOCIAL Y COMUNITARIA', 'OPERATIVO', 'SMCCD', 'EJE-05', 'Implementar estrategias, planes, programas y proyectos integrales destinados a la transformación ciudadana y a la promoción de la seguridad ciudadana a través de una cultura de paz, y a la reducción de los factores de riesgo, la ocurrencia del delito, y los efectos de daño potencial a las personas y la sociedad, así como a la reducción de la percepción de inseguridad mediante la intervención en sus causas, a través de acciones de prevención primaria, secundaria y terciaria, así como de protección social y comunitaria.', 'Ejecuta estrategias y programas de prevención del delito y promoción de la seguridad ciudadana. || Desarrolla campañas educativas y comunicacionales para una cultura de paz en la comunidad. || Reduce factores de riesgo social y fortalece los factores de protección en barrios y comunidades. || Apoya programas de reeducación, rehabilitación y reinserción de niños y adolescentes en riesgo social. || Coadyuva en la atención a personas con drogodependencia y alcoholismo.', 'prevención del delito, seguridad ciudadana, cultura de paz, prevención social, factores de riesgo, reinserción social, rehabilitación, reeducación, drogodependencia, alcoholismo, jóvenes en riesgo, violencia, campaña comunicacional, convivencia pacífica, prevención comunitaria, percepción de inseguridad, riesgo social, protección social, talleres preventivos');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (83, 'UPS', 'UNIDAD DE PREVENCIÓN SITUACIONAL', 'OPERATIVO', 'SMCCD', 'EJE-05', 'Fortalecer la seguridad ciudadana en el municipio de La Paz a través de la gestión, planificación y ejecución de estrategias de prevención situacional, garantizando la dotación de infraestructura, equipamiento tecnológico y logística a la Policía Boliviana, así como la recuperación de espacios públicos, la coordinación interinstitucional y la atención integral en situaciones de emergencia, con el fin de reducir los factores de riesgo y mejorar la calidad de vida de la población.', 'Dota de infraestructura, equipamiento y logística a la Policía Boliviana para la seguridad ciudadana en el municipio. || Construye, mantiene y refacciona módulos y estaciones policiales. || Instala y mantiene cámaras de video vigilancia, alarmas comunitarias y la red de comunicaciones (fibra óptica y enlaces). || Gestiona el combustible para los vehículos municipales entregados a la Policía. || Recupera espacios públicos y ejecuta operativos de control de expendio y consumo de bebidas alcohólicas. || Fortalece la Policía Comunitaria y coordina con instituciones para prevenir el delito.', 'seguridad ciudadana, prevención del delito, cámaras de vigilancia, videovigilancia, alarmas comunitarias, módulo policial, estación policial, policía boliviana, policía comunitaria, botón de pánico, combustible policial, fibra óptica, operativos, bebidas alcohólicas, expendio de alcohol, recuperación de espacios, equipamiento policial, tecnología preventiva, prevención situacional, patrullaje');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (84, 'SMCCTAEN', 'SECRETARÍA MUNICIPAL DE CIUDAD CULTURAL, TURISMO DE ALTURA Y ECONOMÍA NARANJA', 'EJECUTIVO', 'SMCCTAEN', 'EJE-06', 'Formular, dirigir, coordinar e implementar políticas, planes, programas y proyectos orientados a consolidar a al municipio de Nuestra Señora de La Paz como una Ciudad Cultural, destino de turismo de altura y plataforma de economía naranja, mediante la protección y valorización del patrimonio, la promoción de las culturas y las artes, el fortalecimiento de industrias creativas, la dinamización de la marca ciudad, el desarrollo de productos y destinos turísticos, la gestión de espacios culturales y recreativos, y la articulación entre identidad, creatividad, turismo y orgullo ciudadano.', 'Dirige las políticas de cultura, turismo de altura y economía naranja del municipio de La Paz. || Formula e implementa el Plan Municipal de Turismo y fortalece la Red Turística Municipal. || Protege, cataloga y salvaguarda el patrimonio cultural material e inmaterial paceño. || Impulsa las industrias creativas, la marca ciudad y el posicionamiento nacional e internacional de La Paz. || Organiza la Agenda Cultural Anual, el calendario festivo y folklórico y las actividades en fechas cívicas. || Promueve la gastronomía, el turismo comunitario y la producción artística de gestores culturales. || Supervisa y controla el funcionamiento de los servicios turísticos del municipio.', 'cultura, turismo, turismo de altura, economía naranja, patrimonio cultural, patrimonio inmaterial, industrias creativas, marca ciudad, gastronomía, agenda cultural, calendario festivo, folklore, artes, gestores culturales, festival, eventos culturales, destino turístico, guías de turismo, atractivos turísticos, identidad paceña, espacios culturales');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (85, 'DTA', 'DIRECCIÓN DE TURISMO DE ALTURA', 'EJECUTIVO', 'SMCCTAEN', 'EJE-06', 'Posicionar al municipio de La Paz como un destino de referencia internacional, mediante la implementación de la política municipal de turismo de altura, articulando el fortalecimiento de la infraestructura y ===== PÁGINA 211 ===== 211 equipamiento turístico, así como el fomento de la dinamización de la oferta comunitaria y gastronómica, la promoción de productos turísticos y la consolidación de una red turística sostenible de altura, que valorice la identidad geográfica de La Paz.', 'Implementa la política municipal de turismo de altura y el Plan Municipal de Turismo. || Promociona a La Paz como destino turístico a nivel local, nacional e internacional. || Fortalece la infraestructura y equipamiento turístico municipal. || Fomenta el turismo comunitario, la oferta gastronómica y la marca gastronómica del municipio. || Supervisa y controla el funcionamiento de servicios turísticos, guías, agencias y hoteles. || Administra el Parque Mirador La Paz en Pasankeri, Macrodistrito Cotahuma.', 'turismo, turismo de altura, promoción turística, destino turístico, gastronomía, turismo comunitario, guías turísticos, agencias de viaje, operadores turísticos, miradores, parque mirador, atractivos turísticos, hoteles, restaurantes, red turística, señalización turística, ferias gastronómicas, marca turística, infraestructura turística');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (86, 'UCPAT', 'UNIDAD DE CALIDAD, PROMOCIÓN Y ARTICULACIÓN TURÍSTICA', 'OPERATIVO', 'SMCCTAEN', 'EJE-06', 'Ejecutar planes, programas y proyectos destinados a posicionar al municipio como un destino turístico internacional y el principal destino turístico de Bolivia, atrayendo demanda turística de calidad que genera empleo y bienestar social.', 'Ejecuta programas de promoción y difusión del destino turístico La Paz a nivel local, nacional e internacional. || Posiciona el patrimonio turístico del municipio para atraer más visitantes. || Implementa acciones para mejorar la calidad y competitividad de los servicios turísticos. || Dinamiza el mercado interno y fomenta la inversión privada en actividades turísticas. || Aplica el Plan Municipal de Turismo con enfoque de sostenibilidad.', 'turismo, promoción turística, destino turístico, patrimonio turístico, atractivos turísticos, calidad turística, city tour, ferias de turismo, guías turísticos, turismo de altura, marca ciudad, difusión turística, inversión turística, competitividad turística, circuitos turísticos, visitantes, plan de turismo, servicios turísticos, turismo sostenible');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (87, 'UFPDIT', 'UNIDAD DE FOMENTO DE PRODUCTOS, DESTINOS E INFRAESTRUCTURA TURÍSTICA', 'OPERATIVO', 'SMCCTAEN', 'EJE-06', 'Gestionar productos, destinos, circuitos e infraestructura turística del municipio de La Paz, consolidando la sostenibilidad integral turística que integra cultura, patrimonio, gastronomía y servicios turísticos de calidad.', 'Diseña y gestiona productos, destinos y circuitos turísticos del municipio de La Paz. || Administra, mantiene y equipa la infraestructura turística municipal. || Gestiona proyectos de inversión en infraestructura pública de apoyo al turismo. || Impulsa emprendimientos turísticos comunitarios mediante proyectos de infraestructura. || Gestiona la restauración, preservación y equipamiento de atractivos y espacios turísticos.', 'turismo, destinos turísticos, circuitos turísticos, productos turísticos, infraestructura turística, atractivos turísticos, miradores, señalética turística, turismo comunitario, patrimonio turístico, equipamiento turístico, mantenimiento de atractivos, inversión turística, gastronomía, promoción turística, sostenibilidad turística, rutas turísticas');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (88, 'DCU', 'DIRECCIÓN DE CULTURAS', 'EJECUTIVO', 'SMCCTAEN', 'EJE-06', 'Generar los espacios para garantizar el ejercicio pleno de los Derechos Culturales, potenciar la diversidad cultural y su encuentro a través del fomento a las manifestaciones artístico-culturales (autóctonas, folklóricas, tradicionales, urbanas y contemporáneas), fortaleciendo la creación, producción, circulación artístico-cultural y el desarrollo de las economías culturales, con base en el respeto a la pluralidad de identidades, el diálogo intercultural, la democratización, desconcentración y la valoración de la riqueza cultural como factores de cohesión, inclusión, transformación y desarrollo del municipio, así como la protección, preservación, revalorización y puesta en valor del patrimonio cultural inmaterial.', 'Formula y supervisa políticas, programas y proyectos culturales para promover las artes y las culturas del municipio. || Fomenta las manifestaciones artístico-culturales autóctonas, folklóricas, tradicionales, urbanas y contemporáneas. || Apoya a gestores, artistas y trabajadores de la cultura en la creación, producción y circulación artística. || Descentraliza y democratiza el acceso a la cultura, llevando la actividad cultural a los distritos. || Protege, preserva y pone en valor el patrimonio cultural inmaterial. || Impulsa las economías culturales y el diálogo intercultural.', 'cultura, arte, actividad cultural, manifestaciones culturales, folklore, patrimonio inmaterial, artistas, gestores culturales, festival cultural, danza, musica, teatro, eventos culturales, economias culturales, interculturalidad, produccion artistica, derechos culturales, espacios culturales, tradiciones');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (89, 'UCV', 'UNIDAD DE CULTURA POR LA VIDA', 'OPERATIVO', 'SMCCTAEN', 'EJE-06', 'Impulsar y consolidar las economías culturales del municipio a través de la evaluación, promoción, difusión y ejecución de proyectos sostenibles, el desarrollo de marcos institucionales y normativos, y la facilitación de su inserción y competitividad en los mercados locales, nacionales e internacionales, reconociendo su impacto en el desarrollo económico y social y promover, fortalecer y dinamizar la oferta cultural y artística, fomentando la creación, producción y circulación de expresiones culturales diversas, garantizando la democratización y el acceso a la cultura en todos los distritos, e impulsando el reconocimiento, desarrollo y sostenibilidad de las tradiciones ancestrales y el patrimonio folklórico del municipio de La Paz.', 'Ejecuta planes y proyectos para desarrollar las economías culturales y creativas del municipio. || Organiza ferias culturales, espectáculos artísticos y actividades en espacios públicos de todos los distritos. || Gestiona concursos y premios municipales para incentivar la creación artística. || Apoya iniciativas artístico-culturales y expresiones de la población, promoviendo su circulación y sostenibilidad. || Promociona a La Paz como destino audiovisual a través de La Paz Filma y difunde talentos y servicios locales. || Evalúa y promueve proyectos artístico-culturales y fortalece las tradiciones ancestrales y el patrimonio folklórico.', 'cultura, arte, actividad cultural, feria cultural, espectáculo artístico, concurso, premio municipal, economías culturales, industrias creativas, la paz filma, producción audiovisual, folklore, patrimonio, artistas, música, teatro, danza, festival, escenario, tradiciones, promoción cultural, circulación artística');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (90, 'UPF', 'UNIDAD DE PATRIMONIO PARA EL FUTURO', 'OPERATIVO', 'SMCCTAEN', 'EJE-06', 'Gestionar el patrimonio cultural inmaterial del municipio de La Paz, así como formar y capacitar a hombres y mujeres en situación de vulnerabilidad social, económica y cultural, en oficios tradicionales, artesanales y contemporáneos, orientados a la conservación y restauración del patrimonio cultural mueble e inmueble; impulsando programas de formación y capacitación en áreas vinculadas al ámbito artístico-cultural para preservar el patrimonio como legado vivo para las futuras generaciones.', 'Gestiona y salvaguarda el patrimonio cultural inmaterial del municipio de La Paz. || Rescata conocimientos ancestrales y oficios tradicionales en riesgo de desaparición. || Forma y capacita a personas en situación de vulnerabilidad en oficios artesanales y de restauración. || Identifica, registra y cataloga las expresiones del patrimonio cultural inmaterial. || Impulsa investigaciones, publicaciones y archivos de memoria e historia del municipio. || Trabaja con comunidades portadoras y actores culturales en acciones de conservación.', 'patrimonio cultural inmaterial, oficios tradicionales, artesanos, restauración, conservación del patrimonio, conocimientos ancestrales, salvaguarda, memoria histórica, registro cultural, catalogación, saberes, cultura viva, formación en oficios, capacitación artesanal, comunidades portadoras, publicaciones, archivo histórico, legado cultural, tradiciones, puesta en valor');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (91, 'UEICR', 'UNIDAD DE ESPACIOS E INFRAESTRUCTURA CULTURAL Y RECREATIVA', 'OPERATIVO', 'SMCCTAEN', 'EJE-06', 'Administrar, promover y consolidar los Espacios Culturales Municipales, como la Red de Bibliotecas, Espacios Escénicos, Museos, Salas de Exposición y Auditorios, bajo la gestión de la Secretaría Municipal de Ciudad Cultural, Turismo de Altura y Economía Naranja, garantizando servicios de calidad, calidez, eficiencia y eficacia, adecuados a las necesidades de los usuarios y de la población en general.', 'Administra los espacios culturales municipales: Red de Bibliotecas, museos, salas de exposición, espacios escénicos y auditorios. || Programa y difunde las actividades culturales en esos espacios en coordinación con los usuarios. || Evalúa y asigna los espacios culturales solicitados por usuarios externos o áreas del municipio. || Propone la metodología, precios y modificaciones de tarifas de los servicios culturales. || Impulsa proyectos y normativa para mejorar los servicios y crear nuevos espacios de difusión literaria.', 'espacios culturales, biblioteca, museo, sala de exposición, auditorio, teatro, espacio escénico, reserva de auditorio, préstamo de sala, programación cultural, exposición, alquiler de espacio cultural, red de bibliotecas, actividad cultural, infraestructura cultural, casa de la cultura, eventos culturales, difusión literaria, tarifa de espacio');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (92, 'DENICMC', 'DIRECCIÓN DE ECONOMÍA NARANJA, INDUSTRIAS CREATIVAS Y MARCA CIUDAD', 'EJECUTIVO', 'SMCCTAEN', 'EJE-06', 'Desarrollar y ejecutar políticas y proyectos que fortalezcan la economía naranja y las industrias creativas, promoviendo la inversión privada y la innovación cultural, bajo una estrategia de Marca Ciudad que consolide al municipio de La Paz como un referente nacional e internacional de creatividad y talento. ===== PÁGINA 226 ===== 226', 'Desarrolla políticas y proyectos que fortalecen la economía naranja y las industrias creativas. || Diseña y posiciona la estrategia de Marca Ciudad de La Paz a nivel nacional e internacional. || Promueve la inversión privada y la sostenibilidad económica de los emprendimientos creativos. || Organiza actividades en espacios públicos para difundir las economías creativas en los macrodistritos. || Fortalece y articula las organizaciones de los sectores creativos, comunitarios y colaborativos.', 'economía naranja, industrias creativas, marca ciudad, emprendimiento creativo, economía creativa, inversión privada, innovación cultural, sentido de pertenencia, economías colaborativas, economías comunitarias, talento creativo, competitividad, diseño, audiovisual, música, sostenibilidad económica, posicionamiento, ferias creativas');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (93, 'SMCPH', 'SECRETARÍA MUNICIPAL DE CIUDAD PLANIFICADA Y HABITABLE', 'EJECUTIVO', 'SMCPH', 'EJE-07', 'Formular, dirigir, coordinar e implementar políticas, planes, programas y proyectos orientados a consolidar una ciudad planificada, habitable, segura, resiliente y territorialmente ordenada, mediante la planificación del hábitat digno, la gestión del suelo, el catastro multifinalitario, el saneamiento de la propiedad municipal, el mejoramiento y mantenimiento de barrios y vías, la infraestructura resiliente, la reducción de riesgos, la atención de emergencias y la articulación de intervenciones urbanas y rurales que protejan la vida, mejoren la calidad del entorno y fortalezcan el desarrollo territorial del municipio de La Paz.', 'Formula y dirige políticas de planificación territorial, ordenamiento urbano y hábitat digno. || Gestiona el suelo, el catastro multifinalitario y el saneamiento de la propiedad municipal. || Dirige el mejoramiento y mantenimiento de barrios, vías e infraestructura resiliente. || Coordina la reducción de riesgos y la atención de emergencias. || Consolida la información territorial del municipio y lidera procesos de delimitación territorial. || Regula asentamientos humanos, uso de suelo y protección del patrimonio material.', 'planificación urbana, ordenamiento territorial, catastro, uso de suelo, hábitat, vivienda, asentamientos humanos, mantenimiento de vías, mejoramiento de barrios, infraestructura barrial, riesgos, resiliencia urbana, propiedad municipal, delimitación territorial, patrimonio material, edificaciones, planos reguladores, estructura vial, ciudad planificada');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (94, 'PIR', 'PROGRAMA DE INFRAESTRUCTURA RESILIENTE', 'OPERATIVO (PROGRAMA)', 'SMCPH', 'EJE-07', 'Planificar, administrar, coordinar y ejecutar programas, proyectos e intervenciones estratégicas que contribuyan a reducir el riesgo de desastres ante eventos adversos geodinámicos e hidrológicos en el municipio de La Paz con enfoque resiliente y de desarrollo social.', 'Coordinar con el Viceministerio de Inversión Pública y Financiamiento Externo, Organismos Multilaterales y Bilaterales, Agencias de Cooperación y Asistencia Técnica y Fondos de Inversión, la ejecución de programas y/o proyectos. || Realizar las actividades técnicas, administrativas, financieras, jurídicas, ambientales y sociales que permitan viabilizar la ejecución de los productos y resultados esperados, establecidos en los programas y/o proyectos. || Cumplir con los objetivos y metas establecidos en los programas y/o proyectos. || Realizar el monitoreo, seguimiento y control del avance físico-financiero de los programas y/o proyectos. || Realizar los procesos de contratación de Obras, Servicios de No-Consultoría y Servicios de Consultoría y los procesos de adquisición de Bienes, de acuerdo a la normativa vigente para cada caso. || Controlar y realizar seguimiento a los estudios y las obras de programas y/o proyectos, mediante la supervisión y fiscalización de obras, así como a las empresas proveedoras de bienes y servicios. || Coordinar acciones específicas con las áreas y unidades organizacionales del Gobierno Autónomo Municipal de La Paz. || Generar datos institucionales de la atención de desastres y emergencias, para la gestión de riesgos. || Elaborar informes periódicos de ejecución y control de cumplimiento de las condiciones contractuales de los programas y/o proyectos. || Establecer mecanismos de control y seguimiento continuo para la correcta administración y destino de los recursos financieros bajo responsabilidad de los programas y/o proyectos. || Verificar la correcta aplicación de leyes, reglamentos, instructivos, normas, procedimientos y controles internos de administración, tanto de orden general como propios de la entidad. || Cumplir con principios, normas generales y básicas de Control Interno Gubernamental. || Otras que le sean asignadas por la autoridad superior.', NULL);
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (95, 'LSM', 'LABORATORIO DE SUELOS Y MATERIALES', 'OPERATIVO', 'SMCPH', 'EJE-07', 'Prestar oportunamente servicios de laboratorio de suelos y materiales con imparcialidad, en muestras de suelos, concretos, materiales y otro tipo de objetos susceptibles de ser sujetos a estudio, a áreas y unidades organizacionales del Gobierno Autónomo Municipal de La Paz y/o a entidades externas, relacionados con la obtención de muestras, análisis, registro, sistematización y almacenamiento.', 'Programar, dirigir, ejecutar y evaluar las operaciones técnico administrativas de los servicios que presta. || Efectuar la toma de muestras mediante muestreo correspondiente al tipo de ensayo a realizar. || Recibir muestras de áreas y unidades organizacionales solicitantes del Gobierno Autónomo Municipal de La Paz y externos para efectuar el ensayo solicitado. || Ejecutar el análisis, control y diagnóstico de calidad de los suelos, concretos y materiales empleados en las diferentes obras de infraestructura encaradas por el Gobierno Autónomo Municipal de La Paz, a requerimiento. || Compilar, analizar y evaluar los resultados del muestreo en sus diferentes componentes. || Priorizar intervenciones con toma de muestras, análisis y ensayos de acuerdo a la importancia. || Elaborar informes de toma de muestras, ensayos y resultados de laboratorio. || Establecer normas generales para la prestación del servicio al interior del Gobierno Autónomo Municipal de La Paz, así como a externos debiendo generar las tarifas de prestación del servicio que se brinda, el cual debe ser debidamente aprobado.', NULL);
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (96, 'DPTOU', 'DIRECCIÓN DE PLANIFICACIÓN TERRITORIAL Y ORDENAMIENTO URBANO', 'EJECUTIVO', 'SMCPH', 'EJE-07', 'Dirigir la planificación territorial, el ordenamiento urbano y la gestión del hábitat del municipio de La Paz mediante la gestión y administración de procesos de ocupación del territorio urbano y rural del municipio, los usos de suelo y la ocupación sobre predios públicos y privados, asignación de normativa territorial y/o predial, identificando, catalogando y gestionando la declaratoria de bienes patrimoniales del municipio, el tratamiento de los límites intra e inter municipales; así como brindar servicios de autorizaciones y aprobaciones de edificaciones y predios públicos y privados.', 'Dirige la planificación territorial, el ordenamiento urbano y la gestión del hábitat del municipio. || Administra los usos de suelo y la ocupación de predios públicos y privados. || Asigna normativa territorial y predial (patrón de asentamiento, alturas, retiros). || Autoriza y aprueba edificaciones, planos y trámites sobre predios. || Identifica, cataloga y gestiona la declaratoria de bienes patrimoniales. || Atiende los límites intra e intermunicipales y aplica el Modelo de Desarrollo Territorial.', 'ordenamiento urbano, planificación territorial, uso de suelo, aprobación de planos, licencia de construcción, línea y nivel, normativa predial, patrón de asentamiento, regularización de predios, edificaciones, bienes patrimoniales, declaratoria patrimonial, límites municipales, catastro, usr, zonificación, gestión del hábitat, predios públicos, aprobación de edificaciones, modelo de desarrollo territorial');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (97, 'UPHD', 'UNIDAD DE PLANIFICACIÓN DEL HABITAT DIGNO', 'OPERATIVO', 'SMCPH', 'EJE-07', 'Administrar el territorio en cumplimiento y aplicación de las normas relativas a los usos de suelo y asignación de patrones de asentamiento, habilitación de tierras para usos urbanos y rurales, regularización y estructuración de asentamientos humanos, así como actualización y registro de la información física y digital de la base cartográfica de administración territorial del municipio de La Paz; así como elaborar y presentar propuestas para la delimitación de límites territoriales inter municipales y la consolidación de límites intra municipales en el marco de la normativa nacional vigente y normas conexas.', 'Administra los usos de suelo y la asignación de patrones de asentamiento del municipio. || Procesa aprobaciones de habilitación de tierras, planimetrías, estructuras viales y división de lotes. || Regulariza técnica y legalmente asentamientos humanos, diferenciando el derecho propietario municipal. || Actualiza y mantiene la base cartográfica física y digital y el Mapa de Uso de Suelos. || Elabora mapas temáticos y análisis urbano-territorial para la toma de decisiones. || Propone la delimitación de límites intermunicipales y consolida límites intramunicipales.', 'uso de suelo, patrones de asentamiento, planimetría, habilitación de tierras, asentamientos humanos, regularización de lotes, división y partición, base cartográfica, mapa de uso de suelos, límites territoriales, administración territorial, estructura vial, trazos viales, ordenamiento urbano, catastro, planificación urbana, hábitat digno, análisis territorial, aprobación de planos');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (98, 'UGSAS', 'UNIDAD DE GESTIÓN DEL SUELO Y ASENTAMIENTOS SEGUROS', 'OPERATIVO', 'SMCPH', 'EJE-07', 'Administrar en escala predial el área urbana del municipio de La Paz aplicando y generando normativa y lineamientos, procesos y procedimientos para la administración territorial y monitorear procesos de fiscalización territorial en el módulo de seguimiento y control territorial del Sistema de Información Territorial y proteger, valorizar, conservar, recuperar, investigar, identificar, catalogar, promover y difundir el patrimonio material del municipio, garantizando su preservación para las generaciones futuras, mediante la gestión integral y sostenible de los bienes culturales, arqueológicos, históricos y arquitectónicos que conforman la identidad y riqueza cultural del municipio.', 'Administra el suelo urbano en escala predial: emite informes y certificaciones sobre predios y lotes. || Proporciona información técnica para el control y administración del territorio y asentamientos seguros. || Procesa autorizaciones de ubicación y emplazamiento de antenas de telecomunicaciones. || Propone normativa y parámetros técnicos para proyectos individuales, equipamientos e instalaciones especiales. || Monitorea la fiscalización territorial en el Sistema de Información Territorial. || Coadyuva a la conservación, valorización y difusión del patrimonio material del municipio.', 'gestion del suelo, administracion predial, predios, lotes, asentamientos, certificacion predial, antenas de telecomunicaciones, emplazamiento, informacion territorial, fiscalizacion territorial, patrimonio material, uso de suelo, equipamientos urbanos, instalaciones especiales, parametros urbanos, ordenamiento territorial, asentamientos seguros, catastro');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (99, 'DCSP', 'DIRECCIÓN DE CATASTRO Y SANEAMIENTO DE LA PROPIEDAD', 'EJECUTIVO', 'SMCPH', 'EJE-07', 'Dirigir, administrar y regular la gestión catastral multifinalitaria, el registro, saneamiento y administración de información de la propiedad municipal e inmueble a través de la actualización de los registros catastrales, la valoración catastral, la administración de la red geodésica satelital y la emisión de las certificaciones de registro catastral de la propiedad de bienes inmuebles públicos y privados en el territorio del municipio de La Paz; así como gestionar, elaborar, regular y actualizar la base geográfica, cartográfica y geodésica del municipio de La Paz, a través de la captura, procesamiento, análisis, interpretación, almacenamiento, modelización, aplicación y difusión de información digital geoespacial o localizada.', 'Dirige y regula la gestión catastral multifinalitaria del municipio y actualiza los registros catastrales. || Realiza la valoración catastral, actualiza zonas homogéneas, planos de valor y el modelo de valoración. || Emite certificaciones de registro catastral de propiedades públicas y privadas. || Administra la red geodésica satelital y la base geográfica, cartográfica y geodésica del municipio. || Gestiona el saneamiento y la administración de información de la propiedad municipal e inmueble. || Implementa mecanismos e instrumentos de analítica inmobiliaria.', 'catastro, registro catastral, certificado catastral, saneamiento de propiedad, valoración catastral, avalúo, zonas homogéneas, plano de valor, propiedad inmueble, red geodésica, cartografía, geodesia, información geoespacial, límites de predio, predio, lote, planos, analítica inmobiliaria, propiedad municipal, georreferenciación');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (100, 'UCM', 'UNIDAD DE CATASTRO MULTIFINALITARIO', 'OPERATIVO', 'SMCPH', 'EJE-07', 'Administrar el registro y servicios catastrales multifinalitario a través de la creación y actualización de los registros catastrales y la emisión de las Certificaciones de Registro Catastral de la propiedad de bienes inmuebles públicos y privados en el territorio del Municipio de La Paz, integrando información física, jurídica, económica, tributaria, territorial y geoespacial de los predios para apoyar la planificación, gestión urbana, administración tributaria, inversión pública y servicios ciudadanos.', 'Administra el registro catastral de los bienes inmuebles públicos y privados del municipio. || Emite las Certificaciones de Registro Catastral de los predios. || Actualiza la base de datos catastral con información física, jurídica, económica y geoespacial. || Proporciona información gráfica y alfanumérica del catastro a ciudadanos e instituciones. || Propone la creación y modificación de límites de distritos catastrales. || Moderniza y optimiza los procesos de gestión catastral.', 'catastro, registro catastral, certificación catastral, bienes inmuebles, predios, propiedad, base catastral, información geoespacial, distritos catastrales, límites de predio, plano catastral, avalúo, superficie del terreno, datos del inmueble, código catastral, sistema de información geográfica, gestión catastral, registro de propiedad, certificado catastral, cartografía');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (101, 'URSP', 'UNIDAD DE REGISTRO Y SANEAMIENTO DE LA PROPIEDAD', 'OPERATIVO', 'SMCPH', 'EJE-07', 'Sanear, regularizar y registrar el derecho propietario de los bienes inmuebles del Gobierno Autónomo Municipal de La Paz a través del registro técnico y legal en función a normativa vigente, así también generar la información oportuna solicitada por las diferentes áreas y unidades organizacionales del Gobierno Autónomo Municipal de La Paz.', 'Registra e inscribe la propiedad de los bienes inmuebles del municipio ante Derechos Reales. || Ejecuta procesos de saneamiento y regularización técnica y legal de la propiedad municipal ante el INRA y por vía administrativa. || Elabora informes técnicos y legales y anteproyectos de normas para el registro del patrimonio municipal. || Levanta gravámenes de los inmuebles de propiedad municipal. || Gestiona las cesiones de terrenos a favor del municipio. || Emite información sobre la propiedad de bienes inmuebles y bienes de dominio público municipal.', 'registro de propiedad, saneamiento, derechos reales, bienes inmuebles, propiedad municipal, regularización, inra, gravamen, levantamiento de gravamen, cesión de terreno, dominio público, titulación, folio real, patrimonio municipal, inscripción de inmueble, informe técnico legal, terrenos municipales, derecho propietario');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (102, 'DIMMBV', 'DIRECCIÓN DE INFRAESTRUCTURA, MEJORAMIENTO Y MANTENIMIENTO DE BARRIOS Y VÍAS', 'EJECUTIVO', 'SMCPH', 'EJE-07', 'Planificar y ejecutar proyectos para infraestructuras estratégicas de acuerdo a normativa vigente, asegurando la calidad de las obras civiles; brindar mantenimiento preventivo y correctivo de infraestructura urbana, así como la construcción, mejoramiento y ampliación de la infraestructura vial, así como ejecutar acciones de administración y ampliación del servicio a la red de alumbrado público, ejecutar el mantenimiento del sistema semafórico y la gestión de la comunicación; asimismo, la gestión del tráfico; así también planificar y desarrollar Estudios de Diseño Técnico de Preinversión y proyectos dirigidos a la construcción de infraestructura pública municipal conforme a normativa vigente y de proyectos priorizados por la Máxima Autoridad Ejecutiva, brindando asistencia técnica a otras áreas y unidades organizacionales; promoviendo el desarrollo comunitario sostenible.', 'Planifica y ejecuta obras de infraestructura estratégica y obras públicas municipales. || Construye, mejora y amplía vías, calles y equipamiento urbano del municipio. || Da mantenimiento preventivo y correctivo a barrios, vías y espacios públicos. || Administra y amplía la red de alumbrado público y el mantenimiento del sistema semafórico. || Gestiona el tráfico y la comunicación vial de la ciudad. || Elabora diseños técnicos, memorias de cálculo y planos, y ejecuta obras por administración delegada.', 'obras, infraestructura, vías, calles, mantenimiento de barrios, alumbrado público, luminarias, semáforos, asfaltado, pavimento, bacheo, equipamiento urbano, obras públicas, tráfico, señalización vial, aceras, puentes, diseño técnico, administración delegada, obra civil');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (103, 'UDEPR', 'UNIDAD DE DISEÑOS Y ESTUDIOS DE PREINVERSIÓN', 'OPERATIVO', 'SMCPH', 'EJE-07', 'Elaborar Estudios de Diseño Técnico de Preinversión y proyectos de infraestructura municipales en el Gobierno Autónomo Municipal de La Paz, bajo normativa vigente asegurando calidad técnica, viabilidad, sostenibilidad, reducción de riesgos y alineación con prioridades institucionales y territoriales.', 'Elabora Estudios de Diseño Técnico de Preinversión (EDTP) para obras municipales. || Diseña proyectos de nuevas construcciones, ampliaciones, remodelaciones y revitalizaciones de infraestructura. || Desarrolla los componentes de arquitectura de los proyectos. || Gestiona la Licencia Ambiental de los estudios y proyectos ante Ciudad Verde. || Requiere a las unidades solicitantes la información técnica necesaria para los diseños.', 'preinversión, diseño técnico, edtp, estudios de diseño, proyectos de infraestructura, arquitectura, planos, itcp, términos de referencia, licencia ambiental, construcciones, ampliaciones, remodelaciones, revitalización, diseño de obras, ingeniería, presupuesto de obra, cómputos métricos');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (104, 'UDMIEU', 'UNIDAD DE DESARROLLO Y MANTENIMIENTO DE INFRAESTRUCTURA Y EQUIPAMIENTO URBANO', 'OPERATIVO', 'SMCPH', 'EJE-07', 'Ejecutar proyectos de inversión relacionados a obras de arquitectura e ingeniería especializadas que involucren el empleo de técnicas, tecnologías y materiales de características particulares; y ejecutar el mantenimiento preventivo y correctivo de la infraestructura urbana, así como planificar, organizar y ejecutar actividades de infraestructura por administración directa orientadas a la revitalización urbana y mejora de las condiciones de habitabilidad del municipio, y ejecutar planes, programas y proyectos para la construcción, mejoramiento y mantenimiento de la infraestructura y señalización vial en el municipio de La Paz.', 'Ejecuta obras de arquitectura e ingeniería especializada con técnicas y materiales particulares. || Realiza el mantenimiento preventivo y correctivo de la infraestructura urbana estratégica. || Ejecuta obras por administración directa para la revitalización urbana y mejora de la habitabilidad. || Construye, mejora y mantiene la infraestructura y señalización vial del municipio. || Hace seguimiento a convenios de financiamiento y contratos de ejecución de obras. || Mantiene una base de datos del estado y funcionamiento de las infraestructuras estratégicas.', 'infraestructura urbana, mantenimiento vial, señalización vial, obras de arquitectura, ingeniería especializada, administración directa, revitalización urbana, mobiliario urbano, puentes, graderías, pasarelas, espacios públicos, obras estratégicas, mejoramiento urbano, equipamiento urbano, aceras, escalinatas, muros de contención, señalización horizontal, mantenimiento preventivo');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (105, 'USE', 'UNIDAD DE SERVICIOS ELÉCTRICOS', 'OPERATIVO', 'SMCPH', 'EJE-07', 'Gestionar el servicio de alumbrado público y el mantenimiento de semaforización del municipio de La Paz; así como, administrar y garantizar la radiocomunicación y brindar asistencia técnica en el ámbito de las competencias de la unidad para la institución.', 'Gestiona el alumbrado público de la ciudad: diseño, ampliación, mejoramiento y reubicación de luminarias. || Realiza mantenimiento preventivo, correctivo y atención de urgencias de luminarias y postes. || Da seguimiento a la reposición de daños en infraestructura de alumbrado y semáforos. || Planifica, ejecuta y moderniza el sistema de semaforización de la ciudad. || Monitorea el funcionamiento del sistema semafórico. || Administra la radiocomunicación y brinda asistencia técnica eléctrica a la institución.', 'servicios eléctricos, alumbrado público, luminarias, postes de luz, semáforos, semaforización, foco quemado, poste caído, mantenimiento eléctrico, eficiencia energética, radiocomunicación, iluminación de calles, reposición de luminarias, urgencias eléctricas, sistema semafórico, instalación eléctrica, cableado público, modernización de semáforos');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (106, 'DPRRU', 'DIRECCIÓN DE PREVENCIÓN DE RIESGOS Y RESILIENCIA URBANA', 'EJECUTIVO', 'SMCPH', 'EJE-07', 'Implementar acciones de reducción del riesgo de desastres mediante la aplicación de medidas estructurales y no estructurales para mitigar los eventos geodinámicos e hidrológicos en las cuencas del municipio de La Paz; y fortalecer la resiliencia del municipio de La Paz frente a desastres socio-naturales de manera multisectorial, integrando tecnologías y prácticas innovadoras para fortalecer la capacidad de respuesta municipal ante diversas amenazas mediante la identificación y análisis del riesgo, el desarrollo de proyectos estructurales de reducción de riesgos de desastres y la administración del Sistema de Alerta Temprana; así como la atención de emergencias municipales.', 'Ejecuta obras y medidas estructurales y no estructurales para reducir el riesgo de deslizamientos, mazamorras e inundaciones. || Interviene las cuencas del municipio frente a eventos geodinámicos e hidrológicos. || Administra el Sistema de Alerta Temprana y fortalece la capacidad de respuesta municipal ante amenazas. || Identifica y analiza zonas de riesgo para prevenir desastres socio-naturales. || Atiende emergencias municipales y coordina la respuesta con otras áreas del GAMLP.', 'riesgos, deslizamiento, mazamorra, inundacion, riada, alerta temprana, emergencia, desastre, prevencion de riesgos, cuencas, resiliencia urbana, gestion de riesgos, geodinamica, obras de mitigacion, muro de contencion, reduccion de riesgo de desastres, amenazas naturales, vulnerabilidad');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (107, 'UCRRH', 'UNIDAD DE CUENCAS Y REDUCCIÓN DEL RIESGO HIDROLÓGICO', 'OPERATIVO', 'SMCPH', 'EJE-07', 'Evaluar las características y amenazas referidas a ríos, quebradas y torrenteras, con el fin de proponer e implementar medidas de prevención, mitigación y recuperación para la reducción de riesgos hidrológicos en el municipio de La Paz.', 'Inspecciona y monitorea embovedados, canales, lechos y estructuras en ríos, quebradas y torrenteras del municipio. || Evalúa amenazas hidrológicas y propone medidas de prevención, mitigación y recuperación para reducir riesgos. || Evalúa proyectos de infraestructura hidráulica y recomienda la ejecución de obras y su pertinencia. || Verifica la ejecución de obras de regulación de cauces, control de torrenteras y control de erosión. || Elabora y ejecuta el Plan de Reducción del Riesgo de Desastres para ríos y torrenteras en época de estiaje. || Elabora proyectos de reparación y mantenimiento de obras hidráulicas y coadyuva a los planes de contingencia y emergencias.', 'cuencas, ríos, quebradas, torrenteras, riesgo hidrológico, embovedado, canales, obras hidráulicas, regulación de cauces, control de erosión, inundaciones, áridos, lecho de río, reducción de riesgo de desastres, plan de contingencia, época de lluvias, estiaje, mazamorra, defensivos, gaviones, manejo de cuencas');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (108, 'URRG', 'UNIDAD DE REDUCCIÓN DEL RIESGO GEODINÁMICO', 'OPERATIVO', 'SMCPH', 'EJE-07', 'Evaluar las características y amenazas geológicas y de riesgos con el fin de proponer medidas de prevención y mitigación de reducción de riesgos geodinámicos en el municipio de La Paz.', 'Evalúa amenazas geológicas y riesgos geodinámicos (deslizamientos, mazamorras, hundimientos) en el municipio. || Implementa el Plan de Reducción del Riesgo de Desastres para movimientos geodinámicos. || Realiza estudios geológicos y geotécnicos y emite informes técnicos a solicitud de otras unidades y vecinos. || Monitorea zonas inestables mediante testigos de estuco e inspección visual. || Recomienda obras de prevención y mitigación para controlar áreas inestables. || Inspecciona y evalúa terrenos ante amenazas naturales o antrópicas para la toma de decisiones.', 'riesgo geodinámico, deslizamiento, mazamorra, movimiento de tierra, hundimiento, grietas, estudio geológico, estudio geotécnico, geología, zona inestable, mitigación de riesgos, prevención de desastres, monitoreo de laderas, testigos de estuco, mapa de riesgos, inspección de terreno, amenaza natural, reducción del riesgo, taludes, estabilidad de suelos, época de lluvias');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (109, 'UPGR', 'UNIDAD DE PROYECTOS DE GESTIÓN DEL RIESGO', 'OPERATIVO', 'SMCPH', 'EJE-07', 'Desarrollar proyectos de preinversión estructurales orientados a la gestión del riesgo de desastres, en el municipio de La Paz.', 'Elabora estudios de preinversión (EDTP) para obras estructurales de gestión del riesgo de desastres. || Prioriza los estudios en zonas declaradas en emergencia o desastre. || Orienta técnicamente a otras unidades en estudios para estabilizar zonas de riesgo. || Supervisa las consultorías que contrata para elaborar los estudios de preinversión. || Aporta datos de amenazas y riesgos para actualizar el Mapa de Riesgos y la base geográfica.', 'gestión del riesgo, preinversión, edtp, estudio técnico, deslizamiento, estabilización de zona, mapa de riesgos, zona de riesgo, desastre, emergencia, amenazas, vulnerabilidad, obra estructural, diseño técnico, muro de contención, consultoría de estudios, riesgo de desastres, movimiento de tierras');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (110, 'USAT', 'UNIDAD DE SISTEMA DE ALERTA TEMPRANA', 'OPERATIVO', 'SMCPH', 'EJE-07', 'Administrar el Sistema de Alerta Temprana ante fenómenos hidrometeorológicos y geotécnicos facilitando la toma de decisiones adecuadas y oportunas, orientadas a la preparación y respuesta con el propósito de reducción del impacto de las amenazas sobre la población.', 'Administra el Sistema de Alerta Temprana ante lluvias, inundaciones y deslizamientos. || Emite pronósticos y reportes meteorológicos oportunos para la ciudad. || Monitorea condiciones hidrometeorológicas y hace monitoreo geotécnico en zonas de riesgo. || Genera y comunica las alertas municipales a las áreas responsables y a la población. || Difunde alertas por aplicación móvil, redes sociales y plataformas tecnológicas. || Da mantenimiento a los equipos, sensores y redes del Sistema de Alerta Temprana.', 'alerta temprana, lluvias, inundaciones, deslizamientos, pronóstico meteorológico, hidrometeorología, monitoreo geotécnico, zonas de riesgo, alerta municipal, riada, desborde, sensores, estaciones meteorológicas, mapa de riesgos, granizada, temporada de lluvias, simulacro, reporte de lluvias, amenazas naturales');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (111, 'UAE', 'UNIDAD DE ATENCIÓN DE EMERGENCIAS', 'OPERATIVO', 'SMCPH', 'EJE-07', 'Efectuar la atención de desastres y/o emergencias a través de la preparación y respuesta ante la ocurrencia de eventos adversos de origen natural y antrópico, así como la coordinación y gestión en acciones de rehabilitación y alerta; en coordinación con otras áreas y unidades organizacionales del Gobierno Autónomo Municipal de La Paz e instituciones públicas y/o privadas.', 'Atiende de forma inmediata desastres y emergencias a través de la línea gratuita Red 114. || Elabora e implementa el Plan de Emergencia y los Planes de Contingencia Municipal. || Gestiona maquinaria y equipo pesado para la atención de emergencias. || Dirige al Grupo de Atención a Emergencias (GAEM) y a las Cuadrillas de Acción Inmediata (CAI). || Ejecuta obras de mantenimiento y reparación de control hidráulico y geodinámico para reducir riesgos. || Coordina acciones de rehabilitación tras eventos adversos.', 'emergencias, desastres, red 114, deslizamientos, inundaciones, riadas, mazamorras, granizadas, plan de contingencia, gaem, cuadrillas de acción inmediata, cai, maquinaria pesada, control hidráulico, geodinámica, primera respuesta, rehabilitación, eventos adversos, atención de emergencias, alerta temprana');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (112, 'SMCCMU', 'SECRETARÍA MUNICIPAL DE CIUDAD CONECTADA Y MOVILIDAD URBANA', 'EJECUTIVO', 'SMCCMU', 'EJE-08', 'Formular, dirigir, coordinar e implementar políticas, planes, programas y proyectos orientados a consolidar una ciudad conectada, accesible, segura, inclusiva, integrada y eficiente, mediante la planificación de la movilidad urbana, el fortalecimiento del sistema integrado de transporte, la promoción de movilidad activa y sostenible, la gestión vehicular digital, la infraestructura vial estratégica, la logística urbana inteligente y la conectividad urbana-rural, contribuyendo a reducir tiempos de viaje, mejorar la seguridad vial, ordenar el transporte y elevar la calidad de vida de la población del municipio de La Paz.', 'Formula y dirige las políticas de movilidad urbana, transporte, tránsito y seguridad vial del municipio. || Elabora el Plan de Movilidad Urbana Sostenible y el Programa Municipal de Transporte. || Norma, regula y controla el servicio público de transporte urbano de pasajeros y carga. || Emite autorizaciones, permisos y asignaciones a los operadores de transporte. || Promueve la movilidad activa y sostenible y fortalece el sistema integrado de transporte (PumaKatari, teleférico). || Coordina con la ATT, operadores y entidades públicas y privadas la gestión del tránsito y transporte. || Impulsa la gestión vehicular digital, la logística urbana y la conectividad urbano-rural.', 'movilidad urbana, transporte público, tránsito, seguridad vial, pumakatari, sindicatos de transporte, minibuses, permisos de transporte, rutas de transporte, movilidad activa, ciclovías, plan de movilidad sostenible, logística urbana, operadores de transporte, att, tarjeta de operación, paradas, transporte de carga, gestión vehicular, conectividad urbano-rural, semáforos, congestión vehicular');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (113, 'DMUSIT', 'DIRECCIÓN DE MOVILIDAD URBANA Y SISTEMA INTEGRADO DE TRANSPORTE', 'EJECUTIVO', 'SMCCMU', 'EJE-08', 'Dirigir la planificación, regulación, seguimiento y mejora de la movilidad urbana y del sistema integrado de transporte del municipio de La Paz, promoviendo transporte público eficiente, movilidad activa, seguridad vial, gestión vehicular digital, accesibilidad universal, información para la toma de decisiones y articulación operativa con actores públicos, privados y sociales.', 'Planifica y regula la movilidad urbana y el sistema integrado de transporte del municipio. || Supervisa y fiscaliza el transporte público y el tránsito en la jurisdicción de La Paz. || Evalúa y otorga habilitaciones, autorizaciones, permisos y licencias de funcionamiento a operadores de transporte. || Emite la Tarjeta Municipal de Operación Vehicular y la Tarjeta de Identificación del Conductor. || Impone sanciones administrativas en materia de transporte y tránsito, de oficio o por denuncia. || Elabora estándares técnicos para el servicio de transporte, la movilidad activa y la seguridad vial.', 'movilidad urbana, transporte público, sistema integrado de transporte, tránsito, seguridad vial, tarjeta de operación vehicular, licencia de funcionamiento transporte, radio taxi, operadores de transporte, permisos de transporte, sanciones de tránsito, movilidad activa, accesibilidad universal, habilitación vehicular, identificación del conductor, minibuses, microbuses, rutas de transporte, fiscalización de transporte, planificación vial');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (114, 'UMSSIA', 'UNIDAD DE MOVILIDAD SOSTENIBLE, SEGURA, INCLUSIVA Y ACTIVA', 'OPERATIVO', 'SMCCMU', 'EJE-08', 'Diseñar e implementar programas de movilidad sostenible, segura, inclusiva y activa, promoviendo la caminabilidad, el uso de bicicleta, la accesibilidad universal, la seguridad vial, la educación ciudadana y la reducción de riesgos en los desplazamientos cotidianos de la población.', 'Diseña e implementa programas de movilidad peatonal, ciclista, accesible, segura e inclusiva. || Planifica y gestiona la red de ciclovías, ciclo rutas y circuitos peatonales, incluida la micro-movilidad. || Implementa pilotos de zonas 30, vías calmadas, calles compartidas y peatonalizaciones temporales. || Promueve campañas de educación vial y respeto al peatón, ciclista, personas con discapacidad y adulto mayor. || Diseña programas de movilidad escolar segura, rutas seguras y entornos escolares protegidos. || Institucionaliza el día del peatón y del ciclista y propone normativa de movilidad inclusiva. || Identifica zonas y corredores prioritarios para mejorar la caminabilidad y la seguridad vial.', 'movilidad sostenible, ciclovia, bicicleta, peaton, caminabilidad, seguridad vial, educacion vial, accesibilidad universal, zona 30, via calmada, peatonalizacion, ciclista, movilidad escolar, ruta segura, micro movilidad, dia del peaton, circuito peatonal, movilidad inclusiva, calle compartida, entorno escolar seguro');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (115, 'UGVCD', 'UNIDAD DE GESTIÓN VEHICULAR Y CONTROL DIGITAL', 'OPERATIVO', 'SMCCMU', 'EJE-08', 'Regular la movilidad y los servicios de transporte urbano de pasajeros y carga del municipio de La Paz y gestionar información, registros, monitoreo y control de la circulación vehicular, transporte, tránsito y servicios asociados, mediante herramientas tecnológicas, datos, análisis operativo y coordinación institucional para mejorar la fluidez, seguridad, control y eficiencia de la movilidad urbana; así como supervisar y fiscalizar el cumplimiento de las normas sobre el sistema de tránsito y movilidad urbana en el ámbito de su competencia.', 'Supervisa y fiscaliza los servicios de transporte urbano de pasajeros y carga del municipio. || Administra sistemas digitales de información, registro, monitoreo y control de movilidad, transporte y tránsito. || Atiende denuncias sobre transporte, estacionamientos y paradas momentáneas, y solicitudes de rechazo o conmutación de sanciones. || Planifica operativos de control al transporte, estacionamientos, cierre y uso de vías, junto a la Guardia Municipal. || Analiza zonas de alta congestión, rutas saturadas y puntos críticos de circulación. || Evalúa técnicamente la otorgación o rechazo de habilitaciones, autorizaciones, permisos y asignación de rutas.', 'transporte urbano, movilidad urbana, tránsito, control vehicular, estacionamiento, parada momentánea, ruta, recorrido, minibús, micro, operador de transporte, habilitación de transporte, sanción de tránsito, conmutación de sanción, congestión vehicular, operativo de control, cierre de vías, guardia municipal, monitoreo digital, cámaras de tránsito, sindicato de transporte, permiso municipal');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (116, 'USIT', 'UNIDAD DE SISTEMA INTEGRADO DE TRANSPORTE', 'OPERATIVO', 'SMCCMU', 'EJE-08', 'Gestionar la planificación, articulación, seguimiento y mejora del Sistema Integrado de Transporte del municipio de La Paz, promoviendo integración física, operacional, tarifaria, tecnológica e informativa entre modos de transporte, con criterios de eficiencia, inclusión, seguridad, sostenibilidad y calidad de servicio.', 'Planifica y articula el Sistema Integrado de Transporte del municipio de La Paz. || Elabora el Plan de Movilidad Urbana Sostenible (PMUS) y el Programa Municipal de Transporte (PROMUT). || Analiza, aprueba y modifica rutas y recorridos del transporte público de pasajeros. || Elabora estudios técnicos para fijar las tarifas del transporte de pasajeros y carga. || Diseña el Plan de Gestión de Estacionamientos y medidas de tráfico y seguridad vial. || Proyecta el transporte multimodal integrando modos masivo, colectivo, activo y complementario.', 'transporte público, sistema integrado de transporte, movilidad urbana, pmus, promut, rutas, recorridos, paradas, tarifas de transporte, pasaje, estacionamientos, tráfico, seguridad vial, transporte multimodal, minibuses, microbuses, puma katari, teleférico, movilidad sostenible, circulación vehicular, peatonalización, carga');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (117, 'DILCT', 'DIRECCIÓN DE INFRAESTRUCTURA, LOGÍSTICA Y CONECTIVIDAD TERRITORIAL', 'EJECUTIVO', 'SMCCMU', 'EJE-08', 'Dirigir la planificación, coordinación y seguimiento de infraestructura vial estratégica, logística urbana inteligente y conectividad urbana-rural, articulando proyectos que mejoren accesibilidad, circulación, abastecimiento, integración territorial, competitividad económica y conexión segura entre barrios, comunidades, centralidades y servicios municipales.', 'Dirige la planificación de infraestructura vial estratégica y la conectividad urbana-rural del municipio. || Identifica corredores, rutas, nodos, accesos y puntos críticos que requieren intervención vial. || Diseña estrategias de logística urbana para ordenar carga, descarga, abastecimiento y circulación de vehículos de servicio. || Coordina con Ciudad Planificada y Habitable el diseño y ejecución de proyectos viales. || Propone normativa y criterios técnicos y desarrolla indicadores de conectividad, tiempos de viaje y seguridad vial.', 'infraestructura vial, conectividad territorial, logística urbana, vías estratégicas, corredores, accesos, rutas, carga y descarga, abastecimiento, seguridad vial, puntos críticos, movilidad, circulación, integración territorial, proyectos viales, nodos logísticos, conexión urbana rural, accesibilidad, tiempos de viaje');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (118, 'UIVE', 'UNIDAD DE INFRAESTRUCTURA VIAL ESTRATÉGICA', 'OPERATIVO', 'SMCCMU', 'EJE-08', 'Gestionar la planificación y seguimiento de proyectos de infraestructura vial estratégica del municipio de La Paz, orientados a mejorar la conectividad, seguridad vial, accesibilidad, integración territorial, eficiencia de desplazamientos y soporte físico del sistema de movilidad urbana.', 'Identifica y prioriza proyectos de infraestructura vial estratégica: corredores, puentes, accesos e intersecciones. || Coordina la elaboración de estudios, perfiles y diseños técnicos de proyectos viales. || Incorpora criterios de seguridad vial, accesibilidad universal, drenaje y movilidad activa en los proyectos. || Sistematiza información sobre el estado de las vías estratégicas, avances, riesgos y costos. || Propone intervenciones en puntos críticos de congestión, siniestralidad o deterioro vial.', 'infraestructura vial, vías estratégicas, corredores, puentes, intersecciones, distribuidores, conectividad vial, seguridad vial, accesibilidad universal, movilidad urbana, congestión, puntos críticos, pasos a desnivel, estudios de preinversión, diseño vial, drenaje vial, siniestralidad, movilidad activa, integración territorial');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (119, 'ULUI', 'UNIDAD DE LOGÍSTICA URBANA INTELIGENTE', 'OPERATIVO', 'SMCCMU', 'EJE-08', 'Diseñar e implementar políticas y mecanismos de logística urbana inteligente para ordenar la distribución de bienes, carga y descarga, abastecimiento de mercados, circulación de vehículos de servicio, horarios, zonas logísticas y gestión de información, reduciendo congestión, conflictos de uso vial, emisiones y costos urbanos.', 'Diseña políticas de logística urbana para ordenar la carga, descarga y distribución de bienes. || Identifica zonas críticas de congestión, abastecimiento de mercados y conflictos entre transporte, comercio y peatones. || Propone normativa y horarios para la circulación de vehículos de servicio y zonas logísticas. || Implementa pilotos de ordenamiento logístico en zonas priorizadas. || Evalúa resultados en reducción de congestión, tiempos, emisiones y conflictos viales.', 'logística urbana, carga y descarga, distribución de bienes, abastecimiento de mercados, congestión vehicular, zonas logísticas, horarios de carga, camiones, reparto, transporte de mercancías, ordenamiento logístico, vehículos de servicio, conflictos viales, emisiones, pilotos logísticos, última milla, circulación de camiones, descongestión');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (120, 'UCUR', 'UNIDAD DE CONECTIVIDAD URBANA Y RURAL', 'OPERATIVO', 'SMCCMU', 'EJE-08', 'Gestionar programas y proyectos de conectividad urbana y rural orientados a mejorar el acceso entre barrios, comunidades, servicios, mercados, equipamientos, zonas productivas y destinos turísticos, fortaleciendo la integración territorial, la seguridad, la respuesta a emergencias y las oportunidades de desarrollo del municipio.', 'Identifica brechas de conectividad urbana y rural en barrios, comunidades y rutas de difícil acceso. || Propone proyectos de inversión, mantenimiento o cooperación para mejorar accesos y caminos. || Elabora indicadores de accesibilidad, tiempo de viaje, cobertura y población beneficiada. || Coordina con organizaciones comunitarias el cuidado y seguimiento de las intervenciones. || Emite reportes sobre caminos, accesos, avances y necesidades de conectividad.', 'conectividad, conectividad rural, caminos vecinales, accesos, rutas productivas, sendas, puentes vehiculares, puentes peatonales, integración territorial, zonas de difícil acceso, tiempo de viaje, accesibilidad, comunidades rurales, apertura de caminos, mantenimiento de caminos, rutas turísticas, conectividad barrial, cobertura territorial');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (121, 'SMCVE', 'SECRETARÍA MUNICIPAL DE CIUDAD VERDE', 'EJECUTIVO', 'SMCVE', 'EJE-09', 'Dirigir la transición ecológica justa del municipio de La Paz mediante la formulación, implementación y evaluación de políticas, planes, programas y proyectos orientados a consolidar una Ciudad Verde, sostenible, resiliente, limpia, biodiversa y ambientalmente responsable, mediante la gestión ambiental urbana integral, educación y cultura ambiental comunitaria, conservación y restauración de ecosistemas urbanos, resiliencia, adaptación y mitigación del cambio climático, gestión hídrica, energías sostenibles, conservación de la biodiversidad, incluyendo fauna silvestre, gestión integral de residuos sólidos, economía circular, reciclaje inclusivo, y la consolidación de la agricultura urbana hacia los sistemas alimentarios sostenibles.', 'Dirige las políticas de gestión ambiental urbana, áreas verdes, parques y áreas protegidas municipales. || Impulsa la resiliencia, adaptación y mitigación del cambio climático, la gestión hídrica y las energías sostenibles. || Supervisa la gestión integral de residuos sólidos, la economía circular y el reciclaje inclusivo. || Conserva la biodiversidad urbana y la fauna silvestre, incluyendo el Bioparque Municipal Vesty Pakos. || Desarrolla educación y cultura ambiental comunitaria y buenas prácticas ciudadanas. || Promueve la forestación, reforestación, el arbolado urbano y la agricultura urbana sostenible.', 'medio ambiente, ciudad verde, áreas verdes, parques, áreas protegidas, arbolado urbano, forestación, reforestación, cambio climático, residuos sólidos, economía circular, reciclaje, biodiversidad, fauna silvestre, bioparque vesty pakos, gestión hídrica, energías sostenibles, educación ambiental, agricultura urbana, transición ecológica, contaminación, saneamiento básico');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (122, 'DGACCBU', 'DIRECCIÓN DE GESTIÓN AMBIENTAL, CAMBIO CLIMÁTICO Y BIODIVERSIDAD URBANA', 'EJECUTIVO', 'SMCVE', 'EJE-09', 'Dirigir la gestión ambiental integral en el municipio de La Paz, mediante programas, educación y cultura ambiental comunitaria, conservación y restauración de ecosistemas, áreas verdes, parques, áreas protegidas municipales y otros espacios de conservación, forestación y reforestación, resiliencia, adaptación y mitigación del cambio climático, gestión hídrica, energía sostenibles y ecoeficiencia, biodiversidad incluyendo fauna silvestre, promoviendo la corresponsabilidad ciudadana y sostenibilidad territorial, y ejerciendo como autoridad ambiental municipal las funciones de prevención, control, seguimiento y evaluación ambiental municipal, garantizando cumplimiento normativo, prevención de impactos, atención de denuncias y aplicación de medidas correctivas. ===== PÁGINA 305 ===== 305', 'Dirige la gestión ambiental integral del municipio: educación ambiental, áreas verdes, parques y áreas protegidas. || Conduce programas de forestación, reforestación, arbolado urbano y recuperación de espacios públicos. || Actúa como autoridad ambiental municipal: previene, controla, fiscaliza y sanciona impactos ambientales. || Atiende denuncias de contaminación (residuos, emisiones, ruido, agua) y realiza inspecciones técnicas a actividades económicas. || Impulsa acciones de adaptación y mitigación del cambio climático, gestión hídrica, drenaje sostenible y energías limpias. || Conserva la biodiversidad urbana y la fauna silvestre. || Coordina con Subalcaldías la implementación territorial de los programas ambientales.', 'medio ambiente, gestion ambiental, cambio climatico, areas verdes, parques, areas protegidas, forestacion, reforestacion, arbolado urbano, arboles, biodiversidad, fauna silvestre, contaminacion, ruido, emisiones, denuncia ambiental, licencia ambiental, autoridad ambiental, educacion ambiental, recursos hidricos, energias sostenibles, fiscalizacion ambiental, corredores ecologicos');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (123, 'UGAUCA', 'UNIDAD DE GESTIÓN AMBIENTAL URBANA Y CULTURA AMBIENTAL', 'OPERATIVO', 'SMCVE', 'EJE-09', 'Implementar programas para fortalecer la gestión ambiental integral urbana de todo el municipio, y desarrollar una cultura ambiental comunitaria, promoviendo educación, participación, corresponsabilidad ciudadana, buenas prácticas ambientales, uso responsable de recursos y hábitos sostenibles en barrios, unidades educativas, mercados, espacios públicos, comunidades, y en la ciudadanía en general, y desarrollar acciones técnicas para la prevención, control, seguimiento y evaluación ambiental municipal, garantizando cumplimiento normativo, prevención de impactos, atención de denuncias y aplicación de medidas correctivas dentro del ámbito competencial del municipio.', 'Implementa programas de gestión ambiental urbana integral en todo el municipio. || Establece indicadores de calidad ambiental y monitorea agua, aire y suelo. || Diseña campañas y programas de educación y cultura ambiental en barrios, mercados, unidades educativas y espacios públicos. || Promueve huertos escolares, reciclaje, forestación, separación de residuos y producción verde. || Realiza seguimiento y control ambiental de actividades, obras y proyectos que puedan afectar el medio ambiente. || Apoya técnicamente a la autoridad ambiental municipal en el cumplimiento de la reglamentación ambiental y atención de denuncias.', 'gestión ambiental, medio ambiente, cultura ambiental, educación ambiental, calidad del aire, calidad del agua, monitoreo ambiental, reciclaje, separación de residuos, forestación, reforestación, huertos escolares, contaminación, denuncia ambiental, impacto ambiental, licencia ambiental, transición ecológica, producción verde, campañas ambientales, residuos sólidos, control ambiental, sostenibilidad');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (124, 'UAVRPU', 'UNIDAD DE ÁREAS VERDES, REFORESTACIÓN Y PARQUES URBANOS', 'OPERATIVO', 'SMCVE', 'EJE-09', 'Gestionar, mantener, recuperar, ampliar, áreas verdes, parques, áreas protegidas municipales y otros espacios de conservación, arbolado y desarrollar programas y proyectos de revegetación, forestación y reforestación del municipio de La Paz, promoviendo espacios públicos saludables, seguros, accesibles, biodiversos, resilientes y de encuentro ciudadano.', 'Mantiene, recupera y amplía áreas verdes, parques, plazas y áreas protegidas municipales. || Ejecuta programas de forestación, reforestación y arbolado urbano. || Elabora normativa técnica para la conservación del arbolado, bosques y áreas forestales. || Diseña corredores verdes, infraestructura verde y reposición vegetal. || Coordina con Subalcaldías el mantenimiento de áreas verdes y parques barriales. || Articula con otras direcciones la iluminación y la mejora de parques en zonas de riesgo.', 'áreas verdes, parques, plazas, arbolado urbano, árboles, forestación, reforestación, poda, jardines, áreas protegidas municipales, corredores verdes, revegetación, infraestructura verde, espacios públicos, taludes, mantenimiento de parques, plantación, vivero, cobertura vegetal, biodiversidad urbana, riego de áreas verdes');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (125, 'UACGHES', 'UNIDAD DE ADAPTACIÓN CLIMÁTICA, GESTIÓN HÍDRICA Y ENERGÍA SOSTENIBLE', 'OPERATIVO', 'SMCVE', 'EJE-09', 'Implementar programas y proyectos de adaptación y mitigación climática, gestión hídrica urbana, energía sostenible y ecoeficiencia, para fortalecer la resiliencia del municipio, mediante soluciones basadas en naturaleza, diseño climáticamente inteligente, en el marco de las competencias establecidas.', 'Ejecuta programas y proyectos de adaptación y mitigación al cambio climático, gestión hídrica y energía sostenible. || Elabora diagnósticos de vulnerabilidad climática, estrés hídrico e islas de calor. || Promueve el uso eficiente del agua, la cosecha de agua, el drenaje urbano sostenible y soluciones basadas en la naturaleza. || Propone normativa, protocolos y lineamientos de resiliencia climática y ecoeficiencia para todo el municipio. || Monitorea indicadores de resiliencia y apoya proyectos con financiamiento climático de cooperación internacional.', 'cambio climático, adaptación climática, mitigación, gestión hídrica, agua, energía sostenible, ecoeficiencia, resiliencia, cosecha de agua, drenaje urbano, islas de calor, estrés hídrico, soluciones basadas en naturaleza, energías renovables, vulnerabilidad climática, financiamiento climático, eficiencia energética, recursos hídricos, diseño climático');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (126, 'UBUPFS', 'UNIDAD DE BIODIVERSIDAD URBANA Y PROTECCIÓN DE FAUNA SILVESTRE', 'OPERATIVO', 'SMCVE', 'EJE-09', 'Gestionar la protección, conservación y monitoreo de la biodiversidad urbana y fauna silvestre del municipio, promoviendo hábitats saludables, educación ambiental, atención de casos de fauna, articulación con el Bioparque Municipal Vesty Pakos y prevención de afectaciones a especies y ecosistemas urbanos.', 'Protege, conserva y monitorea la biodiversidad urbana y la fauna silvestre del municipio. || Coordina con el Bioparque Vesty Pakos el rescate, custodia y rehabilitación de fauna silvestre. || Controla y fiscaliza el tráfico y las afectaciones a especies y ecosistemas urbanos. || Identifica y conserva corredores biológicos, hábitats y áreas de importancia ambiental. || Realiza campañas de educación ambiental sobre convivencia responsable y prevención del daño a especies. || Coordina con vecinos y subalcaldías la detección de casos de tráfico de fauna silvestre.', 'biodiversidad urbana, fauna silvestre, bioparque vesty pakos, rescate de animales, tráfico de fauna, conservación, ecosistemas urbanos, corredores biológicos, hábitat, educación ambiental, vida silvestre, animales silvestres, rehabilitación de fauna, aves, especies protegidas, monitoreo ambiental, fiscalización ambiental, protección de especies');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (127, 'DRSECPV', 'DIRECCIÓN DE RESIDUOS SÓLIDOS, ECONOMÍA CIRCULAR Y PRODUCCIÓN VERDE', 'EJECUTIVO', 'SMCVE', 'EJE-09', 'Dirigir la gestión integral de residuos sólidos, economía circular, tratamiento de aguas residuales, reciclaje inclusivo, producción verde, agricultura urbana y soberanía alimentaria del municipio de La Paz, promoviendo reducción, separación en origen, aprovechamiento, valorización, disposición adecuada, inclusión digna de recicladores, innovación ambiental y corresponsabilidad ciudadana además de la consolidación de los sistemas alimentarios. ===== PÁGINA 315 ===== 315', 'Dirige la gestión integral de residuos sólidos: recolección, transporte, tratamiento y disposición final. || Impulsa la economía circular, el reciclaje inclusivo y la separación en origen. || Promueve compostaje, agricultura urbana, huertos comunitarios y soberanía alimentaria. || Coordina el tratamiento de aguas residuales y la producción verde. || Incluye a recicladores de base en las cadenas de reciclaje y programas municipales. || Supervisa la calidad y cobertura del servicio de aseo urbano con operadores y empresas.', 'residuos sólidos, basura, aseo urbano, recolección de basura, reciclaje, economía circular, separación en origen, compostaje, recicladores, relleno sanitario, disposición final, aguas residuales, producción verde, agricultura urbana, huertos comunitarios, soberanía alimentaria, contenedores, botaderos, residuos orgánicos, valorización de residuos');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (128, 'UGIRS', 'UNIDAD DE GESTIÓN INTEGRAL DE RESIDUOS SÓLIDOS', 'OPERATIVO', 'SMCVE', 'EJE-09', 'Gestionar técnica y operativamente la planificación, seguimiento y mejora de la gestión integral de residuos sólidos municipales, garantizando calidad, cobertura, eficiencia, continuidad del servicio, disposición adecuada, reducción de impactos ambientales y corresponsabilidad ciudadana.', 'Planifica y hace seguimiento a la gestión integral de residuos sólidos municipales. || Controla la recolección, transporte, tratamiento, aprovechamiento y disposición final de la basura. || Coordina con operadores (aseo urbano) la mejora de cobertura, frecuencia y rutas del servicio. || Identifica puntos críticos de acumulación de basura, microbasurales y zonas con déficit de atención. || Elabora indicadores y reportes de generación, recolección, reclamos y calidad del servicio. || Apoya proyectos de residuos industriales, peligrosos y especiales, y de cierre y saneamiento de sitios.', 'residuos sólidos, basura, aseo urbano, recolección de basura, carro basurero, botadero, relleno sanitario, reciclaje, puntos críticos de basura, microbasurales, recojo de residuos, disposición final, residuos peligrosos, escombros, contenedores, barrido de calles, rutas de recolección, tratamiento de residuos, limpieza urbana, residuos especiales, sabenpe');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (129, 'UECRI', 'UNIDAD DE ECONOMÍA CIRCULAR Y RECICLAJE INCLUSIVO', 'OPERATIVO', 'SMCVE', 'EJE-09', 'Diseñar e implementar programas y proyectos de economía circular, tratamiento de aguas residuales y reciclaje inclusivo, promoviendo la reducción, reutilización, separación, aprovechamiento y valorización de residuos, con participación de recicladores de base, ciudadanía, sector privado, unidades educativas, mercados y emprendimientos sostenibles.', 'Implementa programas de economía circular, reciclaje inclusivo y valorización de residuos. || Instala puntos verdes, centros de acopio y rutas diferenciadas de recolección de reciclables. || Promueve la separación en origen en hogares, colegios, mercados e instituciones. || Coordina con recicladores de base su inclusión digna, formalización, capacitación y mejora de condiciones. || Desarrolla campañas de educación sobre reutilización, compostaje y consumo responsable. || Gestiona el aprovechamiento de residuos, incluyendo escombros de construcción y demolición y el tratamiento de aguas residuales.', 'economía circular, reciclaje inclusivo, recicladores de base, puntos verdes, centros de acopio, separación en origen, material reciclable, compostaje, valorización de residuos, aguas residuales, residuos de construcción, escombros, recolección diferenciada, consumo responsable, reutilización, campañas de reciclaje, acopio de materiales, combustible derivado de residuos, educación ambiental');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (130, 'UASA', 'UNIDAD DE AGRICULTURA Y SOBERANÍA ALIMENTARIA', 'OPERATIVO', 'SMCVE', 'EJE-09', 'Diseñar e implementar programas y proyectos de agricultura urbana, periurbana y rural, huertos comunitarios, soberanía alimentaria, compostaje, producción agrícola sostenible, educación alimentaria y articulación con mercados agrícolas locales, contribuyendo a mejorar seguridad alimentaria, resiliencia climática, economía local y cultura ambiental en el municipio de La Paz.', 'Diseña e implementa programas de agricultura urbana, periurbana y rural y huertos comunitarios, familiares y barriales. || Brinda asistencia técnica, capacitación y acompañamiento a familias, productores y organizaciones vecinales. || Implementa compostaje y aprovechamiento de residuos orgánicos para producir abonos. || Articula a los productores con mercados, ferias y circuitos cortos para la economía popular. || Promueve la soberanía y seguridad alimentaria y la educación alimentaria. || Coordina con Subalcaldías la identificación de espacios aptos para huertos y proyectos alimentarios. || Sistematiza información de huertos, productores y producción, y diseña indicadores de seguridad alimentaria.', 'agricultura urbana, huertos, huerto comunitario, soberania alimentaria, seguridad alimentaria, compostaje, abono organico, produccion agricola, agroecologia, semillas, productores, ferias agricolas, residuos organicos, educacion alimentaria, asistencia tecnica agricola, huerto familiar, agricultura periurbana, economia popular, circuitos cortos');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (131, 'SAF', 'SECCIÓN ADMINISTRATIVA FINANCIERA', 'OPERATIVO', 'SAF', 'TERRITORIAL', 'Procesar y ejecutar la gestión administrativa y financiera de su área organizacional, referida a los Sistemas de Administración y Control Gubernamentales, aplicando las disposiciones emanadas por los Órganos Rectores y normativa específica emitida por las instancias responsables en el Gobierno Autónomo Municipal de La Paz.', 'Revisar y verificar la consistencia y coherencia de la información y datos registrados en el Sistema de Inversión Municipal (SIM) relativos al área organizacional de acuerdo a normativa vigente. || Actualizar, coordinar y registrar la información del Seguimiento y Evaluación al Plan Operativo Anual. || Solicitar y registrar las modificaciones presupuestarias referidas a reformulados y traspasos en coordinación con las unidades solicitantes, de acuerdo a normativa vigente. || Ejecutar, verificar la consistencia y efectuar el seguimiento de la ejecución presupuestaria de gastos y recursos, otorgando información oportuna a la Máxima Autoridad de su Dirección Administrativa para la toma de decisiones. || Coadyuvar con las autoridades y personal que interviene en los procesos de ejecución de gastos, garantizando la correcta aplicación de las partidas por objeto del gasto, cumpliendo con los parámetros establecidos en el Clasificador Presupuestario, considerado en la Formulación del Presupuesto Institucional y sus modificaciones presupuestarias (instrumento normativo emitido por el Órgano Rector). || Verificar el adecuado registro de las operaciones financieras, presupuestarias y patrimoniales en el Sistema de Gestión Pública (SIGEP) en el marco de la Ley Nº 1178 de Administración y Control Gubernamentales y disposiciones reglamentarias emitidas por la Dirección de Finanzas. || Socializar y dar cumplimiento a los instructivos de la Dirección de Finanzas en aplicación a normativa tributaria emitida por Servicio de Impuestos Nacionales, que son de aplicación y cumplimiento obligatorio por las Unidades Ejecutoras y Unidades Recaudadoras de las Direcciones Administrativas.', NULL);
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (132, 'SL', 'SECCIÓN LEGAL', 'OPERATIVO', 'SL', 'TERRITORIAL', 'Asesorar legal y jurídicamente al despacho del Subalcalde y las áreas y unidades organizacionales dependientes de la Subalcaldía y efectuar acciones para el cumplimiento del ordenamiento jurídico administrativo.', 'Realizar el seguimiento a los procesos judiciales, administrativos, coactivos y de otra índole, cuando la Subalcaldía sea parte procesal, en coordinación con la Dirección de Asuntos Jurídicos. || Proyectar y/o emitir Resoluciones Administrativas Macrodistritales sobre Recursos de Revocatoria en el ámbito de su competencia, de acuerdo a lo establecido en normativa vigente. || Proyectar y/o emitir Resoluciones Administrativas Macrodistritales Sancionatorias en el marco de la normativa municipal vigente. || Proyectar y/o emitir Resoluciones Administrativas Macrodistritales para la administración de su jurisdicción territorial en el marco de la normativa vigente. || Atender Oficios y Requerimientos Fiscales en coordinación con las áreas y unidades organizacionales correspondientes y con la Dirección de Asuntos Jurídicos. || Proyectar la Orden de Demolición conforme los lineamientos normativos establecidos, en los casos que corresponda. || Proyectar la Orden de Ejecución de la Obligación de Hacer, cuando corresponda. || Verificar la correcta aplicación de la normativa nacional y municipal vigente, así como de los instrumentos administrativos y de relacionamiento y comunicación propios de la institución. || Gestionar y coordinar con la Dirección de Asuntos Jurídicos, la presentación de denuncias por agresiones de toda índole a servidores públicos municipales de la Subalcaldía. || Emitir fotocopias legalizadas de documentos que se encuentren bajo su custodia. || Revisar que los contratos de obras, bienes y servicios, así como otros instrumentos relacionados con procesos de contratación, puestos a su conocimiento, se encuentren en el marco de la normativa vigente. || Coordinar con las áreas y unidades organizacionales de la Subalcaldía, la instauración de procesos de ejecución de cobro coactivo, de acuerdo a lo establecido en normativa vigente. || Otras que le sean asignadas por la autoridad superior.', NULL);
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (133, 'SDI', 'SECCIÓN DE DESARROLLO INTEGRAL', 'OPERATIVO', 'SDI', 'TERRITORIAL', 'Promover el desarrollo económico local y de emprendimiento de la población, articulando acciones con los distintos actores económicos de su jurisdicción territorial, así como promover el desarrollo humano a través de acciones y actividades en los ámbitos de educación, salud, cultura, deportes, cultura ciudadana, interculturalidad, seguridad ciudadana, medio ambiente y derechos ciudadanos en el marco de las políticas definidas por las instancias competentes, de manera concertada con actores sociales, público y privado.', 'Gestionar acciones para facilitar el intercambio y la comunicación entre actores sociales públicos y privados para la definición de acciones encaminadas a promover las inversiones en su jurisdicción territorial. || Coordinar acciones para facilitar el encuentro entre productores, comercializadores y demandantes de productos de generación local, para fomentar el desarrollo económico local, en espacios públicos municipales. || Coordinar acciones para la promoción de la industria, la pequeña industria y la artesanía en su jurisdicción territorial, con la Secretaría Municipal de Ciudad Productiva. || Coordinar con las áreas y unidades organizacionales involucradas, la ejecución de proyectos de inversión para la promoción del desarrollo humano. || Ejecutar planes y proyectos de desarrollo de los servicios de educación, salud, cultura, deportes, cultura ciudadana, interculturalidad, seguridad ciudadana, medio ambiente y derechos ciudadanos correspondientes a su jurisdicción territorial, en coordinación con las instancias competentes. || Efectuar la dotación de materiales e insumos a unidades educativas correspondientes a su jurisdicción territorial, en coordinación con la instancia correspondiente, de acuerdo a la asignación del Fondo de Atención Ciudadana.', NULL);
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (134, 'CMAC', 'COORDINACIÓN MACRODISTRITAL', 'EJECUTIVO', 'CMAC', 'TERRITORIAL', 'Coordinar la planificación, ejecución y seguimiento de las acciones de infraestructura, mantenimiento, respuesta inmediata y fiscalización territorial, en el marco de las políticas institucionales y de manera concertada con actores sociales, públicos y privados.', 'Promover, facilitar y coordinar la participación ciudadana de su jurisdicción territorial, canalizando las demandas y criterios de las Organizaciones Sociales Territoriales en la elaboración de su Plan Operativo Anual (POA). || Elaborar y coordinar con las áreas y unidades organizacionales de la Subalcaldía, la formulación, seguimiento, evaluación, ajuste y reformulación del Plan Operativo Anual (POA) y Presupuesto. || Elaborar el proyecto de presupuesto de la Subalcaldía y sus modificaciones en coordinación con las áreas y unidades organizacionales de la Subalcaldía, así como con la Dirección de Planificación, Reforma Institucional y Gestión por Resultados y la Dirección de Finanzas.', NULL);
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (135, 'UI', 'UNIDAD DE INFRAESTRUCTURA', 'OPERATIVO', 'UI', 'TERRITORIAL', 'Efectuar el mejoramiento de la infraestructura y equipamiento urbano y social, en coordinación con los actores sociales de su jurisdicción territorial.', 'Formula, ejecuta y supervisa proyectos de construcción y mejoramiento de infraestructura urbana y social en su jurisdicción. || Elabora informes técnicos de condiciones previas y estudios de diseño técnico de preinversión. || Supervisa las obras del macrodistrito e informa su avance físico y administrativo a la Coordinación Macrodistrital. || Coordina el uso de maquinaria con la Unidad de Mantenimiento y Respuesta Inmediata según el presupuesto de su Subalcaldía. || Identifica necesidades de servicios básicos en propiedad municipal para los proyectos de mejoramiento. || Verifica fichas de inversión en el Sistema de Inversión Municipal (SIM) y emite informes de ejecución del POA.', 'infraestructura, obras, equipamiento urbano, proyecto de inversión, construcción, mejoramiento barrial, preinversión, diseño técnico, supervisión de obra, avance de obra, maquinaria, sistema de inversión municipal, sim, ficha de inversión, poa, obra menor, equipamiento social, servicios básicos, coordinación macrodistrital, estudio técnico');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (136, 'UMRI', 'UNIDAD DE MANTENIMIENTO Y RESPUESTA INMEDIATA', 'OPERATIVO', 'UMRI', 'TERRITORIAL', 'Efectuar el mantenimiento de infraestructura y equipamiento urbano y social de su jurisdicción territorial mediante administración directa.', 'Ejecuta el mantenimiento de infraestructura urbana y social de su macrodistrito por administración directa. || Mantiene infraestructura de salud, educación, deportes, seguridad ciudadana y mercados. || Prioriza zonas de intervención y planifica las tareas de mantenimiento en su jurisdicción. || Mantiene y mejora áreas verdes, parques integrales y espacios de recreación locales. || Programa y supervisa el uso de maquinaria en coordinación con la entidad de maquinaria y equipo. || Realiza la evaluación técnica preliminar de emergencias y da respuesta inmediata.', 'mantenimiento, respuesta inmediata, administración directa, infraestructura urbana, infraestructura social, reparación, maquinaria, obras menores, macrodistrito, emergencia barrial, bacheo, áreas verdes, parques integrales, espacios de recreación, mercados, mantenimiento de escuelas, cuadrilla, intervención rápida, equipamiento urbano, limpieza');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (137, 'UFT', 'UNIDAD DE FISCALIZACIÓN TERRITORIAL', 'OPERATIVO', 'UFT', 'TERRITORIAL', 'Ejercer la fiscalización del territorio, verificando el cumplimiento de la normativa vigente relacionada a la planificación, el ordenamiento y la administración territorial, aplicando las medidas correctivas y precautorias, estableciendo acciones de prevención, identificando la comisión de las infracciones y determinando las sanciones correspondientes, protegiendo la propiedad municipal de forma coordinada e integral.', 'Fiscaliza el territorio verificando que las construcciones cumplan las normas de uso de suelo y edificación. || Hace seguimiento e inspecciones a construcciones con permiso y detecta las que incumplen. || Emite certificaciones de cumplimiento de norma y de inexistencia de procesos de fiscalización. || Ejecuta controles contra avasallamientos y movimientos de suelo para proteger la propiedad municipal. || Aplica medidas correctivas, precautorias y sanciones a las infracciones territoriales. || Registra los procesos de fiscalización en el Sistema de Información Territorial.', 'fiscalización territorial, uso de suelo, construcción sin permiso, avasallamiento, movimiento de suelo, inspección, certificación de norma, edificación, sanción, medida precautoria, clausura, propiedad municipal, infracción, loteamiento, permiso de construcción, control predial, denuncia de construcción, sistema de información territorial, protección municipal');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (138, 'SAF', 'SECCIÓN ADMINISTRATIVA FINANCIERA', 'OPERATIVO', 'SAF', 'TERRITORIAL', 'Procesar y ejecutar la gestión administrativa y financiera de su área organizacional, referida a los Sistemas de Administración y Control Gubernamentales, aplicando las disposiciones emanadas por los Órganos Rectores y normativa específica emitida por las instancias responsables en el Gobierno Autónomo Municipal de La Paz.', 'Revisar y verificar la consistencia y coherencia de la información y datos registrados en el Sistema de Inversión Municipal (SIM) relativos al área organizacional de acuerdo a normativa vigente. || Actualizar, coordinar y registrar la información del Seguimiento y Evaluación al Plan Operativo Anual. || Solicitar y registrar las modificaciones presupuestarias referidas a reformulados y traspasos en coordinación con las unidades solicitantes, de acuerdo a normativa vigente. || Ejecutar, verificar la consistencia y efectuar el seguimiento de la ejecución presupuestaria de gastos y recursos, otorgando información oportuna a la Máxima Autoridad de su Dirección Administrativa para la toma de decisiones. || Coadyuvar con las autoridades y personal que interviene en los procesos de ejecución de gastos, garantizando la correcta aplicación de las partidas por objeto del gasto, cumpliendo con los parámetros establecidos en el Clasificador Presupuestario, considerado en la Formulación del Presupuesto Institucional y sus modificaciones presupuestarias (instrumento normativo emitido por el Órgano Rector). || Verificar el adecuado registro de las operaciones financieras, presupuestarias y patrimoniales en el Sistema de Gestión Pública (SIGEP) en el marco de la Ley Nº 1178 de Administración y Control Gubernamentales y disposiciones reglamentarias emitidas por la Dirección de Finanzas. || Socializar y dar cumplimiento a los instructivos de la Dirección de Finanzas en aplicación a normativa tributaria emitida por Servicio de Impuestos Nacionales, que son de aplicación y cumplimiento obligatorio por las Unidades Ejecutoras y Unidades Recaudadoras de las Direcciones Administrativas. || Socializar y dar cumplimiento con las actividades y plazos establecidos en el Instructivo para el Cierre Presupuestario, Contable y de Tesorería de la Gestión Fiscal correspondiente, en coordinación con el', NULL);
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (139, 'CMAC', 'COORDINACIÓN MACRODISTRITAL', 'EJECUTIVO', 'CMAC', 'TERRITORIAL', 'Coordinar la planificación, ejecución y seguimiento de las acciones, para implementar la planificación integral del desarrollo territorial de su jurisdicción, cumpliendo los objetivos, acciones estratégicas institucionales y metas propuestas en la gestión de la Subalcaldía.', 'Promover, facilitar y coordinar la participación ciudadana de su jurisdicción territorial, canalizando las demandas y criterios de las Organizaciones Sociales Territoriales en la elaboración de su Plan Operativo Anual (POA). || Elaborar y coordinar con las áreas y unidades organizacionales de la Subalcaldía, la formulación, seguimiento, evaluación, ajuste y reformulación del Plan Operativo Anual (POA) y Presupuesto.', NULL);
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (140, 'UMMRI', 'UNIDAD DE MEJORAMIENTO, MANTENIMIENTO Y RESPUESTA INMEDIATA', 'OPERATIVO', 'UMMRI', 'TERRITORIAL', 'Efectuar el mejoramiento y mantenimiento de la infraestructura y equipamiento urbano - rural, en coordinación con los actores sociales de su jurisdicción territorial.', 'Ejecuta obras de mejoramiento y mantenimiento de infraestructura y equipamiento en su macrodistrito. || Planifica y opera el uso de maquinaria municipal según el presupuesto de la Subalcaldía. || Da respuesta inmediata a necesidades barriales y coordina el retiro de escombros. || Ejecuta el mantenimiento del alumbrado público local junto con la Dirección de Barrios y Vías. || Realiza obras con contraparte de acción comunal, aportando materiales a los vecinos. || Supervisa las obras ejecutadas e informa el avance físico y administrativo a la Subalcaldía.', 'mantenimiento, mejoramiento barrial, respuesta inmediata, maquinaria, retiro de escombros, alumbrado público, obras menores, acción comunal, equipamiento urbano, infraestructura barrial, reparación, emergencia barrial, supervisión de obras, dotación de materiales, servicios básicos, obra por administración, arreglo de calles');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (141, 'UFTPM', 'UNIDAD DE FISCALIZACIÓN TERRITORIAL Y PROTECCIÓN MUNICIPAL', 'OPERATIVO', 'UFTPM', 'TERRITORIAL', 'Ejercer la fiscalización del territorio, verificando el cumplimiento de la normativa vigente relacionada a la planificación, el ordenamiento y la administración territorial, aplicando las medidas correctivas y precautorias, estableciendo acciones de prevención, identificando la comisión de las infracciones y determinando las sanciones correspondientes, protegiendo la propiedad municipal de forma coordinada e integral.', 'Fiscaliza el territorio verificando el cumplimiento de la normativa de uso de suelo y ordenamiento. || Identifica infracciones, aplica medidas correctivas y precautorias y determina sanciones. || Elabora mapas temáticos y planos georreferenciados de equipamientos y jurisdicciones. || Protege la propiedad municipal y verifica linderos entre comunidades. || Atiende solicitudes de registro catastral y de Áreas de Tratamiento Especial.', 'fiscalización territorial, uso de suelo, avasallamientos, asentamientos ilegales, propiedad municipal, linderos, mapas georreferenciados, catastro, infracciones, sanciones territoriales, medidas precautorias, áreas de equipamiento, áreas de tratamiento especial, ordenamiento territorial, protección municipal, loteamientos, deslindes, planos temáticos');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (142, 'UDPT', 'UNIDAD DE DESARROLLO PRODUCTIVO Y TURISMO', 'OPERATIVO', 'UDPT', 'TERRITORIAL', 'Promover el desarrollo de las vocaciones de su jurisdicción territorial, orientado al desarrollo y promoción económica y productiva, con el fin de fortalecer las potencialidades de las comunidades y generar mejores condiciones económicas para los pobladores.', 'Elabora y ejecuta proyectos productivos en las comunidades del distrito. || Promueve el turismo, la industria, la pequeña industria, la artesanía y la agricultura en su jurisdicción. || Capacita a los agentes económicos locales. || Realiza campañas de sanidad animal y seguridad alimentaria. || Coordina la protección de recursos naturales y opciones productivas sostenibles.', 'desarrollo productivo, turismo local, proyectos productivos, artesanía, pequeña industria, agricultura, sanidad animal, seguridad alimentaria, capacitación productiva, agentes económicos, producción comunitaria, turismo comunitario, emprendimientos locales, recursos naturales, vocaciones productivas, ferias distritales, producción sostenible');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (143, 'HM', 'HOSPITALES MUNICIPALES', 'EJECUTIVO (DESCONCENTRADO)', 'HM', 'EJE-02', 'Brindar servicios de salud accesibles a la población, con calidad, seguridad, calidez, eficiencia, confiabilidad, confidencialidad y empatía; con infraestructura, equipamiento, medicamentos, suministros y recurso humano especializado, apropiados para la atención integral con promoción y prevención, gestión de asesoramiento técnico, docencia e investigación y vigilancia epidemiológica, según caracterización de Hospitales y otras especialidades demandadas por la población.', 'Brindar atención médica integral: consulta externa, diagnóstico, tratamiento, internación y rehabilitación con enfoque intercultural. || Ejecutar programas y proyectos municipales de salud y aplicar las políticas de salud del municipio dentro de la Red Funcional de Salud. || Gestionar y ofertar la cartera de servicios de cada hospital según su capacidad resolutiva, infraestructura y equipamiento disponibles. || Realizar acciones de promoción y prevención en salud, vigilancia epidemiológica y respuesta ante emergencias de salud pública, con participación ciudadana. || Coordinar la referencia y contrarreferencia de pacientes entre establecimientos de salud de la red. || Impulsar docencia, educación continua e investigación científica en pregrado y posgrado, y generar información para los sistemas de salud (SNIS-VE, SIIS, SICE). || Aplicar protocolos de atención, estándares de calidad y medidas de seguridad laboral para usuarios internos y externos.', 'hospital, hospital municipal, atención médica, emergencia médica, consulta externa, internación, diagnóstico, tratamiento, rehabilitación, ambulancia, farmacia municipal, medicamentos, salud, vigilancia epidemiológica, promoción y prevención, referencia y contrarreferencia, red de salud, atención integral, personal médico, equipamiento médico, insumos médicos, protocolos de atención');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (144, 'SETRAM', 'SERVICIO DE TRANSPORTE MUNICIPAL', 'EJECUTIVO (DESCONCENTRADO)', 'SETRAM', 'EJE-08', 'Prestar un servicio público de transporte municipal colectivo de pasajeros, eficiente y seguro, que contribuya a la mejora de la calidad de vida de la población del municipio de La Paz.', 'Administrar y operar el servicio público de transporte municipal colectivo de pasajeros en La Paz. || Programar, ejecutar y controlar las rutas del servicio, asegurando frecuencia, cobertura y continuidad de los buses. || Gestionar el mantenimiento preventivo y correctivo de la flota de buses, la infraestructura y el equipamiento tecnológico. || Garantizar la seguridad, transparencia y trazabilidad del sistema de recaudo en efectivo y electrónico. || Coadyuvar en la implementación del Sistema Integrado de Transporte y aplicar acciones de movilidad municipal. || Informar a la ciudadanía sobre la operación del servicio mediante canales digitales y elaborar planes de contingencia.', 'transporte municipal, buses, bus municipal, pumakatari, chikititi, transporte colectivo, pasajeros, rutas, paradas, frecuencia, flota de buses, mantenimiento de buses, recaudo, tarjeta de transporte, pago electrónico, movilidad, sistema integrado de transporte, servicio de transporte, cobertura de rutas, planes de contingencia');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (145, 'BMVP', 'BIOPARQUE MUNICIPAL VESTY PAKOS', 'EJECUTIVO (DESCONCENTRADO)', 'BMVP', 'EJE-09', 'Constituir un centro de custodia de fauna nativa referente a nivel local y regional, comprometido con el bienestar animal y la conservación, impulsando mejoras continuas en sus prácticas de manejo, de rehabilitación y de reinserción de fauna silvestre, diseñando e implementando programas para la conservación ex situ e in situ de especies amenazadas, promoviendo la investigación científica y la educación, generando consciencia ambiental, revalorizando los saberes culturales y forjando sentimientos de pertenencia en la sociedad.', 'Administrar el zoológico municipal y ejecutar planes de ampliación y mantenimiento de la infraestructura del Bioparque Vesty Pakos. || Promover la conservación de fauna silvestre amenazada, tanto ex situ como in situ, y contribuir a la recuperación de sus poblaciones. || Proporcionar a los animales albergados condiciones de habitabilidad y espacios que recreen su hábitat natural. || Dar manejo técnico y especializado a la fauna silvestre derivada por las autoridades competentes, según protocolos establecidos. || Implementar los programas del Plan de Manejo 2020-2030 y promover la investigación científica, la educación y la conciencia ambiental.', 'zoológico, bioparque, vesty pakos, mallasa, animales, fauna, fauna silvestre, bienestar animal, conservación, conservación ex situ, conservación in situ, especies amenazadas, rehabilitación de fauna, hábitat, custodia de fauna, educación ambiental, investigación científica, manejo animal, recintos, veterinaria');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (146, 'ATM', 'ADMINISTRACIÓN TRIBUTARIA MUNICIPAL', 'EJECUTIVO (DESCONCENTRADO)', 'ATM', 'EJE-01', 'Administrar el sistema de gestión tributaria municipal, optimizar la recaudación y el registro en el Padrón Municipal de Contribuyentes, mediante la planificación, organización y ejecución de mecanismos y procesos de actualización de datos, control de obligaciones fiscales, fiscalización y orientación al contribuyente para facilitar el cumplimiento del pago voluntario correcto y oportuno de la obligación tributaria, prestando servicios con calidad y calidez; así como, ejecutar las acciones de cobranza coactiva, sancionatoria y acciones legales para la recuperación de la deuda tributaria municipal, en el marco de la normativa tributaria vigente.', 'Administrar el sistema de gestión tributaria municipal y optimizar la recaudación de tributos municipales. || Gestionar el registro y actualización del Padrón Municipal de Contribuyentes (empadronamiento). || Realizar el control de obligaciones fiscales, la fiscalización y la orientación al contribuyente para el pago voluntario y oportuno. || Ejecutar la cobranza coactiva, sancionatoria y las acciones legales para recuperar la deuda tributaria municipal. || Proyectar y emitir normativa tributaria (leyes, decretos y resoluciones administrativas) y establecer guías y procedimientos técnicos. || Administrar los sistemas tributarios vinculados a tasas, patentes, facilidades de pago y control fiscal.', 'impuesto, impuestos, pago de impuestos, tributo, patente, tasas, contribuyente, padrón de contribuyentes, empadronamiento, catastro, bienes inmuebles, vehículos, impuesto a inmuebles, impuesto a vehículos, cobranza coactiva, deuda tributaria, fiscalización, recaudación, facilidades de pago, obligación tributaria, administración tributaria');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (147, 'SIREMU', 'SISTEMA DE REGULACIÓN Y SUPERVISIÓN MUNICIPAL', 'EJECUTIVO (DESCONCENTRADO)', 'SIREMU', 'EJE-01', 'Supervisar, controlar y regular la ejecución de los contratos concesionados y servicios públicos municipales delegados a terceros, ejerciendo el cumplimiento de las condiciones contractualmente establecidas; y establecer políticas para la adecuada fiscalización de obras ejecutadas por empresas de servicios públicos y administrar los servicios públicos municipales asignados; aplicando principios de seguridad jurídica, transparencia, eficacia, eficiencia y calidad.', 'Regular, supervisar y controlar los servicios públicos municipales concesionados o delegados a terceros. || Fiscalizar el cumplimiento de las condiciones contractuales de las concesiones y establecer mecanismos de regulación técnica, económica y financiera. || Supervisar los contratos del servicio de Alimentación Complementaria Escolar (desayuno escolar). || Regular y controlar los contratos del servicio de aseo urbano concesionado o delegado. || Regular y controlar los contratos de tratamiento y disposición final de residuos sólidos en el relleno sanitario.', 'regulación, supervisión, concesión, concesionario, servicios públicos municipales, contratos concesionados, fiscalización de servicios, alimentación complementaria escolar, desayuno escolar, aseo urbano, recojo de basura, residuos sólidos, relleno sanitario, disposición final, tratamiento de residuos, servicios delegados, regulación tarifaria, control de servicios');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (148, 'CMF', 'CENTRO MUNICIPAL DE FAENO', 'EJECUTIVO (DESCONCENTRADO)', 'CMF', 'EJE-04', 'Administrar el servicio de faenado de ganado bovino y refrigeración de piezas de carne, además de procesar sub productos de la actividad de faeno, brindando de esta manera servicios suplementarios para la producción de insumos agropecuarios para la ciudad de La Paz y municipios colindantes, cumpliendo la normativa vigente en lo referente a manejo adecuado del proceso industrial del Centro Municipal de Faeno.', 'Administrar el servicio de faenado de ganado bovino y, en casos de excepción autorizados por el SENASAG, de ganado porcino. || Prestar servicios de refrigeración de piezas de carne y procesado de subproductos del faeno. || Garantizar el mantenimiento integral de la infraestructura y maquinaria del Centro Municipal de Faeno, y gestionar mejoras y adquisiciones de equipos. || Elaborar planes y proyectos para el manejo de residuos sólidos y líquidos provenientes de la actividad de faeno. || Remitir reportes mensuales de servicios prestados, ingresos percibidos y procedencia del ganado (guías de movimiento) a las instancias correspondientes y al SENASAG. || Implementar y cumplir la normativa vigente de sanidad e inocuidad para el faenado.', 'faeneo, faenado, matadero, ganado bovino, ganado porcino, carne, refrigeración de carne, subproductos, sanidad animal, inocuidad alimentaria, senasag, guías de movimiento, procedencia del ganado, residuos del faeno, insumos agropecuarios, centro de faeneo, sacrificio de ganado, piezas de carne');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (149, 'SACO', 'SUBALCALDÍA COTAHUMA', 'SUBALCALDÍA', 'SACO', 'TERRITORIAL', NULL, 'Atiende las demandas y trámites vecinales del macrodistrito Cotahuma. || Ejecuta obras menores, mantenimiento barrial y mejoramiento de vías y espacios públicos locales. || Realiza limpieza, mantenimiento de áreas verdes y arbolado en el macrodistrito. || Coordina ferias, actividades vecinales y atención de emergencias barriales. || Da mantenimiento a la infraestructura pública local: graderías, muros, aceras y drenajes. || Canaliza las solicitudes vecinales hacia las instancias municipales competentes.', 'subalcaldía cotahuma, macrodistrito cotahuma, atención vecinal, obras menores, mantenimiento barrial, limpieza de calles, áreas verdes cotahuma, ferias vecinales, emergencias barriales, trámites vecinales, graderías, muros de contención, aceras, drenaje pluvial, vecinos cotahuma, bacheo, mantenimiento de vías, juntas vecinales');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (150, 'SAMP', 'SUBALCALDÍA MAXIMILIANO PAREDES', 'SUBALCALDÍA', 'SAMP', 'TERRITORIAL', NULL, 'Atiende a los vecinos del macrodistrito Maximiliano Paredes y canaliza sus trámites y solicitudes. || Ejecuta el mantenimiento barrial y obras menores: bacheo, aceras, cordones, cunetas, graderías y muros. || Realiza la limpieza, mantenimiento de áreas verdes y jardines locales del macrodistrito. || Organiza y controla ferias, uso de espacios públicos y actividades vecinales del distrito. || Atiende emergencias barriales (deslizamientos, aguas, escombros) en coordinación con las instancias de riesgo. || Coordina obras y mantenimiento vial local con las direcciones especializadas del GAMLP.', 'subalcaldia maximiliano paredes, macrodistrito maximiliano paredes, atencion vecinal, tramites vecinales, mantenimiento barrial, obras menores, bacheo, aceras, cordones y cunetas, graderias, muro de contencion, areas verdes, limpieza, ferias, emergencias barriales, vecinos, junta vecinal, escombros, mantenimiento vial local, espacios publicos');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (151, 'SAP', 'SUBALCALDÍA PERIFÉRICA', 'SUBALCALDÍA', 'SAP', 'TERRITORIAL', NULL, 'Representa al Gobierno Municipal en el macrodistrito Periférica y atiende las demandas vecinales del territorio. || Ejecuta y supervisa obras menores, mantenimiento barrial y mejoramiento de vías y espacios públicos del macrodistrito. || Coordina la limpieza, el manejo de áreas verdes locales y el barrido de calles del distrito. || Atiende trámites vecinales, juntas de vecinos y solicitudes de la comunidad Periférica. || Organiza y controla ferias, actividades barriales y el uso de espacios públicos locales. || Responde a emergencias barriales y coordina la respuesta inmediata en el macrodistrito.', 'subalcaldía periférica, macrodistrito periférica, periférica, atención vecinal, junta de vecinos, obras menores, mantenimiento barrial, bacheo, limpieza de calles, áreas verdes, ferias barriales, trámite vecinal, emergencia barrial, espacios públicos, cordones y aceras, graderías, adoquinado, vecinos, barrio, distrito, mantenimiento de vías');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (152, 'SASA', 'SUBALCALDÍA SAN ANTONIO', 'SUBALCALDÍA', 'SASA', 'TERRITORIAL', NULL, 'Administra el territorio del Macrodistrito San Antonio y atiende las demandas vecinales. || Ejecuta obras menores y trabajos de mantenimiento barrial en calles, aceras y espacios públicos. || Realiza limpieza, cuidado de áreas verdes locales y mantenimiento de plazas y parques del macrodistrito. || Atiende trámites vecinales y canaliza requerimientos hacia las áreas municipales competentes. || Organiza y autoriza ferias, actividades vecinales y usos del espacio público local. || Responde a emergencias barriales y coordina la atención de riesgos en su jurisdicción.', 'san antonio, subalcaldía san antonio, macrodistrito san antonio, atención vecinal, mantenimiento barrial, obras menores, limpieza, áreas verdes, ferias, trámites vecinales, emergencia barrial, juntas vecinales, vecinos, aceras, calles, adoquinado, plazas, alumbrado, espacio público, distrito');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (153, 'SAS', 'SUBALCALDÍA SUR', 'SUBALCALDÍA', 'SAS', 'TERRITORIAL', NULL, 'Atiende a los vecinos del macrodistrito Sur y gestiona sus trámites y solicitudes. || Ejecuta obras menores, mantenimiento barrial y mejora de vías y espacios del macrodistrito. || Realiza limpieza, mantenimiento de áreas verdes y cuidado de plazas y parques locales. || Coordina ferias, actividades vecinales y el control del comercio en su jurisdicción. || Atiende emergencias barriales y coordina la respuesta territorial con las unidades competentes. || Da seguimiento a las demandas vecinales y las canaliza a las instancias municipales correspondientes.', 'subalcaldía sur, macrodistrito sur, zona sur, atención vecinal, obras menores, mantenimiento barrial, áreas verdes, limpieza, bacheo, plazas y parques, ferias, emergencia barrial, trámites vecinales, vecinos, junta vecinal, mantenimiento de vías, cordones, graderías, distrital sur, demanda vecinal');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (154, 'SAM', 'SUBALCALDÍA MALLASA', 'SUBALCALDÍA', 'SAM', 'TERRITORIAL', NULL, 'Atiende a los vecinos del macrodistrito Mallasa y resuelve sus trámites y solicitudes locales. || Ejecuta obras menores, mantenimiento barrial y mejora de la infraestructura del macrodistrito. || Realiza limpieza, mantenimiento de áreas verdes y espacios públicos locales. || Organiza y autoriza ferias, actividades vecinales y uso de espacios públicos del macrodistrito. || Coordina la atención de emergencias barriales y necesidades urgentes de la población. || Gestiona el mantenimiento de vías, calles y equipamiento urbano dentro de su jurisdicción.', 'mallasa, subalcaldía mallasa, macrodistrito mallasa, atención vecinal, trámites vecinales, obras menores, mantenimiento barrial, áreas verdes, limpieza, ferias, emergencia barrial, juntas vecinales, espacios públicos, vías locales, vecinos, solicitud vecinal, distrito rural, mantenimiento de calles');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (155, 'SAC', 'SUBALCALDÍA CENTRO', 'SUBALCALDÍA', 'SAC', 'TERRITORIAL', NULL, 'Atiende de forma directa a los vecinos del Macrodistrito Centro y gestiona sus trámites. || Ejecuta obras menores y mantenimiento barrial: aceras, cordones, gradas y vías vecinales. || Coordina la limpieza, el aseo urbano y el cuidado de áreas verdes locales del Centro. || Organiza y controla ferias, actividades vecinales y ocupación de espacios públicos. || Responde a emergencias barriales y coordina la respuesta territorial con las áreas del municipio. || Mantiene plazas, parques y mobiliario urbano del Macrodistrito Centro.', 'subalcaldía centro, macrodistrito centro, atención vecinal, trámites vecinales, obras menores, mantenimiento barrial, aceras, cordones, gradas, limpieza, áreas verdes, plazas, ferias, emergencias barriales, alumbrado, bacheo, espacios públicos, juntas vecinales centro, poda de árboles, mobiliario urbano');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (156, 'SAH', 'SUBALCALDÍA HAMPATURI', 'SUBALCALDÍA', 'SAH', 'TERRITORIAL', NULL, 'Atiende las demandas vecinales y trámites de los pobladores del macrodistrito rural de Hampaturi. || Ejecuta obras menores, mantenimiento barrial y mejoramiento de caminos y accesos rurales. || Gestiona la limpieza, el cuidado de áreas verdes y espacios comunales del macrodistrito. || Apoya ferias, actividades comunitarias y el desarrollo productivo agropecuario local. || Responde a emergencias, riesgos y desastres en las comunidades rurales de Hampaturi. || Coordina con comunidades y organizaciones sociales la atención de necesidades del territorio.', 'hampaturi, subalcaldía hampaturi, macrodistrito rural, atención vecinal, obras menores, mantenimiento barrial, caminos rurales, áreas verdes, limpieza, ferias comunales, trámites vecinales, emergencias, riadas, deslizamientos, comunidades rurales, represa hampaturi, agropecuaria, riesgos y desastres, juntas vecinales, distrito rural');
insert into unidad (id, sigla, nombre, nivel, secretaria, eje, objetivo, funciones, palabras_clave) values (157, 'SAZ', 'SUBALCALDÍA ZONGO', 'SUBALCALDÍA', 'SAZ', 'TERRITORIAL', NULL, 'Atiende las demandas y trámites vecinales del macrodistrito rural de Zongo. || Ejecuta obras menores, mantenimiento de caminos y mejoramiento de infraestructura local. || Coordina limpieza, mantenimiento de áreas verdes y apoyo a comunidades rurales. || Atiende emergencias y desastres naturales en el territorio de Zongo. || Apoya ferias, actividades comunitarias y productivas del macrodistrito. || Canaliza las solicitudes de los pobladores hacia las instancias municipales competentes.', 'subalcaldía zongo, macrodistrito zongo, área rural, atención vecinal, obras menores, mantenimiento de caminos, caminos rurales, emergencias zongo, desastres naturales, comunidades rurales, trámites vecinales, ferias comunitarias, áreas verdes zongo, actividad productiva rural, pobladores zongo, infraestructura rural, riesgos y deslizamientos');
